  ui_story_5070_50700101_15_dialog_content = "「巨像のナビゲーター、そして心を感知する力の主として、\nお助けいただきたいことがございます」",
  ui_story_5070_50700101_16_dialog_content = "今までたくさんお世話になってるリン家商会が、\n今度は私たちの助けを必要としてる…それに報酬もたっぷり出るらしいわよ！",
