  ui_story_5070_50700101_21_dialog_content = "リン家商会の将来に関わる一大事、なんでしょ？\n影ノ街の本部に行かなくてもいいの？",
  ui_story_5070_50700101_22_dialog_content = "それは…リン家にとって双閣港は影ノ街と同じぐらい\n重要な意味を持っている場所だからよ。",
  ui_story_5070_50700101_23_dialog_content = "カレン！？てっきり部屋で本を読んでるのかと思ってたよ！",
  ui_story_5070_50700101_24_dialog_content = "今のところ休暇も残っているから付き合うわ。それに…\nここで双閣港を知っているのは私だけでしょう？",
  ui_story_5070_50700101_25_dialog_content = "白夜城にとって、双閣港と影ノ街の貿易は重要な経済の一部だから。",
