  ui_story_5070_50700101_31_dialog_content = "これほど急いであなたを呼んでいるところを見ると、\n手紙の<color=#FFB400>「商会の将来に関わる」</color>という言葉も決して大げさではないのでしょうね。",
  ui_story_5070_50700101_32_dialog_content = "じゃあ、急いだ方がよさそうだね。",
