  ui_story_5070_50700101_36_dialog_content = "ここが双閣港なの！？本当に不思議ね。\nアストラの雰囲気とはまったく違うわ。",
  ui_story_5070_50700101_37_dialog_content = "まるで別世界の景色を切り取って、貼り付けたみたいだわ。",
