  ui_story_5070_50700101_39_dialog_content = "この地の発展はリン家がけん引したらしいわ。\nさらにリン家が航路を開くと、海を渡ってくる人たちも増えて…",
  ui_story_5070_50700101_40_dialog_content = "多くの龍州人が定住したの。",
  ui_story_5070_50700101_41_dialog_content = "それで、アストラにあるのに龍州の雰囲気がある街になったそうよ。",
  ui_story_5070_50700101_42_dialog_content = "…確かに本で読んだより、ずっと風情があるわね。",
  ui_story_5070_50700101_43_dialog_content = "肉まんだよ～！できたてホカホカのおいしい肉まんだよ！\nお客さん、おひとつどうだい？",
  ui_story_5070_50700101_44_dialog_content = "観光ですかい？だったら、うちのお茶を飲んでってくださいよ。",
  ui_story_5070_50700101_45_dialog_content = "雨前の龍井茶、雲夢湖の銀芽、無量の大葉に丹山の岩茶――\n銘茶と呼ばれるものなら何でもあるよ！",
  ui_story_5070_50700101_46_dialog_content = "いい香りだなぁ。",
  ui_story_5070_50700101_47_dialog_content = "見たことないものばかりだね。\n仕事が終わったら、じっくり見て回らなくちゃ。",
  ui_story_5070_50700101_48_dialog_content = "あ、そうだ。どこに行けば商会の人と会えるんだったっけ？",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>突然風が吹いた</color>",
  ui_story_5070_50700101_50_dialog_content = "あ、手紙が――！！",
