  ui_story_5070_50700101_55_dialog_content = "ただのついでよ。",
  ui_story_5070_50700101_56_dialog_content = "…あれも龍州の特産品なのかな？",
  ui_story_5070_50700101_57_dialog_content = "ここにいらっしゃいましたか！\nすみません、PlayerNameさんでいらっしゃいますね？",
  ui_story_5070_50700101_58_dialog_content = "はい、そうです。リン家のお手伝いに来ました！",
  ui_story_5070_50700101_59_dialog_content = "リン家商会の者です。この度はわざわざありがとうございます。\nでは、さっそく詳しいお話をよろしいでしょうか？",
  ui_story_5070_50700101_60_dialog_content = "リン家商会については、皆さま多少はご存じかと思いますが――",
  ui_story_5070_50700101_61_dialog_content = "私たちはアストラにはない龍州の技術や物産を運び、\nこの大陸各地で売りさばいております。",
  ui_story_5070_50700101_62_dialog_content = "しかし、龍州とアストラは海を隔てているため、\n非常に危険なのです。",
  ui_story_5070_50700101_63_dialog_content = "今でもリン家の船のみが先祖以来の航路をたどり、\n定期的に物資を運ぶため行き来しているのですが…",
  ui_story_5070_50700101_64_dialog_content = "その重要な運搬役の船――蜃風号がどういうわけか、\n半年もの間姿を見せないのです。",
  ui_story_5070_50700101_65_dialog_content = "半年も？まさか龍州で何かあったとか？",
  ui_story_5070_50700101_66_dialog_content = "それは…私たちにも分かりません。",
  ui_story_5070_50700101_67_dialog_content = "二つの大陸間の連絡は目下、リン家の商船だけが頼りなものですから…",
  ui_story_5070_50700101_68_dialog_content = "リン家商会でも、龍州の本家と連絡を取る方法が他にないのね。",
  ui_story_5070_50700101_69_dialog_content = "残念ながら、その通りです。",
