  ui_story_5070_50700101_73_dialog_content = "ただ、こちらが応答する前に、信号が再び消えてしまい…\nそれきりなのです。",
  ui_story_5070_50700101_74_dialog_content = "分かりました。巨像でその船を捜索してほしいということですね？",
  ui_story_5070_50700101_75_dialog_content = "その通りです！こうなっては、あなたの力をお借りするほかありません。",
  ui_story_5070_50700101_76_dialog_content = "分かりました。全力を尽くします。",
