  ui_story_5070_50700101_80_dialog_content = "ただ、この先はさらに遠くを探さないといけないわね。",
  ui_story_5070_50700101_81_dialog_content = "PlayerName、大丈夫？",
  ui_story_5070_50700101_82_dialog_content = "実を言うと、あまり自信がないよ…",
  ui_story_5070_50700101_83_dialog_content = "いきなり遠洋の嵐にでも巻き込まれたら、\n今のソラヴァンじゃ対応できないだろうし…",
  ui_story_5070_50700101_84_dialog_content = "僕も海上飛行は経験不足で、\n遠くてもせいぜい雲島のあたりまでしか行ったことがないから",
  ui_story_5070_50700101_85_dialog_content = "リン家の船がもっと沖で遭難したとしたら、\n救援は難しいかもしれない。",
  ui_story_5070_50700101_86_dialog_content = "…",
  ui_story_5070_50700101_87_dialog_content = "どうして僕を見て黙ってるの？",
  ui_story_5070_50700101_88_dialog_content = "そうね…いつものPlayerNameなら…",
  ui_story_5070_50700101_89_dialog_content = "弱気な言葉の後に必ず「でも」って続くでしょ？",
  ui_story_5070_50700101_90_dialog_content = "2人とも僕を買いかぶりすぎだよ。でも、確かに…",
  ui_story_5070_50700101_91_dialog_content = "まぁ、依頼を引き受けたからには、出来ることは全部やってみるよ。",
  ui_story_5070_50700101_92_dialog_content = "今から海上の出来るだけ広範囲を感知してみるよ。\n何か手がかりが見つかるといいんだけど…",
  ui_story_5070_50700101_93_option_content = "強制感知！",
  ui_story_5070_50700101_94_dialog_content = "風向きをたどって…見つけた！\nあっちの方向にたくさんの光霊がいる！",
  ui_story_5070_50700101_95_dialog_content = "やったわね！これで行方がつかめたわ！",
