  ui_story_5070_50700101_97_dialog_content = "この先の海域は大荒れよ！",
  ui_story_5070_50700101_98_dialog_content = "船が見えた！すごく大きな船だ！",
  ui_story_5070_50700101_99_dialog_content = "リン家の商船ね。",
  ui_story_5070_50700101_100_dialog_content = "急いで助けに行かなきゃ！巨像がどこまで耐えられるか分からないけど…",
  ui_story_5070_50700101_101_dialog_content = "PlayerName、待って。",
  ui_story_5070_50700101_102_dialog_content = "様子をよく見て。",
  ui_story_5070_50700101_103_dialog_content = "船の上にいる人たち…ちょっと緊張はしてるみたいだけど、\n慌ててはいないのかな？",
  ui_story_5070_50700101_104_dialog_content = "甲板にいる人たちが、明確な目標を持って動いてるわね。\n誰かが的確に指示を出してるみたい。",
  ui_story_5070_50700101_105_dialog_content = "せ、船長！そ、空に何かが飛んでいます…",
  ui_story_5070_50700101_106_dialog_content = "集中して。そのまま舷をしっかり引っ張って、\n舵をしっかり取りなさい。",
  ui_story_5070_50700101_107_dialog_content = "海から目を離さないで。",
  ui_story_5070_50700101_108_dialog_content = "一気に突き抜けるわよ！",
  ui_story_5070_50700101_109_dialog_content = "了解です！",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>海面はうねり、大潮が荒々しく押し寄せ、\n巻き上がる波が鼓膜を破りそうな轟音をあげている</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>渦巻く潮が徐々に集まり、さらに恐ろしい勢いで襲い掛かろうとした瞬間、\n船が激しい波をかき分け突き抜けた！</color>",
  ui_story_5070_50700101_112_dialog_content = "よかった！無事に嵐を抜けたわ。",
  ui_story_5070_50700101_113_dialog_content = "ふぅ…",
  ui_story_5070_50700101_114_dialog_content = "ハラハラしたね…心臓が止まるかと思ったよ。",
  ui_story_5070_50700101_115_dialog_content = "あの船長、大したもののようね。",
  ui_story_5070_50700101_116_dialog_content = "船体にたくさん破損した跡がある。\nきっとかなりの荒波にもまれてきたんだね。",
  ui_story_5070_50700101_117_dialog_content = "それなのに、まだ危なげなく航海できてるなんてすごい。",
  ui_story_5070_50700101_118_dialog_content = "この先は天候も安定してるみたいだし、\n事故の心配もなさそうだ。",
  ui_story_5070_50700101_119_dialog_content = "どこかに停泊できるまで、巨像で見守ってあげよう。",
  ui_story_5070_50700101_120_dialog_content = "蜃風だ！蜃風号が来たぞ！",
  ui_story_5070_50700101_121_dialog_content = "何だか今までと違うみたいだぞ！？",
  ui_story_5070_50700101_122_dialog_content = "何を言ってるんだ。今までどおりの蜃風号じゃないか。",
  ui_story_5070_50700101_123_dialog_content = "ほら、数年前にウワサがあったろ。\n鄴（ぎょう）の国の船匠が済の国の船のために最新の機関を造ってるって…",
  ui_story_5070_50700101_124_dialog_content = "この船はきっと性能がアップした新しい船だ！",
  ui_story_5070_50700101_125_dialog_content = "スピードも安定性も耐用性も上がったっていう、\nこの世に二つとない、新しい蜃風号に違いない！",
  ui_story_5070_50700101_126_dialog_content = "す、すごい人だね。",
  ui_story_5070_50700101_127_dialog_content = "商船が港に着くと、町の人たちがおのずと集まって来るのよ。\n一種の儀式のようなものね。",
  ui_story_5070_50700101_128_dialog_content = "あはは…でも、あまりの歓迎ぶりで、\nここからじゃ船も見えないわ。",
  ui_story_5070_50700101_129_dialog_content = "PlayerNameさん！PlayerNameさん！\nここにいらっしゃいましたか！",
  ui_story_5070_50700101_130_dialog_content = "あなたはリン家商会の…",
  ui_story_5070_50700101_131_dialog_content = "はい。ご覧の通り、蜃風号が無事に寄港しました！",
  ui_story_5070_50700101_132_dialog_content = "船長が皆さんに会いたいと申しております。\nどうぞこちらへ。",
  ui_story_5070_50700101_133_dialog_content = "船長？でも、僕たちは何もしてませんよ…",
  ui_story_5070_50700101_134_dialog_content = "そんなことはないわ。",
  ui_story_5070_50700101_135_dialog_content = "蜃風号の船長、ユエよ。",
  ui_story_5070_50700101_136_dialog_content = "伝説の空の末裔にとっては何でもないことだったかもしれないけど、\n蜃風号には大きな助けになったわ。",
  ui_story_5070_50700101_137_dialog_content = "実は半年前、リン家の商船が海で事故に遭って、\n行方知れずになってしまったのよ。",
  ui_story_5070_50700101_138_dialog_content = "リン家が海上で方位の見極めや航路の決定に使っていた天測器――\n渾天儀（こんてんぎ）もその事故でなくなっているの。",
  ui_story_5070_50700101_139_dialog_content = "だから、海図と経験だけを頼りに\n改めて航路を開拓していたところだったのよ。",
  ui_story_5070_50700101_140_dialog_content = "航海中、嵐や暗鬼の襲撃を乗り越えたものの、\n渦巻く潮に飲み込まれた時は本当に危なかったわ。",
  ui_story_5070_50700101_141_dialog_content = "もしあなたの誘導がなかったら…",
  ui_story_5070_50700101_142_dialog_content = "あの渦巻く潮を抜けられたとしても、\n港までの道を探すのに苦労していたことでしょうね。",
  ui_story_5070_50700101_143_dialog_content = "だから、あなた自身は何もしていないと思っていても、\n船を導き、見守ってもらった恩に感謝しているの。",
  ui_story_5070_50700101_144_dialog_content = "リン家商会の決まりでは、リン家への恩には倍返し。\n食客としてお迎えすることになっているわ。",
  ui_story_5070_50700101_145_dialog_content = "双閣港支部で増額分を支払いたくないと言うなら、\n船長の私が代わりにお支払いするわ。",
  ui_story_5070_50700101_146_dialog_content = "コホン！あ、あの…ユエ船長、\nそのようにおっしゃられましても…",
  ui_story_5070_50700101_147_dialog_content = "私どもはアストラの契約習慣に従って事を進めておりますし…\nそれに、いずれの勢力にも身を寄せるような方では無いと聞いております。",
  ui_story_5070_50700101_148_dialog_content = "PlayerNameさん、聞かせて。\nリン家と盟を結ぶ気はないかしら？",
  ui_story_5070_50700101_149_dialog_content = "（ええと？僕の勘違いじゃなければ…\nそれってつまり、リン家の一員になれってことかな？？）",
  ui_story_5070_50700101_150_dialog_content = "ユエ船長、確かに高額な報酬は欲しい所だけど…",
  ui_story_5070_50700101_151_dialog_content = "僕はただ見守ってただけで、大して助けにならなかったことは事実です。\nそれにアストラでは、契約を大事にします。",
  ui_story_5070_50700101_152_dialog_content = "恩があるというなら、僕もリン家には恩があってお互い様だから…",
  ui_story_5070_50700101_153_dialog_content = "こんなにたくさんの報酬は受け取れませんし、\nリン家の一員にもなれません。",
  ui_story_5070_50700101_154_dialog_content = "…",
  ui_story_5070_50700101_155_dialog_content = "ホホホ。ユエ船長は飴と鞭を使い分けがうまい、\n人付き合いが実に巧みじゃと聞いておったが…",
  ui_story_5070_50700101_156_dialog_content = "こんなこともあるのじゃのう。実に面白い。",
  ui_story_5070_50700101_157_dialog_content = "こうしてはどうじゃ？わらわが間に立ち…",
  ui_story_5070_50700101_158_dialog_content = "公子殿とはこの地で受け入れられている方法で、\n船長と友誼を交わすというのはどうじゃ？",
  ui_story_5070_50700101_159_dialog_content = "はい！僕は別に特別な盟約や関係を結びたいわけでは無くて、\nただリン家の皆さんと友達になりたいだけなんです。",
  ui_story_5070_50700101_160_dialog_content = "ユエ船長には巨像を見に来てもらいたいですし、\n代わりに僕も蜃風号を見学させてもらえれば、それで満足です。",
  ui_story_5070_50700101_161_dialog_content = "…蜃風号は大規模な修理が必要なのよ。\n今はお客様を呼ぶにはふさわしくないわ。",
  ui_story_5070_50700101_162_dialog_content = "ただ…タンドウ殿下がそうおっしゃるのなら、\nその通りにいたしましょう。",
  ui_story_5070_50700101_163_dialog_content = "ごめんなさいね、PlayerNameさん。\nさっきは私があまりにも唐突だったわ。",
  ui_story_5070_50700101_164_dialog_content = "気にしないで。それに2人とも、僕のことは呼び捨てでいいよ。",
  ui_story_5070_50700101_165_dialog_content = "蜃風号はここに半月ほど停泊する予定よ。\n色々とやる事があるから、また何かお願いする機会があるかもしれないわ。",
  ui_story_5070_50700101_166_dialog_content = "もちろん、報酬は弾むわ。",
  ui_story_5070_50700101_167_dialog_content = "分かった。人を待たせてるから、今日はこれで失礼するね。\nまた機会を見つけて会おう！",
  ui_story_5070_50700101_168_dialog_content = "お待ちください、ユエ船長。\n蜃風号が半月も停泊するとは聞いておりませんが…",
  ui_story_5070_50700101_169_dialog_content = "それに…色々とやる事があるというのは…",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>バキッ！</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>頭上で大きな音がしたかと思うと、\n船体の板の一枚が突然はがれ、海の中へと落ちていった</color>",
  ui_story_5070_50700101_172_dialog_content = "今のが「やる事」よ。",
  ui_story_5070_50700101_173_dialog_content = "しょ、承知しました…確かに修理が必要ですね。\n後ほど船職人のリーと腕利きのソンをこちらに来させます。",
  ui_story_5070_50700101_174_dialog_content = "ご安心ください。2人とも熟練の職人ですから。\n双閣港での船を整備はいつも彼らに任せています。",
  ui_story_5070_50700101_175_dialog_content = "難しいと思うわ。",
  ui_story_5070_50700101_176_dialog_content = "PlayerNameはまだかしら…？\nまさか取り押さえられたとか？",
  ui_story_5070_50700101_177_dialog_content = "じっとしてられないわ！\n私、様子を見てくる！！",
  ui_story_5070_50700101_178_dialog_content = "ここが双閣港か。",
  ui_story_5070_50700101_179_dialog_content = "大方は龍州の様式じゃが、細部に異国の風情が漂っておる。\n確かにまた違った趣があるのう。",
  ui_story_5070_50700101_180_dialog_content = "キュウ、一回りしてみるか。",
  ui_story_5070_50700101_181_dialog_content = "鄴の国の大人物もしばらく滞在しておるとの話じゃ…",
  ui_story_5070_50700101_182_dialog_content = "おもむきのある所を紹介してくれるかもしれぬ。",
  ui_story_5070_50700101_183_dialog_content = "殿下、長旅でお疲れでございましょう？\n先にしばしお休みになられてはいかがですか？",
  ui_story_5070_50700101_184_dialog_content = "おやおや、キュウさんは情緒ってものを\n分かっていらっしゃらないですねぇ。",
  ui_story_5070_50700101_185_dialog_content = "物見遊山だ、買い物だってのは、\n気の向くままってのが大事なんですよ。",
  ui_story_5070_50700101_186_dialog_content = "僕がお二人にお付き合いするってのはどうです？\n殿下と良い縁のある場所を占って差し上げることもできますしねぇ。",
  ui_story_5070_50700101_187_dialog_content = "ふぅ、疲れたのう。",
  ui_story_5070_50700101_188_dialog_content = "キュウの申す通りじゃ。ユエの所へ戻り休むとしよう。",
  ui_story_5070_50700101_189_dialog_content = "おやおや、殿下…待ってくださいよ！",
  ui_story_5070_50700101_190_dialog_content = "すまぬが、側におく者にはこだわりがあってのう。\n友や義士はもちろん、敵とて構いはせぬのじゃが…",
  ui_story_5070_50700101_191_dialog_content = "人をたばかる者だけは側におかぬことにしておる。",
  ui_story_5070_50700101_192_dialog_content = "そんなことおっしゃらないでくださいよ。\n長い航海を共にした仲じゃございやせんか…",
  ui_story_5070_50700101_193_dialog_content = "（きれいな人だわ…殿下って呼ばれてたけど…？）",
  ui_story_5070_50700101_194_dialog_content = "バイス！バイス！何を見てるの？",
  ui_story_5070_50700101_195_dialog_content = "わあ！やっと戻ってきたのね！",
  ui_story_5070_50700101_196_dialog_content = "何も見てないわ。でも、蜃風号って物だけじゃなくて…",
  ui_story_5070_50700101_197_dialog_content = "いろいろな人も乗せて来たみたいね。\n新しい友だちだって出来るかもしれないわ。",
  ui_story_5070_50700101_198_dialog_content = "こりゃあ参ったな。\n前の蜃風号なら、まだ何とかなったんだが…",
  ui_story_5070_50700101_199_dialog_content = "新しい蜃風号ときたら、炉やら、散熱装置やら防水やら…\n俺たちの知らねえ技術ばっかりだ。",
  ui_story_5070_50700101_200_dialog_content = "鄴のカラクリ部品の山に至っては\nもう手も足も出ねえや。",
  ui_story_5070_50700101_201_dialog_content = "言った通りでしょう？",
  ui_story_5070_50700101_202_dialog_content = "…",
  ui_story_5070_50700101_203_dialog_content = "皆…何をそう憂いておるのじゃ？聞かせてくれぬか？",
  ui_story_5070_50700101_204_dialog_content = "タンドウ殿下！",
  ui_story_5070_50700101_205_dialog_content = "殿下は使命を帯びていらっしゃいます。\nつまらない事で殿下を煩わせるわけには参りません。",
  ui_story_5070_50700101_206_dialog_content = "先刻の仲立ちでまだ腹を立てておるのかのう。",
  ui_story_5070_50700101_207_dialog_content = "お主も知っての通り、\n龍州八諸侯国の間には恩義やら怨恨やらが複雑に入り混じっておる…",
  ui_story_5070_50700101_208_dialog_content = "わらわはこの度こそ済の国使ではあるが、\n鄴から済に送り出された人質であることは変わらぬ。",
  ui_story_5070_50700101_209_dialog_content = "人質である限り、済の国からまことの信を得るは難しきこと…",
  ui_story_5070_50700101_210_dialog_content = "しかし、それ故に自ら望んで海を渡り、\nアストラへ来たのじゃ。",
  ui_story_5070_50700101_211_dialog_content = "行いで己の誠意を証明するためにな。",
  ui_story_5070_50700101_212_dialog_content = "故に、わらわが行うことはすべて、\n済と鄴両国の通商の繁栄と民の安寧のためじゃ。",
  ui_story_5070_50700101_213_dialog_content = "蜃風号はその要となるもの。\nならば、蜃風号の問題はわらわにも一大事であろう？",
  ui_story_5070_50700101_214_dialog_content = "蜃風号のために力を尽くすは当然のことじゃ。",
  ui_story_5070_50700101_215_dialog_content = "…実は…蜃風号の修理のことで…",
  ui_story_5070_50700101_216_dialog_content = "新しい船に使われている機構は鄴の国の最先端技術の粋を集めたもので、\nこれまでの船とは異なるのです。",
  ui_story_5070_50700101_217_dialog_content = "この種の技術を扱う機巧師でなければ、\nおそらく修理は難しいでしょう。",
  ui_story_5070_50700101_218_dialog_content = "材料なら双閣港にいくらでもありますし、船職人も揃っていますが、\n蜃風号の機械を直せる機巧師だけは…",
  ui_story_5070_50700101_219_dialog_content = "ふむ…",
  ui_story_5070_50700101_220_dialog_content = "殿下？",
  ui_story_5070_50700101_221_dialog_content = "他の事なら、わらわも手の貸しようがなかったであろうが…",
  ui_story_5070_50700101_222_dialog_content = "鄴の国のカラクリに通じた機巧師ならば、\nふさわしき者を知っておる。",
  ui_story_5070_50700101_223_dialog_content = "ユエ、蜃風号の修理に取れる時間はいかほどじゃ？",
  ui_story_5070_50700101_224_dialog_content = "半月でございます。",
  ui_story_5070_50700101_225_dialog_content = "十分じゃ。",
  ui_story_5070_50700101_226_dialog_content = "安心せい。鄴の国で最も秀でた機巧師が、双閣港におる。",
  ui_story_5070_50700101_227_dialog_content = "彼女の作った伝言鳥を使えば…すぐにでも見つかるであろう！",
  ui_story_5070_50700101_228_dialog_content = "蜃風号も無事に入港したし、\n僕たちの任務も無事完了だね…はぁ…",
  ui_story_5070_50700101_229_dialog_content = "それなら、なぜ浮かない顔をしているの？",
  ui_story_5070_50700101_230_dialog_content = "分かったわ。あの時はあんなにきっぱり断ってたけど…",
  ui_story_5070_50700101_231_dialog_content = "報酬の増額、断ったのを後悔してるのよね？",
  ui_story_5070_50700101_232_dialog_content = "いま残念がるなら、あの時素直に受け入れておけばよかったのよ。",
  ui_story_5070_50700101_233_dialog_content = "…それはダメだよ。",
  ui_story_5070_50700101_234_dialog_content = "確かにここのところ巨像の修理やら普段の支出やら、\n厳しい状況だし…",
  ui_story_5070_50700101_235_dialog_content = "次はいつ依頼が来るかも分からないけど…",
  ui_story_5070_50700101_236_dialog_content = "何もしてないのに報酬をもらうのは、やっぱりいけないよ。",
  ui_story_5070_50700101_237_dialog_content = "それに、リン家商会に落ち着いてずっと働くっていうのは\nまだそんな年でもない気がするし…",
  ui_story_5070_50700101_238_dialog_content = "カン違いしているのではないかしら。\nその誘いはリン家商会で働くという意味では…",
  ui_story_5070_50700101_239_dialog_content = "え？ちょっと待って。問題はそこじゃないでしょ？",
  ui_story_5070_50700101_240_dialog_content = "双閣港の皆さん――",
  ui_story_5070_50700101_241_dialog_content = "うわ！大きな声だね。どこで話してるんだろう？",
  ui_story_5070_50700101_242_dialog_content = "誰かが啓光の軍用拡声器でも使ってるのかしら？",
  ui_story_5070_50700101_243_dialog_content = "この度龍州の遠洋船蜃風号が入港しました。\n蜃風号は当港に半月ほど停泊し――",
  ui_story_5070_50700101_244_dialog_content = "大修理を行います！",
  ui_story_5070_50700101_245_dialog_content = "そこで、大勢の運搬工と船職人を募集します。",
  ui_story_5070_50700101_246_dialog_content = "ぜひご応募をお願いします！\n皆さんの働きと才覚を、蜃風号にお貸しください！",
  ui_story_5070_50700101_247_dialog_content = "海の向こうからもたらされた富を分かち合いましょう！",
  ui_story_5070_50700101_248_dialog_content = "はぁ…はぁ…親父さん！い、急いで…人を集めましょう！",
  ui_story_5070_50700101_249_dialog_content = "急いで働き手を見つけなきゃいかんな。\nすぐに貼り紙を出そう。",
  ui_story_5070_50700101_250_dialog_content = "貼り紙の必要はありませんよ！\nもう全員の耳に届いてますから！",
  ui_story_5070_50700101_251_dialog_content = "なんだって？そういえば双閣港にはあんな仕組みなかったはずだが…",
  ui_story_5070_50700101_252_dialog_content = "これって…ユエが言ってた「お願いすること」なのかな…",
  ui_story_5070_50700101_253_dialog_content = "ちょうどいいじゃない。\n何か出来る仕事はないか見に行きましょう！",
  ui_story_5070_50700101_254_dialog_content = "予想外の大金を稼げるかもしれないわよ。",
  ui_story_5070_50700201_1_dialog_content = "こうして、僕は双閣港で2週間、なかなか充実した時を過ごした。",
  ui_story_5070_50700201_2_dialog_content = "蜃風号に関わる色々な仕事のほかにも、\nたくさんの事をした…",
  ui_story_5070_50700201_3_dialog_content = "カレンと一緒に修理中の蜃風号を見学して――",
  ui_story_5070_50700201_4_dialog_content = "怪しい占い師に言われるまま、\n不思議なくじをたくさん引いて…",
  ui_story_5070_50700201_5_dialog_content = "それから、バイスと一緒に\n災いを払い、福を呼び寄せると言う鎮海の舞の準備もした。",
  ui_story_5070_50700201_6_dialog_content = "その時、僕とバイスはあの時助けてくれた\nタンドウと改めて言葉を交わすことができた。",
  ui_story_5070_50700201_7_dialog_content = "異国の貴族で群主という身分らしく、近づき難い人かと心配していたけど、\n聡明で、とても親しみやすい人だった。",
  ui_story_5070_50700201_8_dialog_content = "彼女と黒服のお付きの人が、\n僕たちを連れて龍州の文化や風習を紹介してくれた。",
  ui_story_5070_50700201_9_dialog_content = "残念だったのは、バイスもカレンも途中で急な連絡が来て、\nそれぞれ啓光と白夜城に帰らなきゃならなくなったことだ。",
  ui_story_5070_50700201_10_dialog_content = "でも、この絶好のチャンスを逃さず、\n僕は2人の分までしっかり大金を稼ぐつもりだ！",
  ui_story_5070_50700201_11_dialog_content = "…PlayerName？PlayerName？",
  ui_story_5070_50700201_12_dialog_content = "え？あ、ご、ごめんなさい、タンドウ殿下。\nちょっと考え事をしてました。",
  ui_story_5070_50700201_13_dialog_content = "構わぬ。大事な話はこれからじゃ。",
  ui_story_5070_50700201_14_dialog_content = "だが言ったであろう？タンドウでよい。",
  ui_story_5070_50700201_15_dialog_content = "あ、そうだった。ごめん、タンドウさ…タンドウ。",
  ui_story_5070_50700201_16_dialog_content = "フフ。詫びを聞きに来たのではない。",
  ui_story_5070_50700201_17_dialog_content = "先頃わらわがユエに紹介した優秀な機巧師がおったであろう？",
  ui_story_5070_50700201_18_dialog_content = "その者のおかげで、蜃風号の修理作業も順調に進んでのう。\n完成も近いそうでな。",
  ui_story_5070_50700201_19_dialog_content = "それゆえ、修理が完了した日に祝いの儀式を執り行おうと、\n準備を始めたのじゃ。",
  ui_story_5070_50700201_20_dialog_content = "わらわ自身の務めもその間に色々と計らい、\n成果が出ておる。",
  ui_story_5070_50700201_21_dialog_content = "お主が引き合わせてくれたカレン殿下のおかげで、\n白夜城の使いがついに返答をよこしてのう。",
  ui_story_5070_50700201_22_dialog_content = "龍州との通商や暗鬼への対策について、\n話し合いたいと言ってきたのじゃ。",
  ui_story_5070_50700201_23_dialog_content = "しかも白夜城から使いを祝儀に出席させ、\nそのまま蜃風号と共に龍州へ出向き、済の国を訪れるとの事じゃ。",
  ui_story_5070_50700201_24_dialog_content = "任務を無事に果たせたんだね。おめでとう、タンドウ！",
  ui_story_5070_50700201_25_dialog_content = "フフフ、PlayerNameのおかげじゃな。",
  ui_story_5070_50700201_26_dialog_content = "今日はお主を儀式に招きたいと思って来たのじゃ。",
  ui_story_5070_50700201_27_dialog_content = "僕も行っていいの？喜んで参加するよ！",
  ui_story_5070_50700201_28_dialog_content = "もちろんじゃ。必ず顔を出すのじゃぞ。",
  ui_story_5070_50700201_29_dialog_content = "バイスとカレン殿下が来られぬのだけが心残りじゃな。\n2人には大そう助けてもらったからの。直に礼を言いたかったのじゃが。",
  ui_story_5070_50700201_30_dialog_content = "せめて、PlayerNameには2人分も楽しんでもらわねば。",
  ui_story_5070_50700201_31_dialog_content = "分かった。じゃあ残りの仕事を早めに終わらせて、\n儀式の日を楽しみに待ってるよ！",
  ui_story_5070_50700201_32_dialog_content = "どれどれ…",
  ui_story_5070_50700201_33_dialog_content = "東側にあるお店に渡す書類は…これでよしと。\n職人さんたちが借りた道具も全部集めて返したね。",
  ui_story_5070_50700201_34_dialog_content = "あとは…春昔街の突き当りにある倉庫に荷物を運べば…\nでも、なかなか終わりそうにないな…",
  ui_story_5070_50700201_35_dialog_content = "はぁ。",
  ui_story_5070_50700201_36_dialog_content = "今朝からがんばって早めに運んできたのに、\n誰も受け取りに来ない…",
  ui_story_5070_50700201_37_dialog_content = "途中様子を見ながら、他の仕事を終わらせてきたけど、\nどうしてまだ誰も受け取りにこないんだろう？",
  ui_story_5070_50700201_38_dialog_content = "今日は蜃風号のお祝いの日なのに…\nこれ以上待ってたら儀式に遅れそうだ。",
  ui_story_5070_50700201_39_dialog_content = "それはそうと、ずいぶん変わった形の箱だなぁ。",
  ui_story_5070_50700201_40_dialog_content = "船の修理に使う材料とかを、こういう箱に入れる決まりなのかな？",
  ui_story_5070_50700201_41_dialog_content = "…あれ？",
  ui_story_5070_50700201_42_dialog_content = "なんだか…箱の位置が動いた気がするんだけど！？",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>ギギギ――ミシミシ――</color>",
  ui_story_5070_50700201_44_dialog_content = "何の音！？",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700201_46_dialog_content = "な、何これ…！？カ、カニの怪物！？\n待って！こっちに来ないで！",
  ui_story_5070_50700201_47_dialog_content = "逃げ足を鍛えててよかった…\nでなかったら、ツメがかすってたよ…",
  ui_story_5070_50700201_48_dialog_content = "ゴオオ！",
  ui_story_5070_50700201_49_dialog_content = "ええっ！？火も噴くの！？――うわああ！！",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>怪物が灼熱の炎を噴き出した</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>だが次の瞬間、大きな傘が目の前に現れ――</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>まぶしい金属のきらめきとともに開いた傘が回り出し、\n勢いよく噴き出す炎を散らした</color>",
  ui_story_5070_50700201_53_dialog_content = "空気も物も乾燥してるから、火には注意しないとね。",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>怪物は無尽蔵に炎を噴き出し続ける。\nだが、それはすべて傘に遮られ、かすかに熱が伝わってくるだけだ</color>",
  ui_story_5070_50700201_55_dialog_content = "どこかで聞いたことあるような…あ！思い出した！\nこの前トンボで手紙を拾ってくれた人だね！",
  ui_story_5070_50700201_56_dialog_content = "その傘は…？",
  ui_story_5070_50700201_57_dialog_content = "あ、危ないわよ。今はむやみに触っちゃダメ。\nケガしても責任持てないわ。",
  ui_story_5070_50700201_58_dialog_content = "目の前のコイツも先に片付けなきゃいけないし。",
  ui_story_5070_50700202_1_dialog_content = "ほ、本当にすごいね！",
  ui_story_5070_50700202_2_dialog_content = "（ただの傘に見えるけど、どんな名刀や神剣より強いのかもしれない…）",
  ui_story_5070_50700202_3_dialog_content = "（開けば、火も水も通さない盾になり――）",
  ui_story_5070_50700202_4_dialog_content = "（閉じれば、決して折れない武器になる）",
  ui_story_5070_50700202_5_dialog_content = "（動きがまったく見切れない）",
  ui_story_5070_50700202_6_dialog_content = "（軽く腕を動かしているだけのようでいて、傘が振られるたびに、\nあの丈夫そうな怪物が粉々の破片になっていく）",
  ui_story_5070_50700202_7_dialog_content = "グアアア――",
  ui_story_5070_50700202_8_dialog_content = "（あ、でも待って…金属の破片？ということは、\nこの怪物は人が造った機械だってこと？）",
  ui_story_5070_50700202_9_dialog_content = "こんな大きくて恐ろしい機械のカニ…\nいったい誰が何の目的で造ったんだろう…？",
  ui_story_5070_50700202_10_dialog_content = "これは火吹き蟹っていうの。\n鄴の国の工房ではよく使われるカラクリ獣よ。",
  ui_story_5070_50700202_11_dialog_content = "匠の仕事を手伝うために作られたもので、\nほぞ接ぎや溶接の作業がずっと楽になるわ。",
  ui_story_5070_50700202_12_dialog_content = "素早く正確に必要な大きさの炎を出せるし、\nペンチも合わせて使えるから、とっても便利なの。",
  ui_story_5070_50700202_13_dialog_content = "ほぞ接ぎ？溶接？…まさかこのカラクリたち、\n僕を機械の材料か何かと間違えたわけじゃないよね？",
  ui_story_5070_50700202_14_dialog_content = "うーん…そういう視点で見ると、あなたは…\n剛性も強度も機械の材料とは程遠いわね。",
  ui_story_5070_50700202_15_dialog_content = "普通なら火吹き蟹がこんな基本的な間違いをするはずないんだけど…",
  ui_story_5070_50700202_16_dialog_content = "どう反応すればいいのか分からないよ。",
  ui_story_5070_50700202_17_dialog_content = "何より、鄴の国には、カラクリ獣の流通や使用に関する決まりがあるわ。",
  ui_story_5070_50700202_18_dialog_content = "火吹き蟹がこんな所に現れて、しかも人を傷つけようとするなんて…",
  ui_story_5070_50700202_19_dialog_content = "きっと誰かが裏で糸を引いてるに違いないわ。",
  ui_story_5070_50700202_20_dialog_content = "自分から出てくる？それとも、私が引っ張り出してあげようかしら？",
  ui_story_5070_50700202_21_dialog_content = "（倉庫の中に誰かいる！？）",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>黒い人影が突然、薄暗い影の中から飛び出し、\n出入口へと走り出した</color>",
  ui_story_5070_50700202_23_dialog_content = "止まりなさい！",
  ui_story_5070_50700202_24_dialog_content = "（攻撃がかわされた…何とかして止めなきゃ！）",
  ui_story_5070_50700202_25_dialog_content = "強制感知！",
  ui_story_5070_50700202_26_dialog_content = "安心してください。この手のことは影ノ街で長年やってますから、\nやり方は十分承知していますよ。",
  ui_story_5070_50700202_27_dialog_content = "人から金をもらってやるんです。\nもちろんご要望通り、きっちり仕事しますよ。",
  ui_story_5070_50700202_28_dialog_content = "それに、ただ使い方を学ぶだけでしょう？\nええと、確か…何と言いましたかね、このカニは？",
  ui_story_5070_50700202_29_dialog_content = "あ、そうそう。築炉蟹でしたかね。",
  ui_story_5070_50700202_30_dialog_content = "少しばかり面倒ではありますね。",
  ui_story_5070_50700202_31_dialog_content = "でも、リン家と蜃風号を痛い目に遭わせてやれるなら、\n少しばかりの面倒くらい、どうってことありませんよ。",
  ui_story_5070_50700202_32_dialog_content = "（目的は蜃風号？でも、どうして…？）",
  ui_story_5070_50700202_33_dialog_content = "どけ！",
  ui_story_5070_50700202_34_dialog_content = "うわっ――",
  ui_story_5070_50700202_35_dialog_content = "気をつけて。",
  ui_story_5070_50700202_36_dialog_content = "あ…ありがとう。受け止めてくれなかったら、転んで散々な目に遭ってたよ。\nでも、あの人が…",
  ui_story_5070_50700202_37_dialog_content = "仕方ないわ。追い詰められたネズミは追うなって言うし。",
  ui_story_5070_50700202_38_dialog_content = "それに今のはただの下っ端よ。",
  ui_story_5070_50700202_39_dialog_content = "重要なのは、アイツの上にいるヤツ。\nだいたい目星はついてるの。",
  ui_story_5070_50700202_40_dialog_content = "下っ端がどこへ行くかなんて、\n双閣港の皆にお願いすれば――",
  ui_story_5070_50700202_41_dialog_content = "あ、そうか！この声は！",
  ui_story_5070_50700202_42_dialog_content = "どうりで聞き覚えがあると思った。\nこの前双閣港の皆に拡声器で話しかけてたの、君だね？",
  ui_story_5070_50700202_43_dialog_content = "君はいったい誰？",
  ui_story_5070_50700202_44_dialog_content = "あら？私のこと知らないの？",
  ui_story_5070_50700202_45_dialog_content = "ご、ごめんなさい…？",
  ui_story_5070_50700202_46_dialog_content = "あはは、冗談よ。いくら私でも\n海の向こう側まで自分の名前が知られてるとは思ってないわ。",
  ui_story_5070_50700202_47_dialog_content = "でも…タンドウ様が私のことを話してなかったってことよね。\n私はあなたのこと、タンドウ様からたくさん聞いたけど。",
  ui_story_5070_50700202_48_dialog_content = "ちょっと不公平な気がするわ。",
  ui_story_5070_50700202_49_dialog_content = "まあ、今からお知り合いになればいいだけのことよね。",
  ui_story_5070_50700202_50_dialog_content = "私はセンキョクっていうの。機巧師よ。",
  ui_story_5070_50700202_51_dialog_content = "タンドウ様と同じ龍州で、工匠の国と呼ばれている鄴の国の出身よ。",
  ui_story_5070_50700202_52_dialog_content = "今は双閣港で、落とし物探しの依頼なんかを受けてるの。",
  ui_story_5070_50700202_53_dialog_content = "今は光栄にも、タンドウ様に腕を買われて、\n一時的だけど蜃風号の技師をやってるわ。",
  ui_story_5070_50700202_54_dialog_content = "蜃風号の機関の修理をしながら、\nリン家商会に貸し出す伝言鳥の調整もやってるわね。",
  ui_story_5070_50700202_55_dialog_content = "この間のは、伝言鳥っていうのを使って…？",
  ui_story_5070_50700202_56_dialog_content = "空飛ぶ拡声器だと思ってくれればいいわ。",
  ui_story_5070_50700202_57_dialog_content = "とはいっても、クチバシと羽根の構造は\nかなりこだわって設計したんだけどね。",
  ui_story_5070_50700202_58_dialog_content = "…君がタンドウの言ってた「最高の機巧師」だったんだ。",
  ui_story_5070_50700202_59_dialog_content = "すごいね！",
  ui_story_5070_50700202_60_dialog_content = "ついでに言うと――",
  ui_story_5070_50700202_61_dialog_content = "地面に転がってる「大きくて恐ろしいカニ」も私が設計したのよ。",
  ui_story_5070_50700202_62_dialog_content = "？",
  ui_story_5070_50700301_1_dialog_content = "続きまして、ユエ船長にご挨拶をいただきます――",
  ui_story_5070_50700301_2_dialog_content = "蜃風号が無事に修理を終えられたのも、\nここにお揃いの皆様がたのおかげです。",
  ui_story_5070_50700301_3_dialog_content = "ですので、本日の祝いの式も皆さんのためにあるものです。",
  ui_story_5070_50700301_4_dialog_content = "リン家は常に努力と勤勉を重んじます。\n力を尽くしてくださった方々へのお礼は一切惜しみません。",
  ui_story_5070_50700301_5_dialog_content = "どうぞご遠慮なく、思い切りお楽しみください。",
  ui_story_5070_50700301_6_dialog_content = "おお！",
  ui_story_5070_50700301_7_dialog_content = "まさか船上でこれほど盛大な式典を催すことができるとは\n思ってもいませんでした。",
  ui_story_5070_50700301_8_dialog_content = "白夜城よりお越しいただきありがとうございます。\nテルマ閣下。",
  ui_story_5070_50700301_9_dialog_content = "龍州へ出向けば、さらに多くの驚きが待っているのでしょうね。\n非常に楽しみです。",
  ui_story_5070_50700301_10_dialog_content = "もちろんでございます。",
  ui_story_5070_50700301_11_dialog_content = "龍州は遠方からの方々をお客様として扱う風習です。\nましてや、御身は白夜城を代表しておられる、賓客でございます。",
  ui_story_5070_50700301_12_dialog_content = "存分におもてなしさせていただきます。",
  ui_story_5070_50700301_13_dialog_content = "お言葉をうかがい、今すぐにでも海の向こうを訪れたくなりました。",
  ui_story_5070_50700301_14_dialog_content = "ですが、龍州は私たちにとって、まだはるか遠方の地。\nまずは蜃風号に使われている機巧術とやらを拝見したいのですが？",
  ui_story_5070_50700301_15_dialog_content = "実は双閣港に足を踏み入れてから、\n機巧術について、興味深い話を耳にしまして。",
  ui_story_5070_50700301_16_dialog_content = "機巧術で造られた物の多くは小さく非常に精巧で\n性能も様々、まるで芸術品のようだというではありませんか。",
  ui_story_5070_50700301_17_dialog_content = "啓光のゴツゴツとした機械や、砂漠の…恥さらし同然のそれよりもずっと\n愛らしく親しみやすいと聞いております。",
  ui_story_5070_50700301_18_dialog_content = "どの土地にもそれぞれ独自の技術がございます。\n強みもあれば、足りない所もあるでしょう。",
  ui_story_5070_50700301_19_dialog_content = "では…私がご案内させていただきます。\n一つ一つご紹介いたしましょう。",
  ui_story_5070_50700301_20_dialog_content = "（センキョクは…おらぬのか？）",
  ui_story_5070_50700301_21_dialog_content = "おや、お主、腕利きの匠…ソンであったな？\nちょうどよい。",
  ui_story_5070_50700301_22_dialog_content = "…郡主殿下！？な、何かご用でしょうか？",
  ui_story_5070_50700301_23_dialog_content = "こちらの白夜城の使者殿に、\n蜃風号のカラクリを紹介してもらえぬか？",
  ui_story_5070_50700301_24_dialog_content = "お、お安い御用です。",
  ui_story_5070_50700301_25_dialog_content = "機巧をいじってもう数十年ですから、\nそういうことなら、お任せくだせえ。",
  ui_story_5070_50700301_26_dialog_content = "ならば、頼んだぞ。",
  ui_story_5070_50700301_27_dialog_content = "それでは、後ほどお会いしましょう。",
  ui_story_5070_50700301_28_dialog_content = "ふぅ。",
  ui_story_5070_50700301_29_dialog_content = "殿下、お休みになられますか？",
  ui_story_5070_50700301_30_dialog_content = "いや、構わぬ。疲れてはおらぬのじゃ。",
  ui_story_5070_50700301_31_dialog_content = "それにしても…PlayerNameはなにゆえ、\nいまだに姿を見せぬのであろう？",
  ui_story_5070_50700301_32_dialog_content = "仕事が忙しすぎるのかのう？",
  ui_story_5070_50700301_33_dialog_content = "ならば、私が様子を見てまいりましょうか…",
  ui_story_5070_50700301_34_dialog_content = "お待ちください！",
  ui_story_5070_50700301_35_dialog_content = "キュウ？いかがしたのじゃ？",
  ui_story_5070_50700301_36_dialog_content = "殿下、周りにご注意くださいませ。",
  ui_story_5070_50700301_37_dialog_content = "…",
  ui_story_5070_50700301_38_dialog_content = "どうやら…蜃風号乗船時の注意説明は\n後回しになりそうね。",
  ui_story_5070_50700301_39_dialog_content = "どうしたんだ？何事だ？？",
  ui_story_5070_50700301_40_dialog_content = "おやおや。せっかくの祝いの席でこんな目に遭うなんてねぇ…",
  ui_story_5070_50700301_41_dialog_content = "こりゃあ不吉ですなぁ。",
  ui_story_5070_50700301_42_dialog_content = "全員、警戒態勢よ！",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700301_44_dialog_content = "わあっ！船が揺れたぞ！",
  ui_story_5070_50700301_45_dialog_content = "船長、大変だ！カラクリ獣が蜃風号の骨組みを攻撃してやがる！",
  ui_story_5070_50700301_46_dialog_content = "白夜に捧ぐ…式典の最中だというのに…\nいったい何が起こっているのですか！？",
  ui_story_5070_50700301_47_dialog_content = "教えていただきたい、\n船はいったいどうなっているのですか！？",
  ui_story_5070_50700301_48_dialog_content = "…",
  ui_story_5070_50700301_49_dialog_content = "殿下はここでお待ちください。\n私が行ってまいります。",
  ui_story_5070_50700301_50_dialog_content = "キュウ、気を付けるのじゃぞ。",
  ui_story_5070_50700302_1_dialog_content = "殿下、片付きました。",
  ui_story_5070_50700302_2_dialog_content = "さようか。",
  ui_story_5070_50700302_3_dialog_content = "殿下…なぜ眉をひそめていらっしゃるのですか？\nまさか先程の騒ぎでおケガでもされたのでは――",
  ui_story_5070_50700302_4_dialog_content = "そうではない。",
  ui_story_5070_50700302_5_dialog_content = "先刻のカラクリ獣騒ぎで、\nリン家は今、蜃風号の出航を遅らせようと話し合っておる。",
  ui_story_5070_50700302_6_dialog_content = "決して弱腰になっているわけではありません。",
  ui_story_5070_50700302_7_dialog_content = "ですが、海はそもそも危険が多いのです。\n暗鬼や嵐だけでも大変だというのに…",
  ui_story_5070_50700302_8_dialog_content = "そのうえ原因不明のカラクリ獣の暴走ときました。",
  ui_story_5070_50700302_9_dialog_content = "危険すぎます。しばらく様子を見るべきでしょう。",
  ui_story_5070_50700302_10_dialog_content = "じゃが、わらわどもは待ってはおられぬ。",
  ui_story_5070_50700302_11_dialog_content = "お主らも知っておるじゃろう？\nわらわには使者としての務めが二つある。",
  ui_story_5070_50700302_12_dialog_content = "一つはアストラとの通商を深め、\nより正式なものとするべく先方と話し合うこと。",
  ui_story_5070_50700302_13_dialog_content = "もう一つは暗鬼に対抗するため、\n戦略と技術に関して交流を行うことじゃ。",
  ui_story_5070_50700302_14_dialog_content = "この二つの何がそれほど重要か、皆は知っておるか？",
  ui_story_5070_50700302_15_dialog_content = "近年、龍州の沿海部は暗鬼にたびたび襲撃されておる。\n商船の出航も、それ故に大きな影響を受けておる。",
  ui_story_5070_50700302_16_dialog_content = "わらわのいる済の国は八大諸侯国の中でも最も通商の発達した国じゃ。\n水路や海運が国の基礎と言ってもよい。",
  ui_story_5070_50700302_17_dialog_content = "故に各商会は早くから連名で嘆願書をしたため、\n国主に取り締まりを求めておった。",
  ui_story_5070_50700302_18_dialog_content = "じゃが、根本的解決策は見つからぬまま、暗鬼の襲撃は繰り返し、\n民はやむなく海辺の地を捨て、海賊どもが勢いを取り戻した…",
  ui_story_5070_50700302_19_dialog_content = "商人は憂いに顔を曇らせ、人々の暮らしは安寧を失い、\n水運を営む者の間には動揺が広がっておる。",
  ui_story_5070_50700302_20_dialog_content = "それ故に国主は使節をアストラに派遣し、\nこの大陸に解決の手がかりを求めたのじゃ。",
  ui_story_5070_50700302_21_dialog_content = "ようやく白夜城の使者を招き、\n龍州への同行を取りつけられたというに…",
  ui_story_5070_50700302_22_dialog_content = "それが…",
  ui_story_5070_50700302_23_dialog_content = "船を下ります。今すぐに。",
  ui_story_5070_50700302_24_dialog_content = "この船は絶対に安全だとおっしゃっていましたよね？\nそれが今、まだ港も出ていないというのに襲撃に遭いました。",
  ui_story_5070_50700302_25_dialog_content = "これがあなた方のおっしゃる安全と言う事ですか？",
  ui_story_5070_50700302_26_dialog_content = "あの機械どもが人を襲うことがあるとは、聞いておりませんよ！",
  ui_story_5070_50700302_27_dialog_content = "そうでしょう！？",
  ui_story_5070_50700302_28_dialog_content = "そ…それは…",
  ui_story_5070_50700302_29_dialog_content = "…わらわには引き止めてわずかな時間を稼ぐことしかできん。",
  ui_story_5070_50700302_30_dialog_content = "早々に船を修復し出航できねば、事態がどう変わるか分からぬ。\nそうなれば、わらわの使命は…",
  ui_story_5070_50700302_31_dialog_content = "それは…",
  ui_story_5070_50700302_32_dialog_content = "殿下のおっしゃることは分かります。\nですが、いくら急いでも、そのような無謀はいけません。",
  ui_story_5070_50700302_33_dialog_content = "ご自分の命を投げ出すようなものです。",
  ui_story_5070_50700302_34_dialog_content = "殿下、やはり待ちましょう。",
  ui_story_5070_50700302_35_dialog_content = "使者の方がどうしても同行を拒むようであれば、\n「お連れ」すればよいだけのことです。",
  ui_story_5070_50700302_36_dialog_content = "これだけの危険を冒してやってきたのです。\n殿下のご苦労が無駄になるようなことは私が許しません。",
  ui_story_5070_50700302_37_dialog_content = "コホン…船長のご意見は？",
  ui_story_5070_50700302_38_dialog_content = "…",
  ui_story_5070_50700302_39_dialog_content = "今回の航海はとても重大な使命を背負っているわ。\nタンドウ殿下と積み荷はもちろんのこと――",
  ui_story_5070_50700302_40_dialog_content = "リン家の未来もかかっているのよ。",
  ui_story_5070_50700302_41_dialog_content = "リン家とて、このままでは…\nこれ以上の打撃は避けなければならないわ。",
  ui_story_5070_50700302_42_dialog_content = "その通りです。ですから、慎重を期して――",
  ui_story_5070_50700302_43_dialog_content = "船を修理するわよ。",
  ui_story_5070_50700302_44_dialog_content = "帰航を急ぐわ。",
  ui_story_5070_50700302_45_dialog_content = "ゴホッ、ゴホゴホ！",
  ui_story_5070_50700302_46_dialog_content = "ユ、ユエ船長、い、今何と…",
  ui_story_5070_50700302_47_dialog_content = "あの、船長？お待ちください…船長！",
  ui_story_5070_50700302_48_dialog_content = "最近の若者は…せっかちで困ります。",
  ui_story_5070_50700302_49_dialog_content = "まったくですねぇ。急がば回れとはよく言ったもんです。",
  ui_story_5070_50700302_50_dialog_content = "まあ、確かにこの状況じゃあ、\n急ぐなっていうのも難しいでしょうがねぇ。",
  ui_story_5070_50700302_51_dialog_content = "ん？あなたは…？",
  ui_story_5070_50700302_52_dialog_content = "祝いの儀式にいかさま師を招いた覚えはないがの？",
  ui_story_5070_50700302_53_dialog_content = "つれないですねぇ。",
  ui_story_5070_50700302_54_dialog_content = "思いがけないことになって、\n皆さん、食欲も出ないでしょう？",
  ui_story_5070_50700302_55_dialog_content = "皆さんの分まで食べて差し上げようと思いましてねぇ。\n船一杯のご馳走を無駄にしちゃあいけません。",
  ui_story_5070_50700302_56_dialog_content = "どれもこれも美味、珍味ばかりですが…\nこのウリはちいとばかし残念ですねぇ。",
  ui_story_5070_50700302_57_dialog_content = "早く売ろうと急いて、熟すのを待たずに収穫したってとこでしょうかね。\n熟してないと、甘くないんですがねぇ。",
  ui_story_5070_50700302_58_dialog_content = "このような時に何をたわけた…",
  ui_story_5070_50700302_59_dialog_content = "まあまあ、たかがウリの話ですよ。\nとはいえ…いいウリを待つか待たないかは殿下次第ですねぇ。",
  ui_story_5070_50700302_60_dialog_content = "苦ウリを無理やり口に入れるのもアリかもしれませんが、\n熟すのを待つ方が自然の摂理には合うってもんですよ。",
  ui_story_5070_50700302_61_dialog_content = "そう思いませんか？",
  ui_story_5070_50700401_1_dialog_content = "うーん、どう説明したら分かりやすいかしら…？",
  ui_story_5070_50700401_2_dialog_content = "…そうだ！確かアストラでは、\n四象の力に関する研究が進んでるのよね…",
  ui_story_5070_50700401_3_dialog_content = "四象の力？",
  ui_story_5070_50700401_4_dialog_content = "各属性の光力のことよ。",
  ui_story_5070_50700401_5_dialog_content = "機巧術はつまるところ、各種の材料をいかに合理的に組み合わせ…",
  ui_story_5070_50700401_6_dialog_content = "光霊や幻獣と同じように光力を使う物を造れるかを\n研究する技術なの。",
  ui_story_5070_50700401_7_dialog_content = "これで大体分かった？",
  ui_story_5070_50700401_8_dialog_content = "うーん…アストラの光力機械技術みたいなものかな。\nでも、だいぶ感じが違うね。",
  ui_story_5070_50700401_9_dialog_content = "当り前じゃない。目的は同じでも、世界のとらえ方が違うわ。",
  ui_story_5070_50700401_10_dialog_content = "龍州では、この世の万物に光力が宿ると考える――",
  ui_story_5070_50700401_11_dialog_content = "草木や虫に獣…すべてのものが光力の循環に関わってる。",
  ui_story_5070_50700401_12_dialog_content = "機巧術はそうした光力をカラクリの中に取り込んで、\n特定の規則性の下で作動させ、いろんな効果を生み出すのよ。",
  ui_story_5070_50700401_13_dialog_content = "だから、適切な材料と精確な構造さえあれば、\nもう一つ別の世界を創り出すことだってできるの。",
  ui_story_5070_50700401_14_dialog_content = "うーん、今度は何だか哲学の授業みたいだ。",
  ui_story_5070_50700401_15_dialog_content = "ははは、あながち間違ってないわ。",
  ui_story_5070_50700401_16_dialog_content = "さっきの火吹き蟹も銅ヤンマも\nモノづくりの哲学の表れだもの。",
  ui_story_5070_50700401_17_dialog_content = "あなたを助けたこの奇天烈傘も同じよ。",
  ui_story_5070_50700401_18_dialog_content = "内部にはたくさんのカラクリが仕込まれてて、\nだからこそ攻撃にも防御にも対応できるの。",
  ui_story_5070_50700401_19_dialog_content = "原理さえつかめば、機巧術はカラクリ獣だけじゃなく、\nいろんな分野に応用できるわ。",
  ui_story_5070_50700401_20_dialog_content = "機巧術って単純な機械技術じゃないんだね…\nそんなにすごい技術だとは思わなかったよ。",
  ui_story_5070_50700401_21_dialog_content = "一つの諸侯国を支え、リン家の航路開拓にも寄与する技術だもの。\n当然、簡単なものじゃないわ。",
  ui_story_5070_50700401_22_dialog_content = "鄴の国では、からくり鳥が空中を飛びながら言付けをし、\n木牛流馬が地上を行き交い、荷物を運んでるの。",
  ui_story_5070_50700401_23_dialog_content = "顔を洗ったり、服を着たり、料理するのが面倒なら、\nカラクリに代わりにやってもらうことだって出来るのよ。",
  ui_story_5070_50700401_24_dialog_content = "龍州に遊びに行くことがあったら、\n本物の「機巧」がどんなものか案内してあげるわ。",
  ui_story_5070_50700401_25_dialog_content = "いいね！",
  ui_story_5070_50700401_26_dialog_content = "ただ…",
  ui_story_5070_50700401_27_dialog_content = "今僕たちは…いったい何をしてるの？",
  ui_story_5070_50700401_28_dialog_content = "見て分からない？最近使われた倉庫を調べてるんじゃない。",
  ui_story_5070_50700401_29_dialog_content = "それは分かってるけど、もうかなりの数の倉庫を調べたよね！？",
  ui_story_5070_50700401_30_dialog_content = "（センキョクが無理やりこじ開けて入った倉庫もあったけど、\n止めようにも止められなかった…）",
  ui_story_5070_50700401_31_dialog_content = "今は敵を追う方が優先なんじゃないの？",
  ui_story_5070_50700401_32_dialog_content = "私は機巧師なのよ。人探しは街にいる密偵に任せましょ。\nカラクリこそ私の得意分野なんだから。",
  ui_story_5070_50700401_33_dialog_content = "裏でコソコソ動く悪党たちは、どうやったか知らないけど、\n私の設計図を入手し…",
  ui_story_5070_50700401_34_dialog_content = "火吹き蟹を凶器に改造して、蜃風号の倉庫に紛れ込ませた――",
  ui_story_5070_50700401_35_dialog_content = "さっきの無意味な待ち伏せは、明らかに真の目的じゃないわ。",
  ui_story_5070_50700401_36_dialog_content = "双閣港のどこかに、もっとたくさんの切り札を隠してるはずよ。",
  ui_story_5070_50700401_37_dialog_content = "…蜃風号、大丈夫かな？",
  ui_story_5070_50700401_38_dialog_content = "さっきの火吹き蟹の威力を見る限り、\n普通の人じゃ襲われても何の抵抗もできない。",
  ui_story_5070_50700401_39_dialog_content = "強は弱を執らず、衆は寡を劫らず、富は貧を侮らず…",
  ui_story_5070_50700401_40_dialog_content = "機巧術は強大な力を生み出すわ。\nだからこそ、その力を持った者は決して人を傷つけてはならないの。",
  ui_story_5070_50700401_41_dialog_content = "それが機巧師全体で決めた、必ず守らなければならない決まりよ。",
  ui_story_5070_50700401_42_dialog_content = "だから、私の図面を盗んだヤツらを見つけたら…",
  ui_story_5070_50700401_43_dialog_content = "（急に語気が鋭くなった…）",
  ui_story_5070_50700401_44_dialog_content = "そうだ！",
  ui_story_5070_50700401_45_dialog_content = "さっき君が言ってた通りなら、\nカラクリ獣は自然界の光力のめぐりを模倣したものなんだよね…",
  ui_story_5070_50700401_46_dialog_content = "だったら、感知能力で他の火吹き蟹の位置が分かるかもしれない！",
  ui_story_5070_50700401_47_dialog_content = "あら、面白い発想ね。",
  ui_story_5070_50700401_48_dialog_content = "感知開始――",
  ui_story_5070_50700401_49_dialog_content = "（さっきの火吹き蟹と似たような光力は…見つけた！）",
  ui_story_5070_50700401_50_dialog_content = "光力自体はわずかしか感じられないけど、方向は確かだ。\nこっちだよ！",
  ui_story_5070_50700401_51_dialog_content = "こんなへんぴな所に倉庫があるなんて…",
  ui_story_5070_50700401_52_dialog_content = "PlayerName、感謝するわ。大当たりよ！",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>一見ボロボロの倉庫の中には変わった形の箱が所狭しと積み上げられ、\nそれらの箱の中には――</color>",
  ui_story_5070_50700401_54_dialog_content = "火吹き蟹、浮き鳥、長サソリ…ふーん、勢ぞろいしてるじゃない。\nしかも上質の材料を使ってる。",
  ui_story_5070_50700401_55_dialog_content = "この倉庫の主は、ずいぶんと大盤振る舞いしたみたいね。",
  ui_story_5070_50700401_56_dialog_content = "こんなにたくさんカラクリを集めて、いったい何をするつもりなんだろう？",
  ui_story_5070_50700401_57_dialog_content = "PlayerName、もう一度手伝ってもらえるかしら？",
  ui_story_5070_50700401_58_dialog_content = "箱を全部開けて、カラクリ獣に印が残されていないか調べたいの。",
  ui_story_5070_50700401_59_dialog_content = "そういえば、さっきも倒した火吹き蟹も\n全部調べてたよね。",
  ui_story_5070_50700401_60_dialog_content = "でも…この2棟の倉庫にあったカラクリ獣には\n何も印はついてないみたいだ。",
  ui_story_5070_50700401_61_dialog_content = "鄴の国は図面や流通経路も含めて、\nカラクリを厳正に管理してるの。",
  ui_story_5070_50700401_62_dialog_content = "工房で量産されたものも、機巧師個人が造ったものも…",
  ui_story_5070_50700401_63_dialog_content = "カラクリはすべて組み立て完成後に\n生産者の印を付けなきゃいけないことになってるわ。",
  ui_story_5070_50700401_64_dialog_content = "何か問題があった時に、\n責任の所在を明確にできるようにね。",
  ui_story_5070_50700401_65_dialog_content = "でも、このカラクリたちには印がない…\n手がかりが途絶えたってこと？",
  ui_story_5070_50700401_66_dialog_content = "そうでもないわ。",
  ui_story_5070_50700401_67_dialog_content = "少なくとも、鄴の国で造られたものじゃないってことは分かったわ。",
  ui_story_5070_50700401_68_dialog_content = "部品の状態で密輸されて、こっちで組み立てられた可能性が高いわね。",
  ui_story_5070_50700401_69_dialog_content = "それに…ここには他の物もある…",
  ui_story_5070_50700401_70_dialog_content = "別の荷物も混じってるの？",
  ui_story_5070_50700401_71_dialog_content = "え？待って…この印って…リン家商会のもの？",
  ui_story_5070_50700401_72_dialog_content = "ええ。",
  ui_story_5070_50700401_73_dialog_content = "10日くらい前に蜃風号が寄港した時、\n下船した乗客たちがよくない噂話をしてたのを聞いたわ。",
  ui_story_5070_50700401_74_dialog_content = "龍州のリン家本家が密輸事件に巻き込まれて、\n当主が船舶府に連行されたって…",
  ui_story_5070_50700401_75_dialog_content = "PlayerName、一つお願いしてもいいかしら？",
  ui_story_5070_50700401_76_dialog_content = "ユエ船長に…",
  ui_story_5070_50700401_77_dialog_content = "リン家が本当に密輸に関わったのか、聞いてくれない？",
  ui_story_5070_50700401_78_dialog_content = "火吹き蟹の襲撃に遭ってから、\nずっと倉庫を調べてたから、忘れかけてたけど…",
  ui_story_5070_50700401_79_dialog_content = "そういえば、蜃風号の儀式はもう終わっちゃったのかな？",
  ui_story_5070_50700401_80_dialog_content = "あれ？蜃風号に何かあったのかな？",
  ui_story_5070_50700401_81_dialog_content = "テルマ閣下もお分かりでしょう？\nこの度の交流は双方にとって利益のあることです。",
  ui_story_5070_50700401_82_dialog_content = "もちろん、承知しております。\n私もそこまで愚かではありません。",
  ui_story_5070_50700401_83_dialog_content = "しかし、龍州がいかに素晴らしく、使命がいかに重要であろうと、\n無事に到着できなければ、何の意味もないのでは？",
  ui_story_5070_50700401_84_dialog_content = "対策に万全を期し、皆様の安全を守るため、あらゆる力を尽くします。",
  ui_story_5070_50700401_85_dialog_content = "栄光ある白夜城の使者として、\nあなたのおっしゃることを信じたいのは山々ですが…",
  ui_story_5070_50700401_86_dialog_content = "この状況では…考え直さないわけには参りません。",
  ui_story_5070_50700401_87_dialog_content = "テルマ閣下…",
  ui_story_5070_50700401_88_dialog_content = "（この人って…タンドウが重要だって言ってた白夜城の使者だよね？\nどうして急に気が変わったんだろう？）",
  ui_story_5070_50700401_89_dialog_content = "まだ調べてない建物は、この薬屋だけね。",
  ui_story_5070_50700401_90_dialog_content = "この感じは…火焔術を使う大物がいるわね！？",
  ui_story_5070_50700401_91_dialog_content = "いったいどんなヤツか見てやるわ。",
  ui_story_5070_50700401_92_dialog_content = "<size=45>トントン。</size>",
  ui_story_5070_50700401_93_dialog_content = "何か用？",
  ui_story_5070_50700401_94_dialog_content = "突然すみません。お聞きしたいことがあるんですが。",
  ui_story_5070_50700401_95_dialog_content = "ここからそう遠くない所にある倉庫が\n誰のものかご存じですか？",
  ui_story_5070_50700401_96_dialog_content = "それと…リン家をご存じですか？",
  ui_story_5070_50700401_97_dialog_content = "…",
  ui_story_5070_50700401_98_dialog_content = "（扉が…開いた？千機――）",
  ui_story_5070_50700401_99_dialog_content = "…",
  ui_story_5070_50700401_100_dialog_content = "？",
  ui_story_5070_50700401_101_dialog_content = "あら？どうしてボクちゃんが出てきたの？\n大人の人は？",
  ui_story_5070_50700401_102_dialog_content = "誰が「ボクちゃん」だって！？",
  ui_story_5070_50700401_103_dialog_content = "もちろん…",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5070_50700401_105_dialog_content = "なかなかの動きだ。",
  ui_story_5070_50700401_106_dialog_content = "なんて運の悪い日なのかしら。\nいきなりお客を攻撃する店なんて聞いたことないわ。",
  ui_story_5070_50700401_107_dialog_content = "<size=45>グオオ――</size>",
  ui_story_5070_50700401_108_dialog_content = "あら、これは予想外のおもてなしね。",
  ui_story_5070_50700402_1_dialog_content = "なんてしつこいんだろう。",
  ui_story_5070_50700402_2_dialog_content = "暗鬼を倒したと思ったら、\n今度はわけの分からないお客さんが…",
  ui_story_5070_50700402_3_dialog_content = "あれ？シュウさん、戦うのやめたの？",
  ui_story_5070_50700402_4_dialog_content = "千機の傘に銅ヤンマ…さらに精巧な作りのカラクリ…",
  ui_story_5070_50700402_5_dialog_content = "もしや…璇璣卿か？",
  ui_story_5070_50700402_6_dialog_content = "知ってる人？",
  ui_story_5070_50700402_7_dialog_content = "会ったことはないが、噂は聞き及んでおる。",
  ui_story_5070_50700402_8_dialog_content = "鄴の国の機巧師の流派「乾雲」の天才だ。",
  ui_story_5070_50700402_9_dialog_content = "齢15にして、本物と見紛うばかりの銅楽師を造り、\n鄴の国全土に名を馳せた者だ。",
  ui_story_5070_50700402_10_dialog_content = "その後鄴の王の麾下に入り、\n大いに謀の才を発揮した。",
  ui_story_5070_50700402_11_dialog_content = "鄴の国は名の知られたカラクリで要人を呼ぶ習わしがあると聞く。\n「璇璣卿」という名からして、多くの者に認められた才能の持ち主とお見受けする。",
  ui_story_5070_50700402_12_dialog_content = "そんな大した者じゃありません。朝廷の仕事はとうの昔にやめてますし、\n今はただの機巧師です。",
  ui_story_5070_50700402_13_dialog_content = "それより…赤い髪に優れた剣術の腕、\nさらに私のことをご存じということは…",
  ui_story_5070_50700402_14_dialog_content = "リン家とも懇意で、済の国の商会の誰もが敬うシュウ様ですね？",
  ui_story_5070_50700402_15_dialog_content = "それがしは名ばかりの者。あくまで友の名声の成すところにすぎぬ。",
  ui_story_5070_50700402_16_dialog_content = "リンセイよ。",
  ui_story_5070_50700402_17_dialog_content = "この者は敵にあらず。",
  ui_story_5070_50700402_18_dialog_content = "そうとは限らないかもね。",
  ui_story_5070_50700402_19_dialog_content = "ちょっと！…失礼じゃないか！",
  ui_story_5070_50700402_20_dialog_content = "ボクちゃんは、大人の話に口を挟んじゃダメよ。",
  ui_story_5070_50700402_21_dialog_content = "「ボクちゃん」じゃないって言ってるでしょ！",
  ui_story_5070_50700402_22_dialog_content = "半年前、済の国がある密輸品を追跡調査したところ――",
  ui_story_5070_50700402_23_dialog_content = "その時期に出航していた船はリン家の商船だけでした。",
  ui_story_5070_50700402_24_dialog_content = "リン家商会も潔白を証明できる証拠がなく――",
  ui_story_5070_50700402_25_dialog_content = "ウソでしょ？ただの偶然で罪を着せたっていうの？",
  ui_story_5070_50700402_26_dialog_content = "その通りよ。",
  ui_story_5070_50700402_27_dialog_content = "条件に当てはまるのは確かにリン家だけだけど、\n多くの人がまだ疑いをもってるわ。",
  ui_story_5070_50700402_28_dialog_content = "でもさっき、ここの近くの倉庫を調べていたら…",
  ui_story_5070_50700402_29_dialog_content = "おそらく密輸されたものであろう\n鄴の国のカラクリ獣の部品が見つかったんです。",
  ui_story_5070_50700402_30_dialog_content = "倉庫の中にはリン家商会の印のついた荷物もありました。",
  ui_story_5070_50700402_31_dialog_content = "シュウ様はリン家と懇意になさっています。\n何かご存じでしょう？",
  ui_story_5070_50700402_32_dialog_content = "説明していただけませんか？",
  ui_story_5070_50700402_33_dialog_content = "…",
  ui_story_5070_50700402_34_dialog_content = "リン家の商船は確かに密輸品を載せたことがある。",
  ui_story_5070_50700402_35_dialog_content = "（このテルマって人、本当に頑固だなぁ…\n何を言っても、「考えさせてほしい」としか言わない…）",
  ui_story_5070_50700402_36_dialog_content = "（このままだったら、タンドウの任務はどうなっちゃうんだろう…）",
  ui_story_5070_50700402_37_dialog_content = "…分かりました。",
  ui_story_5070_50700402_38_dialog_content = "ご意志を尊重いたします。",
  ui_story_5070_50700402_39_dialog_content = "ふぅ…感謝いたします。",
  ui_story_5070_50700402_40_dialog_content = "あなたのような美しく高貴な女性なら、\n必ずや私の立場をご理解いただけるものと信じておりました。",
  ui_story_5070_50700402_41_dialog_content = "ならば同様に、私の立場もご理解いただきたいものです。",
  ui_story_5070_50700402_42_dialog_content = "ほう？",
  ui_story_5070_50700402_43_dialog_content = "PlayerName。",
  ui_story_5070_50700402_44_dialog_content = "テルマ閣下の代わりに、アストラ大陸の使節として、\nわらわと共に龍州へ渡ってくれぬかのう？",
  ui_story_5070_50700402_45_dialog_content = "…僕が！？",
  ui_story_5070_50700501_1_dialog_content = "だ、ダメだよ！僕なんかが使者になれるわけないでしょ！？",
  ui_story_5070_50700501_2_dialog_content = "なにゆえじゃ？",
  ui_story_5070_50700501_3_dialog_content = "僕は啓光連邦の者でも、白夜城の者でもないんだ。",
  ui_story_5070_50700501_4_dialog_content = "いずれの勢力にも属さぬ中立な者こそ、\nアストラ大陸を代表するにふさわしいのではないか？",
  ui_story_5070_50700501_5_dialog_content = "しかもPlayerNameは人脈も広く、経験も豊かであろう？",
  ui_story_5070_50700501_6_dialog_content = "この大陸各地の状況や暗鬼に対抗する戦略などにも通じておる。",
  ui_story_5070_50700501_7_dialog_content = "二大陸の懸け橋を造らんとする、\nこの度の使命にまさにふさわしいではないか。",
  ui_story_5070_50700501_8_dialog_content = "あの、でも、それは…",
  ui_story_5070_50700501_9_dialog_content = "私は賛成です！！",
  ui_story_5070_50700501_10_dialog_content = "PlayerNameさんはアストラでも非常に名声高く、\nお会いする前から、その功績については聞き及んでおります。",
  ui_story_5070_50700501_11_dialog_content = "白夜城を代表して、龍州への使節としての役目をあなたにお任せいたします！",
  ui_story_5070_50700501_12_dialog_content = "ちょっと待って…ちゃんと考えさせてほしいんだ…",
  ui_story_5070_50700501_13_dialog_content = "（白夜城か…カレンはずっと二大陸間の交流を支持してきたし、\nもし今回のことがダメになったら、ガッカリするよね）",
  ui_story_5070_50700501_14_dialog_content = "（タンドウたちもアストラに到着してからずっと、\nあちこち駆け回ってた…）",
  ui_story_5070_50700501_15_dialog_content = "（今回の交流にたくさんの人が期待してるんだ…しかも両大陸の将来に関わる一大事…\nもし今、他にふさわしい人がいないなら…）",
  ui_story_5070_50700501_16_dialog_content = "全力を尽くすよ。",
  ui_story_5070_50700501_17_dialog_content = "PlayerName…感謝する！！",
  ui_story_5070_50700501_18_dialog_content = "決心はついたのね！？",
  ui_story_5070_50700501_19_dialog_content = "ユエ船長も聞いてたの？",
  ui_story_5070_50700501_20_dialog_content = "ユエでいいわ。",
  ui_story_5070_50700501_21_dialog_content = "決心がついたのなら、蜃風号の船長として…",
  ui_story_5070_50700501_22_dialog_content = "PlayerNameがアストラ全権使節として乗船することを認めるわ。",
  ui_story_5070_50700501_23_dialog_content = "ただし、航海は危険よ。心の準備をしておいてね。",
  ui_story_5070_50700501_24_dialog_content = "うん、分かった。",
  ui_story_5070_50700501_25_dialog_content = "そうだ、ユエ船長…じゃなくて、ユエ。\n今ちょっといいかな？",
  ui_story_5070_50700501_26_dialog_content = "あの…友だちにリン家のことを聞いてほしいって頼まれたんだ。",
  ui_story_5070_50700501_27_dialog_content = "リン家の商船は確かに密輸品を載せたことがある。",
  ui_story_5070_50700501_28_dialog_content = "シュウさん、何言ってるの！？",
  ui_story_5070_50700501_29_dialog_content = "この人、どこで聞いたか知れない話を信じて、詰問してくるなんて失礼だよ。\nシュウさんも適当にあしらえばいいんだよ。",
  ui_story_5070_50700501_30_dialog_content = "あらあら～、聞こえてるわよ。",
  ui_story_5070_50700501_31_dialog_content = "でも…いきなりそんな衝撃的なことを話すなんて、\nシュウ様はまだ私と腕試しをしたいってことですか？",
  ui_story_5070_50700501_32_dialog_content = "否――",
  ui_story_5070_50700501_33_dialog_content = "ただ璇璣卿が今の一言で、心が揺らいだとあらば…",
  ui_story_5070_50700501_34_dialog_content = "真相を知る気はないものとお見受けする。",
  ui_story_5070_50700501_35_dialog_content = "何ですって？",
  ui_story_5070_50700501_36_dialog_content = "分かるヤツだけ聞けばいい、分からないヤツや聞きたくないヤツは聞かなくていい――\nそうおっしゃりたいんですか？",
  ui_story_5070_50700501_37_dialog_content = "さようではござらぬ。",
  ui_story_5070_50700501_38_dialog_content = "それがしはまだ傷も癒えておらず、疲れやすい。\n話はできるだけ短く済ませたいだけのこと。",
  ui_story_5070_50700501_39_dialog_content = "いいわ、それなら短く済ませましょう。",
  ui_story_5070_50700501_40_dialog_content = "シュウ様がここまでハッキリ話してくださってるのに、\nそれさえ聞かないなんて言ったら、私が心の狭い人間みたいですもの。",
  ui_story_5070_50700501_41_dialog_content = "なんだ、キミって話が通じたんだね。",
  ui_story_5070_50700501_42_dialog_content = "だって大人だもの、ボクちゃん。",
  ui_story_5070_50700501_43_dialog_content = "だから「ボクちゃん」じゃないって言ってるでしょ！\nなんでソコだけ通じないの！？",
  ui_story_5070_50700501_44_dialog_content = "それで…半年前、海でリン家の商船に何があったんですか？",
  ui_story_5070_50700501_45_dialog_content = "海賊だ。",
  ui_story_5070_50700501_46_dialog_content = "リン家の船は習わしに従い、時季がくると済の国の港を出航した。",
  ui_story_5070_50700501_47_dialog_content = "しかし、アストラ近海に差し掛かった頃、\n船員が記録にない積み荷を発見した。",
  ui_story_5070_50700501_48_dialog_content = "時を同じくして、他の者が乗客の中に紛れ込んだ海賊を見つけたのだ。",
  ui_story_5070_50700501_49_dialog_content = "リン家の船で密輸品を運ぼうとしたんですか？",
  ui_story_5070_50700501_50_dialog_content = "いかにも。",
  ui_story_5070_50700501_51_dialog_content = "しかし、その企みが露見し、海賊たちは暴挙に出た。\n人々を傷つけ、商船を奪ってしまったのだ。",
  ui_story_5070_50700501_52_dialog_content = "結局、生き残ったのはそれがしと、\n船に医者として乗船しておったリンセイのみであった。",
  ui_story_5070_50700501_53_dialog_content = "シュウさんはその時落水して重傷を負ったんだ。\n命も危なかったんだよ。",
  ui_story_5070_50700501_54_dialog_content = "命はなんとか取り留めたけど、足はどうしようもなくて…\n今みたいなことになっちゃったんだ…",
  ui_story_5070_50700501_55_dialog_content = "リンセイ、自責することはない。\n命が助かり、それがしは感謝しておるのだ。",
  ui_story_5070_50700501_56_dialog_content = "ほんとにそう思ってるなら、ちゃんと休んでよ。",
  ui_story_5070_50700501_57_dialog_content = "嫌なお客さんが来るたび、\nすぐに飛び出していっちゃうんだから――",
  ui_story_5070_50700501_58_dialog_content = "イヤなお客さん？",
  ui_story_5070_50700501_59_dialog_content = "グアアッ！",
  ui_story_5070_50700501_60_dialog_content = "あ、また来た！",
  ui_story_5070_50700501_61_dialog_content = "ちょっとでも気を抜くと、すぐに出てくるんだ。\nご飯の時も、寝る時も、おちおちしてられないよ！",
  ui_story_5070_50700501_62_dialog_content = "千機――",
  ui_story_5070_50700501_63_dialog_content = "熾焔断灰！",
  ui_story_5070_50700501_64_dialog_content = "…",
  ui_story_5070_50700501_65_dialog_content = "シュウさん！今言ったばかりでしょ！？\nそんな調子じゃ、いつまで経っても治らないよ！",
  ui_story_5070_50700501_66_dialog_content = "余生を送るだけの身。この命に大した重みはない。",
  ui_story_5070_50700501_67_dialog_content = "しかし、リン家の当主は…",
  ui_story_5070_50700501_68_dialog_content = "約束したのだ。このまま当主が獄中で\n無念のまま逝くのを見てられようか。",
  ui_story_5070_50700501_69_dialog_content = "ゆえに、それがしも死ぬわけにはいかぬ。",
  ui_story_5070_50700501_70_dialog_content = "何としても龍州へ戻り、リン家の濡れ衣を晴らさねばならん。",
  ui_story_5070_50700501_71_dialog_content = "それで私が来た時も警戒してたんですね。",
  ui_story_5070_50700501_72_dialog_content = "お二人はずっとカラクリ獣に悩まされてるんですか？",
  ui_story_5070_50700501_73_dialog_content = "いや、西からの傭兵にも悩まされておる。",
  ui_story_5070_50700501_74_dialog_content = "あの海賊どもにはおそらく、\n後ろ盾となる勢力がついておるのだろう。",
  ui_story_5070_50700501_75_dialog_content = "真相とそれがしらをこの客地で亡き者にせんと、\n刺客を送り込んでおる。",
  ui_story_5070_50700501_76_dialog_content = "つまり、リン家が永遠に汚点をぬぐえぬよう図っておるのだ。",
  ui_story_5070_50700501_77_dialog_content = "シュウさんはこんな時までリン家のことばっかりなんだから…\nまったく、いい人だかなんだか分からないよ。",
  ui_story_5070_50700501_78_dialog_content = "グアアッ！",
  ui_story_5070_50700501_79_dialog_content = "うひゃあ！まただ！",
  ui_story_5070_50700501_80_dialog_content = "先刻は璇璣卿とは知らず、失礼した。\n許されよ。",
  ui_story_5070_50700501_81_dialog_content = "今はどうか退がられよ。\nそれがしの招いた災いの巻き添えにならぬよう。",
  ui_story_5070_50700501_82_dialog_content = "巻き添えとは言えません。",
  ui_story_5070_50700501_83_dialog_content = "むしろ当事者と言えるんです。",
  ui_story_5070_50700501_84_dialog_content = "私がこのカラクリ獣たちを設計したのは…",
  ui_story_5070_50700501_85_dialog_content = "どこの馬の骨かも知れない職人たちに真似させて、\n人を傷つけるためじゃありません！",
  ui_story_5070_50700501_86_dialog_content = "ちょうど手がかりが途切れて困ってたんです。\nまさか向こうから来てくれるとは思っていませんでしたよ。",
  ui_story_5070_50700501_87_dialog_content = "むしろ、お二人には感謝しないと！",
  ui_story_5070_50700501_88_dialog_content = "シュウ様、共通の敵ができたみたいですね。",
  ui_story_5070_50700501_89_dialog_content = "…遠回りしたけど、結局仲間だったんだね！",
  ui_story_5070_50700501_90_dialog_content = "警戒して損しちゃったな。お互いあれこれ探り合って、\n敵が見てたら、大笑いされちゃうよ。",
  ui_story_5070_50700501_91_dialog_content = "ボクちゃん、そう怒らないで。\nコイツらを倒したら、面白いおもちゃをあげるわ。",
  ui_story_5070_50700501_92_dialog_content = "コロコロ玉なんてどう？",
  ui_story_5070_50700501_93_dialog_content = "ついでにシュウ様の車いすも修理しましょうか？\n新しい機能を付けるなんてどうです？",
  ui_story_5070_50700501_94_dialog_content = "ご厚意かたじけない。",
  ui_story_5070_50700501_95_dialog_content = "しかし、車椅子はただの足代わり。\n余計なものを付ければ、かえって不便であろう。",
  ui_story_5070_50700501_96_dialog_content = "あはは。シュウ様は機巧師でもないのに、\nカラクリの本当の意義を分かってらっしゃるんですね。",
  ui_story_5070_50700501_97_dialog_content = "影に隠れて、他人の設計を盗むことしかできないヤツらより\n100倍素晴らしいですよ！",
  ui_story_5070_50700502_1_dialog_content = "以上がリン家の…今の状況よ。",
  ui_story_5070_50700502_2_dialog_content = "半年前の密輸騒ぎでリン家商会が大いに失墜したとは聞いておったが、\nかようなことがあったとは初めて聞いた。",
  ui_story_5070_50700502_3_dialog_content = "ユエの言うた通りじゃとすると、\nこの度の判決は独断がすぎるのう。",
  ui_story_5070_50700502_4_dialog_content = "リン家が密輸に手を染めたとの証はないが、\n情況証拠はそろっておる…",
  ui_story_5070_50700502_5_dialog_content = "リン家は潔白を証明しようにも術がなく…\n罪を負うしかなかったか。",
  ui_story_5070_50700502_6_dialog_content = "渾天儀を失っても、危険を冒し海に出たのも、\nこれで納得がいったのう。",
  ui_story_5070_50700502_7_dialog_content = "航路を維持し、商会を再興せんとしたということじゃな。",
  ui_story_5070_50700502_8_dialog_content = "ふむ…この蜃風号の乗客は真に…おのおの難儀じゃのう。",
  ui_story_5070_50700502_9_dialog_content = "だから、何がなんでも予定通り蜃風号を帰航させたかったんだね。",
  ui_story_5070_50700502_10_dialog_content = "PlayerName。",
  ui_story_5070_50700502_11_dialog_content = "どうしたの？急にそんな怖い顔して…",
  ui_story_5070_50700502_12_dialog_content = "海の上は何が起こるか分からぬ。古来危険を冒し使者に出た者で\n無事に帰郷した者は十に一人もおらぬ。",
  ui_story_5070_50700502_13_dialog_content = "航路もしかと定まっておらぬうえ、襲撃にも遭い、\n行く手を未知が塞いでおる。",
  ui_story_5070_50700502_14_dialog_content = "それでも蜃風号に乗らんとする者には、\n未曽有の危機が待ち受けていることであろう。",
  ui_story_5070_50700502_15_dialog_content = "ユエはリン家商会を再興せねばならぬ。\nわらわも重き務めを背負っておる。",
  ui_story_5070_50700502_16_dialog_content = "わらわどもは危険を冒さねばならぬ。\nその結果を受け入れる覚悟もできておる。",
  ui_story_5070_50700502_17_dialog_content = "じゃが、PlayerName。お主は別じゃ。",
  ui_story_5070_50700502_18_dialog_content = "…灼華郡主として言えば、お主を巻き込んだのは、\nわらわがあの時考え得る唯一の方法じゃった。",
  ui_story_5070_50700502_19_dialog_content = "じゃが、友として、わらわはやはりお主の安寧を願っておる…",
  ui_story_5070_50700502_20_dialog_content = "ここでやめると言うても、納得じゃ。",
  ui_story_5070_50700502_21_dialog_content = "何を言うのかと思ったら…",
  ui_story_5070_50700502_22_dialog_content = "ん？",
  ui_story_5070_50700502_23_dialog_content = "君は自分が僕を巻き込んだって言うけど――",
  ui_story_5070_50700502_24_dialog_content = "アストラの使節だろうと、空の末裔としてであろうと、\nPlayerName個人としてであろうと――",
  ui_story_5070_50700502_25_dialog_content = "この使命を受けたのは、僕自身がじっくり考えた上での選択だよ。",
  ui_story_5070_50700502_26_dialog_content = "それに、友だちとして、君の力になりたいんだ。",
  ui_story_5070_50700502_27_dialog_content = "PlayerName…ならば、わらわはすべての力を尽くして、\nお主の航海の安全を守ろう。",
  ui_story_5070_50700502_28_dialog_content = "何も起こらなければよいのじゃが…",
  ui_story_5070_50700502_29_dialog_content = "まったくもう、まだ出航もしてないっていうのに\nどうして沈みきった、泣きそうな顔してるのかしら？",
  ui_story_5070_50700502_30_dialog_content = "…",
  ui_story_5070_50700502_31_dialog_content = "この私が百戦錬磨の勇士と、どんな病気も治せる名医を連れてきたわ。\n万が一のことがあっても大丈夫よ。",
  ui_story_5070_50700502_32_dialog_content = "それでもダメなら、私がいるわ。",
  ui_story_5070_50700502_33_dialog_content = "今はもう鄴の国の役人じゃないけど、\nタンドウ様の命なら、剣の山だろうと火の海だろうとどこにだって行くわ！",
  ui_story_5070_50700502_34_dialog_content = "殿下、センキョク様がお戻りになりました！",
  ui_story_5070_50700502_35_dialog_content = "そのようじゃのう。かような話し方をするのはあやつしかおらぬ。",
  ui_story_5070_50700502_36_dialog_content = "璇璣卿はいつでも突拍子もない、\n頼もしいことを言いおるのう。",
  ui_story_5070_50700502_37_dialog_content = "今度は本当に剣の山や火の海に行ってもらおうか。",
  ui_story_5070_50700502_38_dialog_content = "あはは。冗談はこのくらいにして…",
  ui_story_5070_50700502_39_dialog_content = "今さっき蜃風号が襲撃に遭ったらしいわね。\n船体を一通り調べないといけないわ。",
  ui_story_5070_50700502_40_dialog_content = "まさか火吹き蟹の襲撃に備えるために、\n船を整備する日が来るなんて思わなかったわ。",
  ui_story_5070_50700502_41_dialog_content = "動力供給と航路案内機能も\n改造か強化を施さなきゃいけないわね。",
  ui_story_5070_50700502_42_dialog_content = "安心して。安全に航海できるように、\n全力で船を直してあげるわ。",
  ui_story_5070_50700601_1_dialog_content = "（バイス、カレンへ）",
  ui_story_5070_50700601_2_dialog_content = "（返信が遅くなってごめんね。あっという間に出航の日になった）",
  ui_story_5070_50700601_3_dialog_content = "（出航の日まで、全員が船の最終整備に駆け回った）",
  ui_story_5070_50700601_4_dialog_content = "リーさん！何人か人を集めて、\n船体の重要な部分に防火塗料を塗っておいて。",
  ui_story_5070_50700601_5_dialog_content = "火吹き蟹の襲撃だけじゃなく、\n炉で事故があった時にも対応できるわ。",
  ui_story_5070_50700601_6_dialog_content = "私はもう一度水密性能を検査してくるわね。",
  ui_story_5070_50700601_7_dialog_content = "それから、誰か船長がどこに行ったか知らない？\nアストラのエネルギー貯蔵装置を予備として買っておいてほしいんだけど。",
  ui_story_5070_50700601_8_dialog_content = "海の上ではどんなことも起こりうるわ。\n万が一のために予備のエネルギーを持っておかなくちゃ。",
  ui_story_5070_50700601_9_dialog_content = "シュウ様？",
  ui_story_5070_50700601_10_dialog_content = "ここ数日業務で忙しく、ご挨拶が遅れました…",
  ui_story_5070_50700601_11_dialog_content = "密輸事件について、真相をお話しくださるとのこと感謝申し上げます。\nリン家の濡れ衣もこれで晴れることでしょう。",
  ui_story_5070_50700601_12_dialog_content = "シュウ様が無事にお戻りになれば、当主も奮い立ち、\nどのような困難も乗り越えられるに違いありません。",
  ui_story_5070_50700601_13_dialog_content = "己のすべきことをするまでのこと。それに…\nそれがしは当主を守れんかった。",
  ui_story_5070_50700601_14_dialog_content = "海賊どもが再び襲撃してくるやもしれぬ。",
  ui_story_5070_50700601_15_dialog_content = "半年前の事故で、賊どもの動きはおおかたつかめた。",
  ui_story_5070_50700601_16_dialog_content = "それをもとに、前もって対応策を練っておこう。",
  ui_story_5070_50700601_17_dialog_content = "ビャクダン、カンゾウ、ハッカ、葛根…",
  ui_story_5070_50700601_18_dialog_content = "ご主人、あるだけ全部ちょうだい！",
  ui_story_5070_50700601_19_dialog_content = "おや、ずいぶんと太っ腹だね。",
  ui_story_5070_50700601_20_dialog_content = "船に乗ってるみんなの身体を診なきゃいけないんだ。",
  ui_story_5070_50700601_21_dialog_content = "船酔いやら風邪やら、よく使う薬は多ければ多いほど安心だからね。",
  ui_story_5070_50700601_22_dialog_content = "働き出すと身体のことなんて顧みない人たちばっかりなんだ。\nボクがちゃんと準備しておいてあげないと！",
  ui_story_5070_50700601_23_dialog_content = "薬のあとは食べ物だね。\n海でも健康を保てるようなものを買わなきゃ。",
  ui_story_5070_50700601_24_dialog_content = "キュウ、別れのあいさつの文は書き終わったか？",
  ui_story_5070_50700601_25_dialog_content = "はい。私が挨拶すべき相手はそう多くはございませんから。",
  ui_story_5070_50700601_26_dialog_content = "殿下こそ、多くの方にお別れの文をお書きになったのですね？",
  ui_story_5070_50700601_27_dialog_content = "うむ。この旅で多くの友ができたからのう。\nアストラの要人とも少なからず縁があった。",
  ui_story_5070_50700601_28_dialog_content = "この先の交流のためにも、縁をつないでおかねばな。",
  ui_story_5070_50700601_29_dialog_content = "そうじゃ、双閣港の商会連盟にも文を書かねばならんのじゃった。",
  ui_story_5070_50700601_30_dialog_content = "双閣港にも海賊と手を結ぶ賊が出たとあっては、\nしかと取り締まっておかねばならぬ。",
  ui_story_5070_50700601_31_dialog_content = "（僕まで買い出しに駆り出され、影ノ街を何往復もしてアストラ大陸の物資を調達した）",
  ui_story_5070_50700601_32_dialog_content = "（そうこうしてるうちに、アストラ大陸の使節という役割にも\n徐々に実感が湧いてきた）",
  ui_story_5070_50700601_33_dialog_content = "（この手紙を出したら、蜃風号も出航する）",
  ui_story_5070_50700601_34_dialog_content = "（皆の努力が実を結んで、この航海が無事に終わることを願ってる）",
  ui_story_5070_50700601_35_dialog_content = "（僕も必ず龍州での面白い話をいっぱい携えて帰って、\n君たちに聞かせてあげるね）",
  ui_story_5070_50700601_36_dialog_content = "おや、PlayerNameの旦那じゃありませんか。",
  ui_story_5070_50700601_37_dialog_content = "あ、君はこの間の占い師さんだね！？",
  ui_story_5070_50700601_38_dialog_content = "ちょいとお待ちを。占って差し上げますよ。\n旦那は…今、手紙を出してきましたね？",
  ui_story_5070_50700601_39_dialog_content = "…",
  ui_story_5070_50700601_40_dialog_content = "すぐ後ろにクーリエ隊の建物があるし、\n今そこから出て来たばっかりなんだけど…",
  ui_story_5070_50700601_41_dialog_content = "ははは、冗談ですよ。",
  ui_story_5070_50700601_42_dialog_content = "僕はテンカンといいましてね。\n旦那と同じく、蜃風号に乗るんです。",
  ui_story_5070_50700601_43_dialog_content = "ちょうど行先も同じですし、\n一緒に船に戻りませんか？",
  ui_story_5070_50700601_44_dialog_content = "そうだね。それはそうと、\n君もここにいるってことは手紙を出しに来たの？",
  ui_story_5070_50700601_45_dialog_content = "はあ…それなんですがね。",
  ui_story_5070_50700601_46_dialog_content = "出航する前にアストラのご馳走を最後にもう一度食べたいと思って出てきたんですがね、\n今日に限って運が回ってきませんで。",
  ui_story_5070_50700601_47_dialog_content = "いくら待っても、一人として縁のある方が\n現れなかったんですよ。",
  ui_story_5070_50700601_48_dialog_content = "いやはや、残念です。",
  ui_story_5070_50700601_49_dialog_content = "縁のある人に会えなかったことと食事と、\n何の関係があるの？",
  ui_story_5070_50700601_50_dialog_content = "そりゃあ決まってますでしょう。\n僕は見るからに貧しそうですがね――",
  ui_story_5070_50700601_51_dialog_content = "実は、正真正銘の一文無しなんですよ。",
  ui_story_5070_50700601_52_dialog_content = "一文無しって…よく旅に出て来たね。",
  ui_story_5070_50700601_53_dialog_content = "僕は他の乗客とは違いますからねぇ。\n目的なんざありやしません。",
  ui_story_5070_50700601_54_dialog_content = "はるか遠くを吹く風に興味があったもんで、\n物見遊山に来たまでのことです。",
  ui_story_5070_50700601_55_dialog_content = "未知の大陸も、玄関先の水たまりも、\n僕にとっちゃ何の違いもないんですよ。",
  ui_story_5070_50700601_56_dialog_content = "…そうなんだ。",
  ui_story_5070_50700601_57_dialog_content = "（何を言ってるか、よく分からないのに、\n何だか道理を説かれてるような気がしてくる…）",
  ui_story_5070_50700601_58_dialog_content = "わりと理にかなったこと言ってるでしょう？",
  ui_story_5070_50700601_59_dialog_content = "きちんと占ってみてはいかがです？",
  ui_story_5070_50700601_60_dialog_content = "僕の「万類天斗卦」には、「子丑寅卯」に始まる十二支がありましてね。\nそれぞれ陰と陽に分かれてるんです。",
  ui_story_5070_50700601_61_dialog_content = "天意を知ることもできれば、未来も占えるんです。\nこの機会を逃したら次はありませんよ。",
  ui_story_5070_50700601_62_dialog_content = "「子」、「丑」？それって動物だよね？\n動物で何が分かるの？",
  ui_story_5070_50700601_63_dialog_content = "そりゃあもう、奥深いんです。",
  ui_story_5070_50700601_64_dialog_content = "では、こうしましょう。蜃風号はすぐそこです。\nあの船を手本に、歩きながらお話しましょう。",
  ui_story_5070_50700601_65_dialog_content = "あの船にはネズミがいて、牛もいるんです。\n12の動物がそろってるんですが、ご存じですか？",
  ui_story_5070_50700601_66_dialog_content = "船にネズミがいるのは分かるけど、\n牛はいないでしょ？",
  ui_story_5070_50700601_67_dialog_content = "龍州の者は連想や心象ってのを重んじましてね。\n形の似たものの名を取って、ものに名前を付けるんです。",
  ui_story_5070_50700601_68_dialog_content = "ほら、あの帆柱を固定するくさびは「鼠橋」というんですよ。",
  ui_story_5070_50700601_69_dialog_content = "舷の上に据えられた柵の手すりは「牛柵」――",
  ui_story_5070_50700601_70_dialog_content = "船倉の上の甲板は「馬面」といって、\n船の骨組みで一番重要な部分は、ご存じの通り「龍骨」というんです。",
  ui_story_5070_50700601_71_dialog_content = "そんな呼び方があったんだね。",
  ui_story_5070_50700601_72_dialog_content = "ええ。つまり、この船と同じで、僕の卦は万物と呼応してるんですねぇ。\n万事を占えるってわけです。",
  ui_story_5070_50700601_73_dialog_content = "じゃあ、今回の航海がどうなるか分かる？",
  ui_story_5070_50700601_74_dialog_content = "そりゃあ…この間蜃風号が襲撃された時も、\n占ってみたんですがね――",
  ui_story_5070_50700601_75_dialog_content = "陰の丑と陰の午と出ましてねぇ。",
  ui_story_5070_50700601_X75_dialog_content = "死した牛は動かず、木の馬はいななかず――\nつまり、この船は動かないって暗示のはずだったんですが…",
  ui_story_5070_50700601_76_dialog_content = "でも、蜃風号はもうすぐ出航するよ。",
  ui_story_5070_50700601_77_dialog_content = "そうなんですよねぇ。どうやら、あの卦象にはまだ何かありそうです。\n「馬面」や「牛柵」の近くに行けば、啓示でも受けられますかねぇ。",
  ui_story_5070_50700601_78_dialog_content = "PlayerName、いかさま師の申すことなど信じてはならぬ。",
  ui_story_5070_50700601_79_dialog_content = "それはあんまりですねぇ、タンドウ殿下。\n僕はただ自分の技と腕で稼いでるだけなんですが。",
  ui_story_5070_50700601_80_dialog_content = "その者にかまわず、乗船されよ、PlayerName。\n乗客はほぼそろったようじゃ。",
  ui_story_5070_50700601_81_dialog_content = "…最後のお客様を名簿に基づき確認します。",
  ui_story_5070_50700601_82_dialog_content = "シュウ様、リンセイ医師、タンドウ殿下、キュウ、それからPlayerName。",
  ui_story_5070_50700601_83_dialog_content = "船職人のリーとソン、センキョクも船匠として乗船し、\n龍州へ戻ります。",
  ui_story_5070_50700601_84_dialog_content = "これで全員乗船しました。",
  ui_story_5070_50700601_85_dialog_content = "…",
  ui_story_5070_50700601_86_dialog_content = "出航前に乗客の皆様の心配事を増やすような真似は、\n船長として控えるべきでしょうが――",
  ui_story_5070_50700601_87_dialog_content = "今回の航海は特別です。\n最後にもう一度申し上げます。",
  ui_story_5070_50700601_88_dialog_content = "今、この蜃風号には海上で航路を決める渾天儀がありません。",
  ui_story_5070_50700601_89_dialog_content = "船の進む方向はすべて私たち自身で探り、決めていかねばなりません。",
  ui_story_5070_50700601_90_dialog_content = "そのうえ、海の上ではいつ嵐が起こり、暗鬼が現れるとも分かりません。\nさらには未知の敵が待ち伏せている可能性も…",
  ui_story_5070_50700601_91_dialog_content = "今回私たちを待ち受けている危険は、\n今までのどの航海よりも大きくなっています。",
  ui_story_5070_50700601_92_dialog_content = "乗船を取りやめたい方は、お申し出ください。",
  ui_story_5070_50700601_93_dialog_content = "（誰も下船しようとしない。やっぱり覚悟のある人たちだけが残ってるんだな）",
  ui_story_5070_50700601_94_dialog_content = "蜃風号を信じてくださり、ありがとうございます。\n船長として皆様にお約束します。必ずや全力を尽くしこの航海を終えてみせます。",
  ui_story_5070_50700601_95_dialog_content = "蜃風号、出航！",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>ザア――ザア――</color>",
  ui_story_5070_50700701_2_dialog_content = "（出航して、もう何日も経った。船でアストラ大陸を離れるのはこれが初めてだ）",
  ui_story_5070_50700701_3_dialog_content = "（青い空の下で、しぶきを上げる波。\nさわやかな潮風と向こう側で待っている未知の大陸…それから、少しの孤独感）",
  ui_story_5070_50700701_4_dialog_content = "そんなにじっと見つめちゃって、何か心配事でも？",
  ui_story_5070_50700701_5_dialog_content = "あ、センキョク！",
  ui_story_5070_50700701_6_dialog_content = "船で海を渡るのって、巨像に乗ってるのと全く違うなと思って。",
  ui_story_5070_50700701_7_dialog_content = "そう？じゃあ、巨像はどんな感じなの？",
  ui_story_5070_50700701_8_dialog_content = "あなたが自分からその話題に触れるなんてめずらしいわね。\n巨像も広義にはカラクリの一種よね！？",
  ui_story_5070_50700701_9_dialog_content = "それは…ちょっと定義が広すぎるんじゃ…？",
  ui_story_5070_50700701_10_dialog_content = "そんなことはどうでもいいのよ。",
  ui_story_5070_50700701_11_dialog_content = "それより、蜃風号よりもずっと大きく複雑な物を操縦するのに、\n本当にあなた1人だけで大丈夫なの？",
  ui_story_5070_50700701_12_dialog_content = "速度はどのくらい出るのかしら？燃費は？\n季節が変わると、材質に変化が起こったりするのかしら？",
  ui_story_5070_50700701_13_dialog_content = "航空機って動力源だけじゃなく、形によって表面風速が違うから、\n揚力も変わるわよね…",
  ui_story_5070_50700701_14_dialog_content = "この前はちゃんと答えてくれなかったし、\n今日こそ教えてちょうだい。",
  ui_story_5070_50700701_15_dialog_content = "ちょ、ちょっと待って…\nもしかして、話題にしちゃいけないことを話題にしちゃった…？",
  ui_story_5070_50700701_16_dialog_content = "あはは。機密だっていうなら、無理強いはしないわ。",
  ui_story_5070_50700701_17_dialog_content = "機密じゃないけど、僕にもよく分からないんだ。",
  ui_story_5070_50700701_18_dialog_content = "蜃風号では、舷も舵も帆柱も…",
  ui_story_5070_50700701_19_dialog_content = "船上のあらゆることを\nユエたちが自分たちで処理、操作してるでしょ？",
  ui_story_5070_50700701_20_dialog_content = "たとえば、風向きや風力が変われば、\nすぐに自分たちで判断して、航路を調整してる。",
  ui_story_5070_50700701_21_dialog_content = "でも、巨像では、そういうことも全部、\nソラヴァンが自分でデータベースを調べて解決してくれるんだ。",
  ui_story_5070_50700701_22_dialog_content = "僕はただ、ポイントとなる指示を\n言葉か旋律で出せばいいだけなんだ。",
  ui_story_5070_50700701_23_dialog_content = "単純な操縦ではなく、カラクリに合理的な行動の実施を任せて、\n自分は指揮をするだけってことね。",
  ui_story_5070_50700701_24_dialog_content = "まるで神話みたいじゃない！",
  ui_story_5070_50700701_25_dialog_content = "神話？龍州の？",
  ui_story_5070_50700701_26_dialog_content = "そうよ。龍州の古い書物に、太古の時代には、天を呑み、\n月を食らう、それは大きな「巨霊」がいたって記載があるの。",
  ui_story_5070_50700701_27_dialog_content = "天人は巨霊を操り、山や海を渡って四方を征伐し、\n「巨霊の御者」と呼ばれた、とも書かれてるの。",
  ui_story_5070_50700701_28_dialog_content = "わあ…それはすごいね…\nソラヴァンには天を呑み、月を食らうなんてことできないな…",
  ui_story_5070_50700701_29_dialog_content = "どんなに高く飛んでも、空と月はいつだって遠い所にあるから…",
  ui_story_5070_50700701_30_dialog_content = "そうとも限らないわよ。",
  ui_story_5070_50700701_31_dialog_content = "え？",
  ui_story_5070_50700701_32_dialog_content = "甲板に出てきたのは、太陽の高度を測るためよ。",
  ui_story_5070_50700701_33_dialog_content = "「太陽」って…何かのたとえとかじゃなくて？\n僕たちの頭上にある、あの太陽のこと？",
  ui_story_5070_50700701_34_dialog_content = "龍州には古い天測航法が残っていてね。",
  ui_story_5070_50700701_35_dialog_content = "星座盤一つあれば、太陽や月、さらには星座との距離を測れるの。",
  ui_story_5070_50700701_36_dialog_content = "高度も測れて、軌道も分かるなら――",
  ui_story_5070_50700701_37_dialog_content = "ちょっと改造さえすれば、あなたの巨像が\n天を呑み、月を食らうカラクリ獣になるのも夢じゃないわ。",
  ui_story_5070_50700701_38_dialog_content = "明らかに絵空事だって分かってるのに、\nセンキョクが言うと、冗談に思えないな…",
  ui_story_5070_50700701_39_dialog_content = "あはは、私の能力を認めてくれるのね。\nありがとう、PlayerName。",
  ui_story_5070_50700701_40_dialog_content = "でも、カラクリがそうであるように、\n何事も一歩一歩着実に進めていかないとね。",
  ui_story_5070_50700701_41_dialog_content = "今は天に到達することも、月に触れることもできないけど…",
  ui_story_5070_50700701_42_dialog_content = "太陽の高度や角度といった数値があるだけで、\nすでにいろんなことが出来るのよ。",
  ui_story_5070_50700701_43_dialog_content = "たとえば、リン家の海図と合わせれば、\n蜃風号の現在位置が分かるわ。",
  ui_story_5070_50700701_44_dialog_content = "じゃあ、常に位置を確認してれば、\n海上でも道に迷うことはないんだね！",
  ui_story_5070_50700701_45_dialog_content = "理屈はそうだけど、実際はそう簡単じゃないの。\n海の状況は激しく変わるから、人の手で行う測量だけじゃ確実な航行は難しいわ。",
  ui_story_5070_50700701_46_dialog_content = "だからこそ、星の巡りをもとに精確に位置を測れる渾天儀は\nリン家の宝とされてきたのよ。",
  ui_story_5070_50700701_47_dialog_content = "渾天儀とそれを扱う天測士がいれば、\n航路を外れることの方が難しいくらいよ。",
  ui_story_5070_50700701_48_dialog_content = "本当に残念よね…",
  ui_story_5070_50700701_49_dialog_content = "確か、船が海賊に襲われて、\n渾天儀も船と一緒に行方知れずになっちゃったんだよね…",
  ui_story_5070_50700701_50_dialog_content = "そうよ。だから今、私がその代わりを務めてるの。",
  ui_story_5070_50700701_51_dialog_content = "今まではカラクリが人の代わりに仕事をしてきたのに、\nまさか機巧師がカラクリの代わりをする日が来るとは思わなかったわ。",
  ui_story_5070_50700701_52_dialog_content = "ということは、センキョクは蜃風号のナビゲーターなんだね。",
  ui_story_5070_50700701_53_dialog_content = "ただの代役よ。",
  ui_story_5070_50700701_54_dialog_content = "璇璣卿、そう謙遜せずともよい。",
  ui_story_5070_50700701_55_dialog_content = "「センキョク」とは「璇璣」のこと。\n渾天儀の別称じゃ。",
  ui_story_5070_50700701_56_dialog_content = "そして「璇璣卿」はお主の称号。",
  ui_story_5070_50700701_57_dialog_content = "センキョクが渾天儀の役を務めるは、\n本来の務めを果たすということじゃ。",
  ui_story_5070_50700701_58_dialog_content = "僕の勘違いかな？今までセンキョクが\n本来の務めを果たしてなかったみたいに聞こえるんだけど？",
  ui_story_5070_50700701_59_dialog_content = "鄴の国の要職にあった者が文一つを残して、\n務めを退いてしもうたのじゃ。",
  ui_story_5070_50700701_60_dialog_content = "名声高き大機巧師がその工房と多くのカラクリを捨て、\n独り傘を片手に放浪の旅に出てしもうたのじゃよ。",
  ui_story_5070_50700701_61_dialog_content = "本来の務めを果たすのはよいが、\nまずはかつての行いを釈明してもらいたいのう。",
  ui_story_5070_50700701_62_dialog_content = "タンドウ様…",
  ui_story_5070_50700701_63_dialog_content = "殿下、センキョク様にもきっとお考えがあったのでしょう。",
  ui_story_5070_50700701_64_dialog_content = "…",
  ui_story_5070_50700701_65_dialog_content = "大した考えなんてありません。",
  ui_story_5070_50700701_66_dialog_content = "ただ、設計図が盗まれたうえに、\nちょうど流派からアストラ大陸で秘宝を探してきてほしいと言われて…",
  ui_story_5070_50700701_67_dialog_content = "急なことだったので、きちんと挨拶できなかっただけです。",
  ui_story_5070_50700701_68_dialog_content = "今そのことを掘り返すなんて、まさか私が機巧術をお教えしなかったことに\nまだ腹を立てていらっしゃるんですか？",
  ui_story_5070_50700701_69_dialog_content = "あの時は私もまだ子どもだったんです。\nどうか広いお心でお許しください。",
  ui_story_5070_50700701_70_dialog_content = "子どもだったと申すか…\n今も変わっておらぬように見えるがのう…",
  ui_story_5070_50700701_71_dialog_content = "ぷっ――あ…ご、ごめん…",
  ui_story_5070_50700701_72_dialog_content = "タンドウがそんな顔するのは珍しいなと思って。\n何だか普段と違う一面を見た気がするよ。",
  ui_story_5070_50700701_73_dialog_content = "な、なんと！お主まで…！",
  ui_story_5070_50700701_74_dialog_content = "か、かような取るに足らぬ失態、\nどうか心に留め置かぬよう。",
  ui_story_5070_50700701_75_dialog_content = "わらわもここで雑談などしておられぬ。",
  ui_story_5070_50700701_76_dialog_content = "璇璣卿には天測の務めがあり…",
  ui_story_5070_50700701_77_dialog_content = "PlayerNameも客でありながら、\n自ら進んで海の様子をうかがい、務めを果たしておる。",
  ui_story_5070_50700701_78_dialog_content = "無為に過ごす己を恥じねばならぬのう。\nお主らの邪魔など…もってのほかじゃ。",
  ui_story_5070_50700701_79_dialog_content = "気にしないで。僕は事前に暗鬼の存在を感知できるから、\n海の様子をうかがうのは…",
  ui_story_5070_50700701_80_dialog_content = "待って！",
  ui_story_5070_50700701_81_dialog_content = "あら。タンドウ様は他人の邪魔になるのはお嫌いだけど…",
  ui_story_5070_50700701_82_dialog_content = "そんな礼儀は、持ち合わせてないヤツらがいるみたいね。",
  ui_story_5070_50700701_83_dialog_content = "堂々とPlayerNameの邪魔をしに来たわ。",
  ui_story_5070_50700702_1_dialog_content = "ふぅ…やっと倒せたね。\nまさか急にこんなにたくさんの暗鬼が襲ってくるとは。",
  ui_story_5070_50700702_2_dialog_content = "でも、これはいい知らせよ。",
  ui_story_5070_50700702_3_dialog_content = "暗鬼が活発に活動してることが！？",
  ui_story_5070_50700702_4_dialog_content = "だって、船がアストラ近海の暗鬼の活動域に入ったってことじゃない。",
  ui_story_5070_50700702_5_dialog_content = "天測尺や星座盤は精確な数値を出せるけど、\n人の目だけだと、そうはいかない。",
  ui_story_5070_50700702_6_dialog_content = "計算で、近くに来たことくらいは分かっても、\nこんな果てしない海の上じゃ数値を確認することもできないし…",
  ui_story_5070_50700702_7_dialog_content = "ちょうど裏付けがほしいって思ってたの。\n暗鬼が持ってきてくれたわ。",
  ui_story_5070_50700702_8_dialog_content = "自ら犠牲となって、私の検証を手伝ってくれたのよ。",
  ui_story_5070_50700702_9_dialog_content = "だから私は、胸いっぱいの感謝を抱いて、\nヤツらを片付けたの。",
  ui_story_5070_50700702_10_dialog_content = "今の話を暗鬼が聞いたら、どんな気持ちになるんだろう…",
  ui_story_5070_50700702_11_dialog_content = "計算が間違ってなかったってことは、\n蜃風号は順調に航海を続けてるってことよ。",
  ui_story_5070_50700702_12_dialog_content = "風向きもちょうどいい具合に船を進めてくれてるわ。\nこれなら燃料も節約できそうね。",
  ui_story_5070_50700702_13_dialog_content = "ソンさん！仕事よ！",
  ui_story_5070_50700702_14_dialog_content = "…センキョク様はあのようにおっしゃっていましたが、\n妖魔の執拗さは侮れません。警戒を怠らぬようにいたしましょう。",
  ui_story_5070_50700702_15_dialog_content = "殿下は、出来る限り私の側を離れられぬよう。",
  ui_story_5070_50700702_16_dialog_content = "アストラ大陸の近くには、龍州よりも多くの妖魔が潜んでおります。",
  ui_story_5070_50700702_17_dialog_content = "妖魔？前にも聞いたことある。\nそれって龍州での暗鬼の呼び方なの？",
  ui_story_5070_50700702_18_dialog_content = "いかにも。龍州では、アストラの者が暗鬼と呼ぶ物を\n妖魔と呼んでおる。",
  ui_story_5070_50700702_19_dialog_content = "シュウさん…",
  ui_story_5070_50700702_20_dialog_content = "中で休んでいなくて大丈夫なんですか？\nさっきリンセイが薬を飲ませるって騒いでましたけど…",
  ui_story_5070_50700702_21_dialog_content = "リンセイは患者に心を尽くす。",
  ui_story_5070_50700702_22_dialog_content = "しかし、不自由な身とはなったものの、\nまだ剣は振るえる。大事ない。",
  ui_story_5070_50700702_23_dialog_content = "…",
  ui_story_5070_50700702_24_dialog_content = "シュウ…殿。",
  ui_story_5070_50700702_25_dialog_content = "タンドウ殿下、一介の浪人にお気遣いくださるな。\n各位もかしこまることはない。",
  ui_story_5070_50700702_26_dialog_content = "貴公も休まれよ。見張りはそれがしが代わりに務めよう。",
  ui_story_5070_50700702_27_dialog_content = "あ、僕は大丈夫です。この辺りは危険ですし、\n何人かで見張っていた方が安心です。",
  ui_story_5070_50700702_28_dialog_content = "ならば、引き続き貴公にも任せるとしようか。\n龍州の近海に入れば、少しは楽になろうしな。",
  ui_story_5070_50700702_29_dialog_content = "何しろ龍州では、暗黒の生き物の動きは\nさほど活発ではないからな。",
  ui_story_5070_50700702_30_dialog_content = "朝廷は時季ごとに妖魔を鎮める儀式を行い、\n諸侯国もそれぞれ対策を講じておる。",
  ui_story_5070_50700702_31_dialog_content = "妖魔は山の奥深くに潜み、生存が危うくなった時にのみ姿を現し、\n独り山を行く者を襲うのだ。",
  ui_story_5070_50700702_32_dialog_content = "シュウ殿はご存じないやもしれぬが、\nここ半年ほど、各地で妖魔が騒ぎ出しておるのじゃ。",
  ui_story_5070_50700702_33_dialog_content = "民が襲われることもしばしばじゃ。\nひいては城内にもぐりこみ、暴挙を働く事件も多発しておってのう。",
  ui_story_5070_50700702_34_dialog_content = "各国のこれまでの対策では手に余り、\n状況は芳しくないのじゃ。",
  ui_story_5070_50700702_35_dialog_content = "今や民の心は不安で乱れておる。\n果たして祟霊の仕業か、他に何か異変が起こっておるのか…",
  ui_story_5070_50700702_36_dialog_content = "殿下は祟霊を疎んでおられるのか？",
  ui_story_5070_50700702_37_dialog_content = "いや、そうではないが、気がかりなのじゃ…",
  ui_story_5070_50700702_38_dialog_content = "ちょっと待って。祟霊って何？",
  ui_story_5070_50700702_39_dialog_content = "アストラ大陸の亜人族の類と申すべきか。",
  ui_story_5070_50700702_40_dialog_content = "両者の違いは、亜人族は生まれながらにして\n動物の特徴を持つ光霊だが――",
  ui_story_5070_50700702_41_dialog_content = "祟霊は修行で術を身に付け、\n人の姿に化けることもできる人ならざる者をいう。",
  ui_story_5070_50700702_42_dialog_content = "人に疎まれる者もおるが、その能力や象徴する意によって\n人に特に好まれる祟霊もおる。",
  ui_story_5070_50700702_43_dialog_content = "穏やかな性格の魚の祟霊などは、\n船に関わる者が争って招き入れようとするほどだ。",
  ui_story_5070_50700702_44_dialog_content = "…たびたび海で危うき目に遭い、\n魚とは相性の良くないそれがしには理解しがたいがな。",
  ui_story_5070_50700702_45_dialog_content = "大きな魚は往々にして危険なものだ。\n出くわさねばよいのだが。",
  ui_story_5070_50700702_46_dialog_content = "なるほど、分かりました。",
  ui_story_5070_50700702_47_dialog_content = "アストラでも、幸運をもたらすとされる動物もいれば、\n災いをもたらすとされる動物がいるのと同じですね。",
  ui_story_5070_50700702_48_dialog_content = "いかにも。しかし、祟霊がもたらす加護は\n決して験かつぎではないぞ。",
  ui_story_5070_50700702_49_dialog_content = "かつて修行によって人の姿となり、\n自ら進んで、その地の平和を守った祟霊がいた。",
  ui_story_5070_50700702_50_dialog_content = "朝廷もその祟霊を認めて、官位を授け、\n人々がそれを祭り、廟を建てることを許したほどだ。",
  ui_story_5070_50700702_51_dialog_content = "すごいですね。そういう祟霊に会える機会があればいいんですけど。",
  ui_story_5070_50700702_52_dialog_content = "それにしても、シュウさんはよくご存じですね。",
  ui_story_5070_50700702_53_dialog_content = "妖魔退治にしろ、祟霊にしろ…",
  ui_story_5070_50700702_54_dialog_content = "その手の経験や知識で、シュウ殿に勝てる者は\nこの船上にはおらんじゃろうな。",
  ui_story_5070_50700702_55_dialog_content = "PlayerName、他にも知りたいことがあれば、\nシュウ殿に尋ねるがよい。",
  ui_story_5070_50700702_56_dialog_content = "海の妖魔どもが大人しく、\nわらわたちに時間をくれればのことじゃがのう。",
  ui_story_5070_50700702_57_dialog_content = "（案の定、暗鬼が大人しくしてくれるはずもなく、\n僕たちはさらに何回かの戦闘を経て、ようやくアストラ近海を抜けた）",
  ui_story_5070_50700702_58_dialog_content = "（その時、僕はまだ気づいていなかった）",
  ui_story_5070_50700702_59_dialog_content = "（大海原の脅威は暗鬼だけじゃないということに）",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>ゴオォォン――！</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>ザアアア――</color>",
  ui_story_5070_50700801_3_dialog_content = "PlayerName！PlayerName！起きて！",
  ui_story_5070_50700801_4_dialog_content = "んん…？センキョク？",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5070_50700801_6_dialog_content = "わっ…何が起こったの！？",
  ui_story_5070_50700801_7_dialog_content = "火が広がるぞ！水を持ってこい！",
  ui_story_5070_50700801_8_dialog_content = "おい！まだ避難が終わってない！\n押すな！船室内にかたまるな！",
  ui_story_5070_50700801_9_dialog_content = "騒ぐな！燃料庫を守れ！\nここが燃えたら終わりだ！",
  ui_story_5070_50700801_10_dialog_content = "すごく騒がしいけど…いったい何が起こってるの！？",
  ui_story_5070_50700801_11_dialog_content = "ちょっと前に遠洋に入ったんだけど、\n天候が今までに増して不安定で――",
  ui_story_5070_50700801_12_dialog_content = "しかも運悪く、いきなり大凶を引いたのよ。",
  ui_story_5070_50700801_13_dialog_content = "――雷雨よ。",
  ui_story_5070_50700801_14_dialog_content = "普通の嵐なら、私たちも十分対処できたんだけど、\nさっき雷が光ったあと、船で爆発が起こったわ。",
  ui_story_5070_50700801_15_dialog_content = "今は外で皆が消火と避難にあたってるわ。",
  ui_story_5070_50700801_16_dialog_content = "雷？爆発？",
  ui_story_5070_50700801_17_dialog_content = "でも…出発前に避雷装置と防火装置をチェックしたよね？\nどうしてこんなことに？",
  ui_story_5070_50700801_18_dialog_content = "装置で防止できるのは、雷で自然発火した火災よ。",
  ui_story_5070_50700801_19_dialog_content = "でも、今回の騒ぎはおそらくそれだけが原因じゃないわ。",
  ui_story_5070_50700801_20_dialog_content = "えっ？",
  ui_story_5070_50700801_21_dialog_content = "とにかく…今はそんなこと話してる場合じゃないの。\n私もまだ具体的なことを把握してるわけじゃないわ。",
  ui_story_5070_50700801_22_dialog_content = "何か力になれることはある？",
  ui_story_5070_50700801_23_dialog_content = "はぁ…本当は安全な所へ避難してもらおうと思ってたんだけど、\n今は人手が多ければ多いほど助かるわ。",
  ui_story_5070_50700801_24_dialog_content = "遠慮なく力を貸してもらうわ。",
  ui_story_5070_50700801_25_dialog_content = "付いてきて。",
  ui_story_5070_50700801_26_dialog_content = "どうして火が収まらないんだ！\nいったい何やってる！？",
  ui_story_5070_50700801_27_dialog_content = "だったら、お前がやれ！\n火が外に広がらないようにするだけで精一杯だ！",
  ui_story_5070_50700801_28_dialog_content = "クソッ、なんだって下から火が出たんだ！？\n船倉は全部木造なんだぞ、防げるはずがない！",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>ボン！</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>すぐ近くで轟音がしたかと思うと、船倉の扉が吹き飛び、\n炎をまとったまま襲い掛かってきた！</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>シュッ――</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>燃え盛る板が船職人の一歩手前の空中で砕け散った</color>",
  ui_story_5070_50700801_33_dialog_content = "自然の脅威に情けはない。\n災いを前にした時こそ、まずは己を律するのだ。",
  ui_story_5070_50700801_34_dialog_content = "おじけつくのは当然だ。\nしかし、足並みを乱してはならん。",
  ui_story_5070_50700801_35_dialog_content = "シュ…シュウ様！ありがとうございます！",
  ui_story_5070_50700801_36_dialog_content = "申し訳ねえんですが、俺一人じゃどうにもなりやせん。\nシュウ様のお力を貸してくだせえ。",
  ui_story_5070_50700801_37_dialog_content = "今、俺たちゃ何をすればいいんです？",
  ui_story_5070_50700801_38_dialog_content = "船上で聞くべきは、それがしの言葉ではなく、\n船長殿の指示であろう。",
  ui_story_5070_50700801_39_dialog_content = "シュウ様、ありがとうございます。",
  ui_story_5070_50700801_40_dialog_content = "船長、すまねえ…舵を取りながら、\nこっちも見なきゃならねえなんて…",
  ui_story_5070_50700801_41_dialog_content = "謝らないで。船上のあらゆる責任を負うのが船長よ。\nそれができなければ、船長は務まらないわ。",
  ui_story_5070_50700801_42_dialog_content = "船の状態は確認したわ。\n今すぐに動けば、火の勢いは抑えられる。",
  ui_story_5070_50700801_43_dialog_content = "了解です！",
  ui_story_5070_50700801_44_dialog_content = "風と波が強い…リンセイ、皆を連れてもっと遠くへ避難して。",
  ui_story_5070_50700801_45_dialog_content = "ほかの皆は火浣布を用意してちょうだい。\nまずはとび口で火元を遮断するのよ。",
  ui_story_5070_50700801_46_dialog_content = "応援ももうすぐ来るわ。",
  ui_story_5070_50700801_47_dialog_content = "ゴホゴホッ…空気がどんどん熱を帯びてきてる。\nもうすぐここにもいられなくなるよ。",
  ui_story_5070_50700801_48_dialog_content = "センキョク、運んでくるには運んできたけど、\nこれ、役に立つかな？",
  ui_story_5070_50700801_49_dialog_content = "船倉に使われてる木材はゆがみに弱いわ。\n水圧を考慮すると…",
  ui_story_5070_50700801_50_dialog_content = "センキョク？",
  ui_story_5070_50700801_51_dialog_content = "あ、PlayerName。早かったわね、もう運んできたの？",
  ui_story_5070_50700801_52_dialog_content = "いや、かなり時間がかかったんだ。\n君は集中してたから、気づかなかっただけだよ。",
  ui_story_5070_50700801_53_dialog_content = "使えそうなものを探してはみたけど…",
  ui_story_5070_50700801_54_dialog_content = "この辺りには空箱と捨てられた部品しかなかった。",
  ui_story_5070_50700801_55_dialog_content = "これで、本当に消火装置を造れるの？",
  ui_story_5070_50700801_56_dialog_content = "仕方ないわ。貨物室につながる通路は火が上がって通れないし、\nこの場にある材料で造るしかない。",
  ui_story_5070_50700801_57_dialog_content = "有能な機巧師なら、既定の設計や材料に頼らず、\nカラクリを造れるしね。",
  ui_story_5070_50700801_58_dialog_content = "木材じゃ硬度が足りないなら、塗料で補強し、釘がないなら、ほぞでつなげればいい。\n全体の強度を上げるなら、構造を変えればいいのよ。",
  ui_story_5070_50700801_59_dialog_content = "あらゆる知識や経験を柔軟に組み合わせて応用すれば、\n必要なものを造り出せるわ。",
  ui_story_5070_50700801_60_dialog_content = "変幻自在、それこそ機巧術なの。",
  ui_story_5070_50700801_61_dialog_content = "できたわ！上に行って、手伝いましょ！",
  ui_story_5070_50700801_62_dialog_content = "船長！上の火はなんとか収まったが、\n中の火がどうにもこうにも…",
  ui_story_5070_50700801_63_dialog_content = "大丈夫よ。",
  ui_story_5070_50700801_64_dialog_content = "お待たせ――",
  ui_story_5070_50700801_65_dialog_content = "ありあわせで造ったから、時間がかかっちゃったけど、\n効果は保証するわ！",
  ui_story_5070_50700801_66_dialog_content = "センキョク様、そ、それは何です？",
  ui_story_5070_50700801_67_dialog_content = "PlayerName、起動して。",
  ui_story_5070_50700801_68_dialog_content = "うん！",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>ガチャン…ガチャン…</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>もとはまちまちだった木材や金属が、\n自ら回転し、互いに合わさり、かみ合う</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>一方は船べりから海面へと延び、もう一方は船上にしかと立ち、\nまるでカラクリの龍が海から姿を現し、天を見上げているようだ</color>",
  ui_story_5070_50700801_72_dialog_content = "空箱の木材と使わなくなった部品で造ったけど、\n消火には十分ね。",
  ui_story_5070_50700801_73_dialog_content = "カラクリ水龍って名前にしましょ。",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>龍の口から勢いよく水が噴き出し、船倉内に白い煙が立ち込めた。\n猛威をふるっていた炎が消えてゆく</color>",
  ui_story_5070_50700801_75_dialog_content = "ぼうっとしていないで、動きなさい。",
  ui_story_5070_50700801_76_dialog_content = "センキョク、ここはお願いするわ。",
  ui_story_5070_50700801_77_dialog_content = "任せてちょうだい！",
  ui_story_5070_50700801_78_dialog_content = "PlayerNameもいるし…あら？PlayerName？",
  ui_story_5070_50700801_79_dialog_content = "何か、ヘンな感じがする。",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>消えたはずの炎が再び燃え上った</color>",
  ui_story_5070_50700801_82_dialog_content = "大変だ…このままじゃキリがない。",
  ui_story_5070_50700801_83_dialog_content = "感知能力で爆発の起こってる場所を確認してみる。\n何か解決策が見つかるかもしれない。",
  ui_story_5070_50700801_84_dialog_content = "強制感知！",
  ui_story_5070_50700801_85_dialog_content = "（ここじゃない…もっと下だ）",
  ui_story_5070_50700801_86_dialog_content = "（爆発が起こってるのは…貨物室？\n貨物室に何があるんだろう…）",
  ui_story_5070_50700801_87_dialog_content = "危ない！",
  ui_story_5070_50700801_88_dialog_content = "<size=45>グアア――！</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>カラクリ獣が足元の甲板を破って飛び出すと、\nその下は一面の火の海となっていた</color>",
  ui_story_5070_50700801_90_dialog_content = "PlayerName！",
  ui_story_5070_50700801_91_dialog_content = "（落ちる――！！）",
  ui_story_5070_50700801_92_dialog_content = "熾焔断灰！",
  ui_story_5070_50700801_93_dialog_content = "！",
  ui_story_5070_50700801_94_dialog_content = "イテテ…背中を打ったみたいだ。でも…",
  ui_story_5070_50700801_95_dialog_content = "火の中に落ちたはずなのに、どうして少しも熱くないんだろう？",
  ui_story_5070_50700801_96_dialog_content = "ケガはないか？",
  ui_story_5070_50700801_97_dialog_content = "シュウさん！？どうして一緒に？危険じゃないですか！\nケガはありませんか…？",
  ui_story_5070_50700801_98_dialog_content = "璇璣卿が車椅子を改造してくれてな。\nこれしきの衝撃、大事ない。",
  ui_story_5070_50700801_99_dialog_content = "いや、そういうことでは…",
  ui_story_5070_50700801_100_dialog_content = "それに、それがしは火焔術の心得がある。\nかように船上の野火を覆い――",
  ui_story_5070_50700801_101_dialog_content = "貴公を傷つけぬよう、抑え込むことなどたやすい。",
  ui_story_5070_50700801_102_dialog_content = "すごいですね！ということは、火の中を自由に動けるんですか？",
  ui_story_5070_50700801_103_dialog_content = "貨物室はすぐ近くですよね！？シュウさんの力があれば、\nこのまま火元を突き止められるかもしれませんよ！",
  ui_story_5070_50700801_104_dialog_content = "待たれよ。",
  ui_story_5070_50700801_105_dialog_content = "貴公は確かに特殊な力を持っているが、体は強くないとお見受けする。\nまずは安全な所へ戻るのが上策であろう。",
  ui_story_5070_50700801_106_dialog_content = "思いがけず、絶好の機会が巡ってきたのに、\nあきらめることなんてできません。",
  ui_story_5070_50700801_107_dialog_content = "だが、それは貴公の務めではなかろう。",
  ui_story_5070_50700801_108_dialog_content = "貴公は異国の使節であられる。その責は重く貴い。\n自身の安寧を第一としても誰もとがめまい。",
  ui_story_5070_50700801_109_dialog_content = "危険を冒すことはない。",
  ui_story_5070_50700801_110_dialog_content = "シュウさんが僕を心配して、そう言ってくれるのには感謝しています。\nでも、まだ起きてもいないことを心配してたら…",
  ui_story_5070_50700801_111_dialog_content = "何も成し遂げられないんじゃないですか？",
  ui_story_5070_50700801_112_dialog_content = "それに、さっき僕と一緒に飛び降りてきたシュウさんがそんなこと言っても、\n説得力に欠けますよ？",
  ui_story_5070_50700801_113_dialog_content = "シュウさんには僕を助ける義務も責任もないんですから。\nそうでしょう？",
  ui_story_5070_50700801_114_dialog_content = "…",
  ui_story_5070_50700801_115_dialog_content = "はっはっは、もっともだ。",
  ui_story_5070_50700801_116_dialog_content = "まさか、それがしが諫言を受ける側に回る日がくるとは思わなんだ。",
  ui_story_5070_50700801_117_dialog_content = "貴公はまことに殊勝者であるな。",
  ui_story_5070_50700801_118_dialog_content = "ならば、行くとしよう。",
  ui_story_5070_50700801_119_dialog_content = "もう一度火元を確認してみます。",
  ui_story_5070_50700801_120_dialog_content = "強制感知！",
  ui_story_5070_50700801_121_dialog_content = "あれ…待ってください。\nなんだか奇妙な感じがします。それに…",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>あぶない！</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>突如起こった爆発で、辺り一面が火の海となった</color>",
  ui_story_5070_50700802_1_dialog_content = "ゴホッ！ゴホゴホッ…すごい煙だ。",
  ui_story_5070_50700802_2_dialog_content = "煙がひどくて…なかなか集中できない。\nでも、さっきは確かに誰かがいたような…",
  ui_story_5070_50700802_3_dialog_content = "…",
  ui_story_5070_50700802_4_dialog_content = "ゴホゴホッ…君はいったい…",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>煙の中に奇妙な白い一筋の光が走った</color>",
  ui_story_5070_50700802_6_dialog_content = "PlayerName！",
  ui_story_5070_50700802_7_dialog_content = "シュ、シュウさん…ゴホッ…",
  ui_story_5070_50700802_8_dialog_content = "手をこちらへ！",
  ui_story_5070_50700802_9_dialog_content = "待ってください。あっちに…",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>前方に突如炎が燃え上がった</color>",
  ui_story_5070_50700802_11_dialog_content = "まずはここから出ねば。",
  ui_story_5070_50700802_12_dialog_content = "シュウ様！PlayerNameがどうかしたんですか？無事ですか？",
  ui_story_5070_50700802_13_dialog_content = "はい！どいてどいて！みんな、道を開けて！",
  ui_story_5070_50700802_14_dialog_content = "名医が通るよ！",
  ui_story_5070_50700901_1_dialog_content = "う～ん…",
  ui_story_5070_50700901_2_dialog_content = "ニャ～。",
  ui_story_5070_50700901_3_dialog_content = "…どうしてネコが？",
  ui_story_5070_50700901_4_dialog_content = "あ、あれ？君っていつもリンセイの側にいるネコちゃんだよね…\n確か…チビシッポだったっけ？",
  ui_story_5070_50700901_5_dialog_content = "ニャ～！",
  ui_story_5070_50700901_6_dialog_content = "どうしてここに？",
  ui_story_5070_50700901_7_dialog_content = "そうだ。昨日の火事はどうなったんだろう…\n皆無事だよね！？",
  ui_story_5070_50700901_8_dialog_content = "ニャニャ！",
  ui_story_5070_50700901_9_dialog_content = "わあ…チビシッポ、道をふさがないで。\n踏んじゃったらどうするの？",
  ui_story_5070_50700901_10_dialog_content = "ちょっと！なんで起きてるの！？\nおちおち薬も取りに行けないじゃないか。",
  ui_story_5070_50700901_11_dialog_content = "さあ、寝た寝た。",
  ui_story_5070_50700901_12_dialog_content = "ニャ～。",
  ui_story_5070_50700901_13_dialog_content = "チビシッポ、よくやった！",
  ui_story_5070_50700901_14_dialog_content = "シュウさんと同じで、PlayerNameも\n手のかかる患者だろうと思ってたんだよね。",
  ui_story_5070_50700901_15_dialog_content = "…ということは、君がチビシッポに通せんぼさせたの！？",
  ui_story_5070_50700901_16_dialog_content = "当然でしょ。たかが煙だと思って、\n甘く見ちゃだめなんだから。",
  ui_story_5070_50700901_17_dialog_content = "煙が肺深くまで入り込むと、大変なことになりかねないんだよ。",
  ui_story_5070_50700901_18_dialog_content = "さあ、横になってて。",
  ui_story_5070_50700901_19_dialog_content = "バイモ1銭5分、キカラスウリ1銭、花粉、ブクリョウ、橘皮、キキョウを各8分。",
  ui_story_5070_50700901_20_dialog_content = "それは？",
  ui_story_5070_50700901_21_dialog_content = "肺を潤して、熱をとる薬だよ。",
  ui_story_5070_50700901_22_dialog_content = "しばらくの間お水をたくさん飲んで、ゆっくり休むんだよ。\n新鮮な空気をたくさん吸って、ご飯はあったかい、さっぱりしたものにするんだ。",
  ui_story_5070_50700901_23_dialog_content = "せきや痰が出たり、胸が苦しくなったら、\nすぐにボクを呼ぶんだよ。分かった？",
  ui_story_5070_50700901_24_dialog_content = "？？なんで、そんな顔でボクを見てるの？",
  ui_story_5070_50700901_25_dialog_content = "病気の時は、リンセイって本当に頼りになるね。",
  ui_story_5070_50700901_26_dialog_content = "まるで…ええと、龍州ではなんて言うんだっけ！？\nあ、そうだ！神医みたいだね！",
  ui_story_5070_50700901_27_dialog_content = "ほんとに！？あ…コホン。当然でしょ。",
  ui_story_5070_50700901_28_dialog_content = "まあ、ともかく、熱いうちに薬を飲んでよ。",
  ui_story_5070_50700901_29_dialog_content = "うーん…なんとも言えない味だね。",
  ui_story_5070_50700901_30_dialog_content = "卜子曰く「良薬は口に苦し」。\n元気になるには、それなりの代償が必要なんだ。",
  ui_story_5070_50700901_31_dialog_content = "…そんなに…まずいかな？",
  ui_story_5070_50700901_32_dialog_content = "まずいってわけじゃないんだ。ただ生まれて初めて、\nこんな複雑な味のものを飲んだから…",
  ui_story_5070_50700901_33_dialog_content = "ちょっと慣れないだけ",
  ui_story_5070_50700901_34_dialog_content = "ふーん。これだから若者は困るんだよね。",
  ui_story_5070_50700901_35_dialog_content = "はい、果物の蜜漬けをあげる。\n薬を飲み終わったら食べるといいよ。",
  ui_story_5070_50700901_36_dialog_content = "でも、1つだけだからね。\n1包みだけしか持ってこなかったんだから。",
  ui_story_5070_50700901_37_dialog_content = "ありがとう、リンセイ。優しいね。",
  ui_story_5070_50700901_38_dialog_content = "仕方ないでしょ。神医は患者に優しくするもんなんだから！",
  ui_story_5070_50700901_39_dialog_content = "じゃ、ゆっくり休んで。\nほかにも診なきゃいけない患者がいるんだ。",
  ui_story_5070_50700901_40_dialog_content = "他にもケガ人がいるの？",
  ui_story_5070_50700901_41_dialog_content = "起きちゃだめだって。昨日の火事ではキミが一番重傷だったんだ。\nほかの人の心配してるひまないでしょ。",
  ui_story_5070_50700901_42_dialog_content = "大丈夫。みんな大したことないから。",
  ui_story_5070_50700901_43_dialog_content = "ただ念のために、体内の熱を鎮めて\n毒気をとる薬を飲んでもらってるだけだよ。",
  ui_story_5070_50700901_44_dialog_content = "あ、そうだ…",
  ui_story_5070_50700901_45_dialog_content = "キミが寝てる間、いろんな人がお見舞いに来たんだよ。\n目も覚めたことだし、呼んでくるね。",
  ui_story_5070_50700901_46_dialog_content = "あ、それは大丈夫だよ。皆が無事だって分かればいいんだ。\nわざわざ呼ばなくても…",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700901_48_dialog_content = "そんなに遠慮しないでよ。",
  ui_story_5070_50700901_49_dialog_content = "あ――！",
  ui_story_5070_50700901_50_dialog_content = "タンドウ？",
  ui_story_5070_50700901_51_dialog_content = "センキョク様、殿下を押しのけないでくださいませ。",
  ui_story_5070_50700901_52_dialog_content = "あら、キュウは過保護すぎるんじゃない？そうキリキリしないで。\n殿下は高貴な方ではあっても、磁器のお人形じゃないのよ。",
  ui_story_5070_50700901_53_dialog_content = "センキョク？キュウ？皆、どうしたの？",
  ui_story_5070_50700901_54_dialog_content = "もちろん、昨日一番の功労者に会いにきたのよ。",
  ui_story_5070_50700901_55_dialog_content = "骨が折れたりしてなくて幸いだったわ。\nもしそんなことになってたら、謝っても謝りきれなかったわ。",
  ui_story_5070_50700901_56_dialog_content = "センキョクが謝る理由なんてないよ。\nあの時まさか床が抜けるとは誰も予想できなかったんだから。",
  ui_story_5070_50700901_57_dialog_content = "それに皆無事だったってことは、\n君のカラクリのおかげで、火を消せたってことでしょ…",
  ui_story_5070_50700901_58_dialog_content = "それだけ話せるなら、大丈夫そうね。",
  ui_story_5070_50700901_59_dialog_content = "タンドウ殿下、ご自分の目で、\nPlayerNameの元気な姿を確めたご気分は？",
  ui_story_5070_50700901_60_dialog_content = "扉の向こうでこっそり様子をうかがうより、\nずっといいでしょう？",
  ui_story_5070_50700901_61_dialog_content = "…璇璣卿は、何か見間違えたのではあるまいか？",
  ui_story_5070_50700901_62_dialog_content = "PlayerNameは大切な使節じゃぞ。\nその健康を気に掛けるのは、わらわの務めじゃ。",
  ui_story_5070_50700901_63_dialog_content = "こ、こっそりうかがうなど…",
  ui_story_5070_50700901_64_dialog_content = "はい、さようでございますね。\nきっと昨日煙で目をやられて、よく見えなかったんでしょう。",
  ui_story_5070_50700901_65_dialog_content = "では、タンドウ様は引き続きPlayerNameの心配をして、\nお務めをしっかり果たしてくださいませ～。",
  ui_story_5070_50700901_66_dialog_content = "な、なにを申すか…",
  ui_story_5070_50700901_67_dialog_content = "タンドウ、僕はもう元気だから、心配いらないよ。",
  ui_story_5070_50700901_68_dialog_content = "特に困ってることもないし…あ、そういえば…\n薬の味がなんとも言い難いけど…",
  ui_story_5070_50700901_69_dialog_content = "薬じゃと？ならば、わらわが力になれるぞ。",
  ui_story_5070_50700901_70_dialog_content = "身体が回復したのちは、薬よりも食療がよいと聞く。",
  ui_story_5070_50700901_71_dialog_content = "ちょうどリンセイもおることじゃ。\n食の進む薬膳でも用意しようかのう。どうじゃ？",
  ui_story_5070_50700901_72_dialog_content = "おいしいものを作るの！？もちろん、問題ないよ！",
  ui_story_5070_50700901_73_dialog_content = "薬膳ならボクもたくさん作り方を知ってるよ。\n出航前に食材もたっぷり買っておいたんだ。",
  ui_story_5070_50700901_74_dialog_content = "レンコンは血の巡りが良くなるし、トウガンは潤いを補うから、美容にいいんだ。\nブクシン粥は心を落ち着けてくれて…",
  ui_story_5070_50700901_75_dialog_content = "とにかく、いろんなものが作れるよ！",
  ui_story_5070_50700901_76_dialog_content = "…",
  ui_story_5070_50700901_77_dialog_content = "センキョク、食べないの？…センキョク？",
  ui_story_5070_50700901_78_dialog_content = "え？何か手助けでも必要？",
  ui_story_5070_50700901_79_dialog_content = "いや、そうじゃないんだ。\nずっと黙ったまま考え事してるみたいだから。",
  ui_story_5070_50700901_80_dialog_content = "あら、そんなに分かりやすかった？",
  ui_story_5070_50700901_81_dialog_content = "どうやら、修行がまだ足りないみたいね。\n今度、表情をつくるお面でも作ろうかしら？",
  ui_story_5070_50700901_82_dialog_content = "実は、昨日の事を考えてたの。",
  ui_story_5070_50700901_83_dialog_content = "シュウ様に煙の中から助け出してもらった時…",
  ui_story_5070_50700901_84_dialog_content = "あなた…ずっと「炎」だ、「人影」だと言ってたでしょ。",
  ui_story_5070_50700901_85_dialog_content = "いったい何を見たの？",
  ui_story_5070_50700901_86_dialog_content = "正確に言うと、見たんじゃなくて、感知したんだ。",
  ui_story_5070_50700901_87_dialog_content = "貨物室の中に何か奇妙な気配を感じたんだ。\n火に似てるのに、火がもってるはずの熱は感じられなくて…",
  ui_story_5070_50700901_88_dialog_content = "それなのに周りの炎を全部かき集めたよりもずっと、\n密度の高い、濃い感じがしたんだ。",
  ui_story_5070_50700901_89_dialog_content = "まるで…太陽を圧縮したみたいだった。",
  ui_story_5070_50700901_90_dialog_content = "…何か、ヘンな話だよね。",
  ui_story_5070_50700901_91_dialog_content = "とにかく、僕が思うに、雷はただのきっかけでしかなくて、\n僕が感知した奇妙なものこそ真の火元なんじゃないかな！？",
  ui_story_5070_50700901_92_dialog_content = "人影については、あまりよく見えなくて…\nでも、あの時貨物室の近くにずっと立ってたから…",
  ui_story_5070_50700901_93_dialog_content = "おかしいなと思ったんだ。",
  ui_story_5070_50700901_94_dialog_content = "そう、分かったわ。",
  ui_story_5070_50700901_95_dialog_content = "ただ、今後はもう無茶しないでよ。",
  ui_story_5070_50700901_96_dialog_content = "そんな気軽に、おかしな気配を感知するもんじゃないわ…",
  ui_story_5070_50700901_97_dialog_content = "もしすごく危険なものだったら、\n助けてあげたくたって、助けてあげられないんだから…",
  ui_story_5070_50700901_98_dialog_content = "ごめん…これからは気を付けるよ。",
  ui_story_5070_50700901_99_dialog_content = "じゃあ、私はこれで。",
  ui_story_5070_50700901_100_dialog_content = "待って。",
  ui_story_5070_50700901_101_dialog_content = "僕が寝てる間、また良くないことでもあったの？",
  ui_story_5070_50700901_102_dialog_content = "…",
  ui_story_5070_50700901_103_dialog_content = "ああ…表情をつくるお面、早めに造った方がよさそうね。",
  ui_story_5070_50700901_104_dialog_content = "無事に龍州の工房に戻れたらの話だけど。",
  ui_story_5070_50700901_105_dialog_content = "まさか…航海に問題が？",
  ui_story_5070_50700901_106_dialog_content = "航海についてはね、こんな言葉があるの――",
  ui_story_5070_50700901_X106_dialog_content = "「船頭海を識るに、夜は星を観、昼は日を観る。\n陰り暗きにあっては磁針を観て、針乱るれば、速速離るるべし」",
  ui_story_5070_50700901_107_dialog_content = "星を観、日を観るっていうのは、前に話してくれた、\n星座を観測して航路を決めることを言ってるの？",
  ui_story_5070_50700901_108_dialog_content = "そうよ。もし星や月が見えなければ、\n羅針盤のような機械で方向を見極めなきゃいけないの。",
  ui_story_5070_50700901_109_dialog_content = "でも、もし機械まで狂ってしまったら、\n方角を判断する方法はなくなる。",
  ui_story_5070_50700901_110_dialog_content = "だから、早々にそこを離れなければ、\n海上で迷ってしまうっていう意味なのよ。",
  ui_story_5070_50700901_111_dialog_content = "昨日の騒ぎの後、嵐の中で方角を見極めようと、\nあらゆる手を尽くしたんだけど…",
  ui_story_5070_50700901_112_dialog_content = "…全部、ダメだったの？",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>センキョクがかすかにうなずいた</color>",
  ui_story_5070_50700901_114_dialog_content = "今もまだ状況は変わってないわ。",
  ui_story_5070_50700901_115_dialog_content = "蜃風号が正しい航路を進んでるなら、\nこんなこと、起こるはずがないのよ。",
  ui_story_5070_50700901_116_dialog_content = "今いるのは遠洋よ。ここまで来ると海図も完全じゃないわ…\n天候が良くなったとしても、太陽から方角を判断することはできない。",
  ui_story_5070_50700901_117_dialog_content = "つまり、今、蜃風号は…",
  ui_story_5070_50700901_118_dialog_content = "航路を外れてしまったのよ。",
  ui_story_5070_50700902_1_dialog_content = "方向を見失ったうえに、暗鬼の襲撃にも対応しなきゃならない…\n本当に災い続きの多難な航海になったわね。",
  ui_story_5070_50700902_2_dialog_content = "早急に位置を確認しないといけないわ。",
  ui_story_5070_50700902_3_dialog_content = "そうだったのか…でも、それとカラクリ水龍を運び出すことと、\n何の関係があるの？",
  ui_story_5070_50700902_4_dialog_content = "カラクリはある機能を果たすことを目的に造り出されるけど、\nその使い道は一つとは限らないのよ。",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>轟音と共に、海水が銅製の管を通り、\n前もって準備してあった桶の中に注がれた</color>",
  ui_story_5070_50700902_6_dialog_content = "見て。海水のほかにも、\nこんなにたくさんエビさんやカニさんが獲れたわ。",
  ui_story_5070_50700902_7_dialog_content = "海はつながっているとはいえ、\n海域が違えば、そこに棲む生物も違う。",
  ui_story_5070_50700902_8_dialog_content = "特定の海域を代表するような生き物がいれば…",
  ui_story_5070_50700902_9_dialog_content = "海図の生物分布の記録をもとに、\n大体の位置が分かるはずよ。",
  ui_story_5070_50700902_10_dialog_content = "そんな考え方があったんだね！",
  ui_story_5070_50700902_11_dialog_content = "で、何か特別な生き物は捕まった？",
  ui_story_5070_50700902_12_dialog_content = "残念だけど、どれもどこにでもいる魚やエビだわ。\n後でタンドウ様に薬膳にしてもらいましょ。",
  ui_story_5070_50700902_13_dialog_content = "それと、先に言っておくけど、これには危険も伴うのよ。",
  ui_story_5070_50700902_14_dialog_content = "乗組員の皆も毎日魚を獲って食べさせてくれてるよ！？\n何が危険なの？",
  ui_story_5070_50700902_15_dialog_content = "さっきの話には、まだ続きがあるの。",
  ui_story_5070_50700902_16_dialog_content = "カラクリは本来の機能以外のことも出来るけど、\n所詮は真の目的とは違う使い方なの。",
  ui_story_5070_50700902_17_dialog_content = "だから、予想外の結果になることも…",
  ui_story_5070_50700902_18_dialog_content = "火吹き蟹もそう。職人の溶接を手伝うなら、お手のもの。",
  ui_story_5070_50700902_19_dialog_content = "でも、肉を焼こうとすれば、火力をうまく調節できない――",
  ui_story_5070_50700902_20_dialog_content = "まる焦げになった肉がどんな味だか知ってる？",
  ui_story_5070_50700902_21_dialog_content = "あまり知りたくないなぁ。",
  ui_story_5070_50700902_22_dialog_content = "それに、どんな状況になれば、\n火吹き蟹で肉を焼こうと思うの？",
  ui_story_5070_50700902_23_dialog_content = "揚水装置として造ったカラクリで魚を獲ってる、\n今みたいな状況よ。",
  ui_story_5070_50700902_24_dialog_content = "臨機応変が大事な時ってあるでしょ。",
  ui_story_5070_50700902_25_dialog_content = "龍州の人たちの感覚は僕には分からないけど――",
  ui_story_5070_50700902_26_dialog_content = "火吹き蟹で肉を焼くのは、臨機応変には入らないんじゃないかな？",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_28_dialog_content = "何かにぶつかった！？",
  ui_story_5070_50700902_29_dialog_content = "カラクリ水龍を止めて。",
  ui_story_5070_50700902_30_dialog_content = "ものすごい勢いで水を引き揚げてたから、\n海の主でも引き寄せちゃったみたい。",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_32_dialog_content = "ふ、船が傾いてるぞ！\nみんな、近くのものにつかまれ！",
  ui_story_5070_50700902_33_dialog_content = "な、何とか…つかまりはしましたが…",
  ui_story_5070_50700902_34_dialog_content = "甲板で風にでも当たろうかと出てきただけなのに、\nまさか、こんなことに出くわすとはねぇ。",
  ui_story_5070_50700902_35_dialog_content = "幸い、手すりをつかんで持ちこたえましたが、\nやはり、あの卦象は…おおっと！",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_37_dialog_content = "傾きがどんどん大きくなってるわ。\nこのままじゃ何もできない！",
  ui_story_5070_50700902_38_dialog_content = "みんな、急いで浮いてる方へ移動して！\n重みをかけて、平衡を保つのよ！",
  ui_story_5070_50700902_39_dialog_content = "火吹き蟹に動力炉の勢いを上げさせるわ。\n船体が安定したら、即加速して、ここを離れるの！",
  ui_story_5070_50700902_40_dialog_content = "やった！水の中に見えてた影を振り切ったよ！",
  ui_story_5070_50700902_41_dialog_content = "火吹き蟹には何回も襲われたけど、\n今回ばかりは火吹き蟹に救われたね。",
  ui_story_5070_50700902_42_dialog_content = "言ったでしょ？カラクリに罪はない。善も悪もないの。",
  ui_story_5070_50700902_43_dialog_content = "人を救うか、傷つけるかはすべて、\nそれを使う者次第よ。",
  ui_story_5070_50700902_44_dialog_content = "「大きくて恐ろしいカニ」っていう印象も、\n改めなきゃいけないかな…",
  ui_story_5070_50700902_45_dialog_content = "蜃風号もこんな速度で進むのは初めてだよね。\nずっとこのまま進めるのかな？",
  ui_story_5070_50700902_46_dialog_content = "そうは問屋が卸さないわ。",
  ui_story_5070_50700902_47_dialog_content = "今、無理やり動力炉の出力を上げられているのは、\n火吹き蟹のお腹の中に蓄えてある火焔術のおかげなの。",
  ui_story_5070_50700902_48_dialog_content = "補給しなければ、すぐに使い果たしちゃうわ。\nその時は…",
  ui_story_5070_50700902_49_dialog_content = "センキョク様！動力炉の奴が言ってきたんですがね、\n火吹き蟹が動かなくなっちまったそうです！",
  ui_story_5070_50700902_50_dialog_content = "こうなっちゃうんだね？",
  ui_story_5070_50700902_51_dialog_content = "…思ってたよりも早かったわね。",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_53_dialog_content = "強制感知！",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5070_50700902_55_dialog_content = "うまくいった！？",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_57_dialog_content = "お願いだから止まって！\n僕たちは食べ物でも、遊び道具でもないよ！",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5070_50700902_59_dialog_content = "ダメだ。一時的に止まってもらうことはできても、\n距離を引き離せなければ、結局は追いつかれちゃう。",
  ui_story_5070_50700902_60_dialog_content = "それに、この生き物…水面に映ってる影よりも、\n実際はものすごく大きい…",
  ui_story_5070_50700902_61_dialog_content = "具体的には何倍くらい？",
  ui_story_5070_50700902_62_dialog_content = "え？",
  ui_story_5070_50700902_63_dialog_content = "水面に映る影の大きさは目測で分かる。",
  ui_story_5070_50700902_X63_dialog_content = "あとはPlayerNameの感知で、だいたい何倍か分かれば、\n実際の大きさを算出できるでしょ。",
  ui_story_5070_50700902_64_dialog_content = "それから、蜃風号の重量と衝撃の伝わる角度をもとに、\n相手の力の作用範囲を逆算すれば…",
  ui_story_5070_50700902_65_dialog_content = "水中の生き物が何か分かるわ！",
  ui_story_5070_50700902_66_dialog_content = "PlayerName、あと数分引き留めておける？\n船室に物を取りに行きたいの。引き離せるかもしれないわ。",
  ui_story_5070_50700902_67_dialog_content = "分かった。任せて。",
  ui_story_5070_50700902_68_dialog_content = "強制感知！",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_70_dialog_content = "強制感知！",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_72_dialog_content = "（ううっ…これで何回目だろう…遊んでるつもりなのかな？\nそれはそうと、センキョクはまだなの？）",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>パ――ン！</color>",
  ui_story_5070_50700902_74_dialog_content = "強制感知…！",
  ui_story_5070_50700902_75_dialog_content = "PlayerName、お待たせ！",
  ui_story_5070_50700902_76_dialog_content = "よかった――",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_5070_50700902_78_dialog_content = "（今までで一番強烈な衝撃が伝わってきて、\n僕はそのまま空中に放り出されてしまった）",
  ui_story_5070_50700902_79_dialog_content = "傘をつかんで！",
  ui_story_5070_50700902_80_dialog_content = "（ダメだ！今、集中力を分散したら、\nあの海獣を止められない…！）",
  ui_story_5070_50700902_81_dialog_content = "センキョク！手に持ってるものをこっちへ！",
  ui_story_5070_50700902_82_dialog_content = "！？",
  ui_story_5070_50700902_83_dialog_content = "あなたって人は、どこまで無茶なのよ…\n受け取って！",
  ui_story_5070_50700902_84_dialog_content = "（空中にいる僕の方が、遠くまで投げられる！）",
  ui_story_5070_50700902_85_dialog_content = "オモチャをあげるよ！もう追ってこないでね！",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>ポチャン</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>センキョクから受け取った石を海中に投げ入れた</color>",
  ui_story_5070_50700902_88_dialog_content = "（海獣が方向転換したのを感じた。\n傘を開いて、僕を受け止めようとするセンキョクの姿が見えたけど…）",
  ui_story_5070_50700902_89_dialog_content = "（間に合わない…でも、大丈夫。\nだって、下には…あの人がいてくれるから！）",
  ui_story_5070_50700902_90_dialog_content = "熾焔断灰！",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>真っ赤な炎が天を突くように燃え上った。\n動力炉はウォンウォンと音を立てて全開し始め、蜃風号は再び加速した</color>",
  ui_story_5070_50700902_92_dialog_content = "（そして僕は、静かで穏やかな火の中に落ちた）",
  ui_story_5070_50700902_93_dialog_content = "ふぅ…ようやく、これで完全に海獣を振り切れたね…",
  ui_story_5070_50700902_94_dialog_content = "PlayerName。",
  ui_story_5070_50700902_95_dialog_content = "貴公の苦難を恐れずに進む勇気には感服する。",
  ui_story_5070_50700902_96_dialog_content = "しかし、先刻の行いはあまりにも危険であった。\n少々無謀が過ぎるのではあるまいか？",
  ui_story_5070_50700902_97_dialog_content = "（うっ…ものすごく厳しい口調だ…）",
  ui_story_5070_50700902_98_dialog_content = "ごめんなさい…心配かけて。\nでも、僕も確信があったからこそ無茶したんです。",
  ui_story_5070_50700902_99_dialog_content = "シュウさんがいるのが見えたので。",
  ui_story_5070_50700902_100_dialog_content = "ありがとうございました。",
  ui_story_5070_50700902_101_dialog_content = "…礼などいらぬ。\n貴公が感謝すべきは璇璣卿であろうな。",
  ui_story_5070_50700902_102_dialog_content = "璇璣卿の車椅子がなければ、\nそれがしも揺れる船の上で自由に動き回ることはできんかった。",
  ui_story_5070_50700902_103_dialog_content = "PlayerName！",
  ui_story_5070_50700902_104_dialog_content = "運に恵まれてるあなたなら、きっと大丈夫だと思ってたわ。",
  ui_story_5070_50700902_105_dialog_content = "あはは、信頼してくれてありがとう。\nそれはそうと、石でどうやって海獣を引き離したの？",
  ui_story_5070_50700902_106_dialog_content = "あれはただの石じゃないわ、発光石よ。\n周りが暗ければ暗いほど、明るく光るの。",
  ui_story_5070_50700902_107_dialog_content = "さっきの海獣に関する記録は少なくて、\n深海に生息することくらいしか分かっていない。",
  ui_story_5070_50700902_108_dialog_content = "でも、暗い深海で暮らす生き物は、\nたいてい光る物に興味を持つから――",
  ui_story_5070_50700902_109_dialog_content = "発光石できっと海獣の注意を引けると思ったのよ。",
  ui_story_5070_50700902_110_dialog_content = "予想通りだったわ。",
  ui_story_5070_50700902_111_dialog_content = "皆様、ご無事ですか？",
  ui_story_5070_50700902_112_dialog_content = "ええ、無事よ。もう少しで海獣の動力源になるところだったけどね。",
  ui_story_5070_50700902_113_dialog_content = "航海って本当に大変なんだな…",
  ui_story_5070_50700902_114_dialog_content = "空には海獣みたいな生き物がいなくてよかった。\nでなかったら、僕もソラヴァンも危険だったよ。",
  ui_story_5070_50700902_115_dialog_content = "あはは。でも、この後はしばらく安全なはずよ。",
  ui_story_5070_50700902_116_dialog_content = "あんなに大きな海獣は、そうめったにいないわ。",
  ui_story_5070_50700902_117_dialog_content = "少なくとも、あの子の縄張りを抜けるまでは、\n同じような危険に遭うことはないと思うわ。",
  ui_story_5070_50700902_118_dialog_content = "つまり…この先はカラクリ水龍をいくら使っても\n大丈夫ということかしら？",
  ui_story_5070_50700902_119_dialog_content = "ええ。しかも最大出力でね！",
  ui_story_5070_50700902_120_dialog_content = "手の空いてる人は全員集まってちょうだい。\n今のうちに力を合わせて、出来るだけ多くの魚を獲るのよ。",
  ui_story_5070_50700902_121_dialog_content = "航海もここまで来ると、\n船上の食糧もそろそろ補給しなくてはならないわ。",
  ui_story_5070_50700902_122_dialog_content = "あ、はい…今行きやす！",
  ui_story_5070_50700902_123_dialog_content = "あっ！",
  ui_story_5070_50700902_124_dialog_content = "こりゃあ、申し訳ねえです。わざとぶつかったわけじゃ…",
  ui_story_5070_50700902_125_dialog_content = "ソンさん？大丈夫だよ、僕も注意してなかったのがいけないんだ。",
  ui_story_5070_50700902_126_dialog_content = "それより、何を持ってるの？いい匂いだね。",
  ui_story_5070_50700902_127_dialog_content = "あ、こ、これは…魚のエサです。\n船長に呼ばれて、魚を獲りに行くもんで。",
  ui_story_5070_50700902_128_dialog_content = "そうなんだ。こんないい匂いがするんだから、\nきっと大きな魚が釣れるだろうね。",
  ui_story_5070_50700902_129_dialog_content = "…あれ？ソンさん？",
  ui_story_5070_50700902_130_dialog_content = "船長！見て下せえ！獲れやしたよ！",
  ui_story_5070_50700902_131_dialog_content = "PlayerName？何してるの？",
  ui_story_5070_50700902_132_dialog_content = "今さっき…ソンさんは？",
  ui_story_5070_50700902_133_dialog_content = "…",
  ui_story_5070_50700902_134_dialog_content = "まあ、いいわ。",
  ui_story_5070_50700902_135_dialog_content = "<size=25>エサさえあれば、どんなにうまく隠れようと、\nいつか必ず尻尾を出すわ</size>",
  ui_story_5070_50700902_136_dialog_content = "何か言った？",
  ui_story_5070_50700902_137_dialog_content = "いいえ。ずいぶんにぎやかね。私たちも行きましょ。",
  ui_story_5070_50700902_138_dialog_content = "そうだね…あれ？どうして、こんなにたくさん木材が上がってるの？",
  ui_story_5070_50700902_139_dialog_content = "沈没船の残骸だ。",
  ui_story_5070_50700902_140_dialog_content = "だが、木材、塗料、腐蝕の具合がすべて異なる。\n明らかに同じ船のものではない。",
  ui_story_5070_50700902_141_dialog_content = "おそらく、この近くに多くの船が沈没しておるのだろう。",
  ui_story_5070_50700902_142_dialog_content = "船の墓場かもしれないわ。",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5070_50701001_2_dialog_content = "ユエ！？",
  ui_story_5070_50701001_3_dialog_content = "今…ユエが海に飛び込んだ！？",
  ui_story_5070_50701001_4_dialog_content = "心配にはおよばぬ。ユエは泳ぎが得意なのじゃ。",
  ui_story_5070_50701001_5_dialog_content = "わらわたち乗客は船長を信じ、\n待っておればよい。",
  ui_story_5070_50701001_6_dialog_content = "（海にはさまざまな危険が潜んでいる。\n暗礁、潮の渦、狂暴な海獣…）",
  ui_story_5070_50701001_7_dialog_content = "（でも、一つ共通していることがある。\nそれは各海域で無数の船を葬ってきたこと）",
  ui_story_5070_50701001_8_dialog_content = "（船は沈没後、海流に流され、堆積し、\n最後には一つ所に集まって、海底に船の墓場ができる）",
  ui_story_5070_50701001_9_dialog_content = "（ここね）",
  ui_story_5070_50701001_10_dialog_content = "（まさか、私の船が船の墓場へ来る日が来ようとは思わなかったわ）",
  ui_story_5070_50701001_11_dialog_content = "（バラバラになった骨組みの山は、\nサンゴや海藻に寄生され、浸食され、朽ち果てる）",
  ui_story_5070_50701001_12_dialog_content = "（まるで大海原が、船を見送るかのように）",
  ui_story_5070_50701001_13_dialog_content = "（…あの船は？）",
  ui_story_5070_50701001_14_dialog_content = "璇璣卿、PlayerName。\n待つ間、引き続き残骸を引き揚げてくれぬか？",
  ui_story_5070_50701001_15_dialog_content = "この残骸…見覚えがある。",
  ui_story_5070_50701001_16_dialog_content = "僕にはどれも同じ木材にしか見えませんよ！？",
  ui_story_5070_50701001_17_dialog_content = "物というのは、よくよく見ると、様々なことを語ってくれるものじゃ。",
  ui_story_5070_50701001_18_dialog_content = "シュウ殿の言われたように、わらわにも見えて来たぞ。",
  ui_story_5070_50701001_19_dialog_content = "この残骸には、船の名前が刻まれておる。",
  ui_story_5070_50701001_20_dialog_content = "この残骸には…ほぞ穴がある。",
  ui_story_5070_50701001_21_dialog_content = "ただ木材が欠けただけじゃないの？",
  ui_story_5070_50701001_22_dialog_content = "いや、これは竜骨をつなぐために彫られたほぞ穴じゃ。",
  ui_story_5070_50701001_23_dialog_content = "この中に銭や鏡などの縁起物を挟むとのう――",
  ui_story_5070_50701001_24_dialog_content = "邪を払いて行き先を照らし、\n航海の無事を守ると言われておる。",
  ui_story_5070_50701001_25_dialog_content = "にもかかわらず、残骸となってしまったか…\n悲しきことよのう。",
  ui_story_5070_50701001_26_dialog_content = "残骸がこんなにたくさん…\nこの辺りの海域は本当に危険なんだね…",
  ui_story_5070_50701001_27_dialog_content = "シュウさん、どうしたんですか…？\n何か分かりましたか？",
  ui_story_5070_50701001_28_dialog_content = "海賊の船だ。",
  ui_story_5070_50701001_29_dialog_content = "海賊！？",
  ui_story_5070_50701001_30_dialog_content = "それがしはかつて幾度か賊どもと遭遇したことがある。\n見紛うはずがない。",
  ui_story_5070_50701001_31_dialog_content = "しかし、海賊は海の上を己の棲み家とする。\nかように危険な海域には、人一倍警戒しておるはずだが…",
  ui_story_5070_50701001_32_dialog_content = "風、あるいは何者かに追われ、ここまで来たか…",
  ui_story_5070_50701001_33_dialog_content = "こ、怖いこと言わないでください…\n暗鬼、嵐、海獣だけで、もう十分頭が痛いのに――",
  ui_story_5070_50701001_34_dialog_content = "他にも海賊船を危機に陥れた脅威があるなんて…\nしかも、僕たちもその脅威にさらされるかもしれないってことですよね？",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>バシャッ</color>",
  ui_story_5070_50701001_36_dialog_content = "ユエ！ユエが戻ってきた！",
  ui_story_5070_50701001_37_dialog_content = "ここがどこか分かったわ。",
  ui_story_5070_50701001_38_dialog_content = "この下に数年前事故に遭った遠洋漁船が沈んでいたわ。",
  ui_story_5070_50701001_39_dialog_content = "漁船の航路から推測するに、\n私たちは今、遠洋と龍州近海の境界水域にいるはずよ。",
  ui_story_5070_50701001_40_dialog_content = "ということは…",
  ui_story_5070_50701001_41_dialog_content = "はい。龍州に近い所まで来ています。",
  ui_story_5070_50701001_42_dialog_content = "よかった！",
  ui_story_5070_50701001_43_dialog_content = "でも、まだ安心はできないわ。",
  ui_story_5070_50701001_44_dialog_content = "ここは有名な死の海域よ。海図もなければ、\n蜃風号の規定の航路からも外れているわ。",
  ui_story_5070_50701001_45_dialog_content = "位置が分かったところで、\n航行経路を正確に判断するのは困難なの。",
  ui_story_5070_50701001_46_dialog_content = "しかも、船に積んだ食糧も残り少なくなっている…\nこれ以上時間を無駄にはできないわ。",
  ui_story_5070_50701001_47_dialog_content = "シュウさんとセンキョクに動力炉の出力を上げてもらって、\nこの海域を一気に抜けることはできないの？",
  ui_story_5070_50701001_48_dialog_content = "無理ね。この辺りはそこかしこで潮が渦を巻いているの。\n少しでも気を抜けば、海の底の墓場へまっしぐらよ。",
  ui_story_5070_50701001_49_dialog_content = "2人が力を貸してくれたとしても、\n危機的状況は変わらないわ。ただ…",
  ui_story_5070_50701001_50_dialog_content = "ただ…？",
  ui_story_5070_50701001_51_dialog_content = "船が航路を外れたことに真っ先に気がづき、\n早々に対策を立てていたなら、話は別よ。",
  ui_story_5070_50701001_52_dialog_content = "航路を外れたことに真っ先に気がついた…？\nセンキョク！？",
  ui_story_5070_50701001_53_dialog_content = "…",
  ui_story_5070_50701001_54_dialog_content = "もう…そんなふうに私を見ないで。",
  ui_story_5070_50701001_55_dialog_content = "確かに方法がないわけじゃないけど…",
  ui_story_5070_50701001_56_dialog_content = "一か八かの大勝負になるわよ。",
  ui_story_5070_50701001_57_dialog_content = "今、確かに窮地に陥ってはいるけど、\n少なくとも蜃風号は動いているし、進みながら航路を探すことはできるわ。",
  ui_story_5070_50701001_58_dialog_content = "でも、私の方法を使った場合、\n失敗すれば、蜃風号は終わり。",
  ui_story_5070_50701001_59_dialog_content = "私たちも魚のエサになるしかないの。",
  ui_story_5070_50701001_60_dialog_content = "万策尽きていない状況で、危険を冒すのはお勧めしないわ。",
  ui_story_5070_50701001_61_dialog_content = "船長！船長、大変です！霧が出てきました！",
  ui_story_5070_50701001_62_dialog_content = "見通しが悪くなるばかりです。どうしますか？",
  ui_story_5070_50701001_63_dialog_content = "この海域で霧の中を進むのは、自ら死を選ぶようなもの。",
  ui_story_5070_50701001_64_dialog_content = "もはや「万策尽きた」わ。",
  ui_story_5070_50701001_65_dialog_content = "…分かったわ。",
  ui_story_5070_50701001_66_dialog_content = "乗船する時、貨物室に特別なモノを運んでおいたの。",
  ui_story_5070_50701001_67_dialog_content = "カラクリを操縦し、動力も提供できるモノよ。",
  ui_story_5070_50701001_68_dialog_content = "火吹き蟹、水龍、それから蜃風号の動力炉も…",
  ui_story_5070_50701001_69_dialog_content = "それを使えば、未曽有の力を発揮できる。",
  ui_story_5070_50701001_70_dialog_content = "ただ、扱いが難しいうえ、とても不安定なの。",
  ui_story_5070_50701001_71_dialog_content = "過去に行われた試験の結果が記録に残されてるけど、\nそのモノが出力したエネルギーが大きすぎて…",
  ui_story_5070_50701001_72_dialog_content = "カラクリが持ち耐えられずに、壊れて終わってるの。",
  ui_story_5070_50701001_73_dialog_content = "だから、使うにしても、まずは水中で試験してからじゃないと。",
  ui_story_5070_50701001_74_dialog_content = "蜃風号の補修と改造も必要よ。最低でも起動時の衝撃に\n耐えられるようにしておかなきゃいけないわ。",
  ui_story_5070_50701001_75_dialog_content = "そうしなきゃ、局面を打開できないばかりか、\n自ら命を捧げることになるわね。",
  ui_story_5070_50701001_76_dialog_content = "後で蜃風号に積んである材料の一覧表を持ってくるわ。\nあなたは遠慮なく、やるべきことをやってちょうだい。",
  ui_story_5070_50701001_77_dialog_content = "乗組員には、全員あなたの指示に従うように伝えておくわ。",
  ui_story_5070_50701001_78_dialog_content = "それがしの火焔術も何かしらの役に立つであろう。",
  ui_story_5070_50701001_79_dialog_content = "わらわは先刻獲った魚を使い、飽きの来ないよう、\n新たな料理でも振る舞おうかのう。",
  ui_story_5070_50701001_80_dialog_content = "僕も…ええと、僕に何ができる？",
  ui_story_5070_50701001_81_dialog_content = "これから貨物室で探し物をしなきゃいけないの。",
  ui_story_5070_50701001_82_dialog_content = "PlayerNameはボクちゃんを探して、\n火の毒を抑える薬をもらってきてくれないかしら？",
  ui_story_5070_50701001_83_dialog_content = "つまり、センキョクは船に火の精を持ちこんだってこと？",
  ui_story_5070_50701001_84_dialog_content = "どうりで、ずっと火の精の匂いがしてたわけだ。\nボクの鼻がおかしくなったのかと思ってたけど、ほんとだったんだ。",
  ui_story_5070_50701001_85_dialog_content = "なんだ、あの子の仕業だったのか。\nそれにしても、危険なことするな…",
  ui_story_5070_50701001_86_dialog_content = "卜子が言ってたんだ。古代霊物の遺物は、\nその昔陰陽を定め、昼夜を分けたものなんだって。",
  ui_story_5070_50701001_87_dialog_content = "はぁ…そんなこと言っても仕方ないか。\nまったく…乗るは易く、下りるは難しだね。",
  ui_story_5070_50701001_88_dialog_content = "はい、お薬。それから、あの子に言っといて。\n船は壊しちゃだめだよって。",
  ui_story_5070_50701001_89_dialog_content = "センキョク、薬をもらってきたよ。",
  ui_story_5070_50701001_90_dialog_content = "ところで、君の話してたモノっていったい何なの？",
  ui_story_5070_50701001_91_dialog_content = "君の言った通りに伝えたら、\nリンセイが急にああだこうだと騒ぎ出したし――",
  ui_story_5070_50701001_92_dialog_content = "他の皆もそれが何か分かってるみたいだ。\n僕だけ蚊帳の外なんだけど！？",
  ui_story_5070_50701001_93_dialog_content = "あはは、それはPlayerNameだけじゃないわ。",
  ui_story_5070_50701001_94_dialog_content = "私もあなた以上に知ってるとは、\n胸を張って言えないの。",
  ui_story_5070_50701001_95_dialog_content = "え？",
  ui_story_5070_50701001_96_dialog_content = "実物を見れば、分かるわ。",
  ui_story_5070_50701001_97_dialog_content = "実物？どこにあるの？",
  ui_story_5070_50701001_98_dialog_content = "そういえば、前から聞きたかったんだけど、\nこの貨物室には、どうしてこんなにたくさん…木製の牛がいるの？",
  ui_story_5070_50701001_99_dialog_content = "ああ、それは龍州にはよくあるカラクリで、\n木牛流馬っていうの。歴史も古いのよ。",
  ui_story_5070_50701001_100_dialog_content = "普通は貨物輸送に使われるんだけど、\n荷物入れにしても便利なの。",
  ui_story_5070_50701001_101_dialog_content = "こうやって開ければ、中の物を取り出せるわ。",
  ui_story_5070_50701001_102_dialog_content = "中もずいぶん大きいんだね。\n膝を曲げれば、人1人くらい入れそうだ。",
  ui_story_5070_50701001_103_dialog_content = "試してみる？",
  ui_story_5070_50701001_104_dialog_content = "いや、遠慮しとくよ。荷物の気分を味わう趣味はないから。",
  ui_story_5070_50701001_105_dialog_content = "あはは、それもそうね。",
  ui_story_5070_50701001_106_dialog_content = "じゃあ、今日の主役を見てみましょ。",
  ui_story_5070_50701001_107_dialog_content = "この小さな箱が主役？",
  ui_story_5070_50701001_108_dialog_content = "見くびっちゃいけないわ。",
  ui_story_5070_50701001_109_dialog_content = "私の属する門派は「乾雲」っていう、\n鄴の国、さらには龍州大陸で一二を争う機巧術の流派なの。",
  ui_story_5070_50701001_110_dialog_content = "何千何百年と続く技術を受け継ぎ、\n数えきれないほどの秘宝も持っている。",
  ui_story_5070_50701001_111_dialog_content = "でも、その秘宝を全部合わせても、\nコレには敵わないわ。",
  ui_story_5070_50701001_112_dialog_content = "私が大海原を越えて、アストラまでやってきた、\n一番の目的は…",
  ui_story_5070_50701001_113_dialog_content = "何年も前に異国で行方知れずになった宝物を見つけること。",
  ui_story_5070_50701001_114_dialog_content = "その名を「燭陰火」というの。",
  ui_story_5070_50701001_115_dialog_content = "アストラの人たちの言い方では、そうね…\n非常に希少な太古の遺物よ。",
  ui_story_5070_50701001_116_dialog_content = "太古の遺物！？",
  ui_story_5070_50701001_117_dialog_content = "どれくらいの威力か試してみたい？",
  ui_story_5070_50701001_118_dialog_content = "蜃風号の上では危険だから、\n小舟で遠くへ行って試験しましょ。",
  ui_story_5070_50701001_119_dialog_content = "何万年も前、万物を動かしていた、\n真の天の力を見てみましょ。",
  ui_story_5070_50701002_1_dialog_content = "さすがは太古の宝ね。\n思っていたよりもずっと強大だわ。",
  ui_story_5070_50701002_2_dialog_content = "PlayerNameも感知してみたでしょ？\nどうかしら？",
  ui_story_5070_50701002_3_dialog_content = "すごい…",
  ui_story_5070_50701002_4_dialog_content = "すでに光力を使い切ったカラクリ獣に、\n無尽蔵にエネルギーを送って動かしただけじゃなく…",
  ui_story_5070_50701002_5_dialog_content = "周りの水が全部蒸発して、大きな真空空間ができちゃったよ。",
  ui_story_5070_50701002_6_dialog_content = "しかも、ほかのどんな炎よりも、\nずっと凝縮されてる感じがした。まるで…",
  ui_story_5070_50701002_7_dialog_content = "圧縮した太陽みたい？",
  ui_story_5070_50701002_8_dialog_content = "うん…あれ？ちょっと待って。\nそれって僕が前に言ったことじゃ？",
  ui_story_5070_50701002_9_dialog_content = "燭陰火が…あの日の爆発を起こした\n原因だったかもしれないってこと！？",
  ui_story_5070_50701002_10_dialog_content = "あ～あ、分かっちゃったわね。",
  ui_story_5070_50701002_11_dialog_content = "君が感知していいって言ったんだよ！？\n今回は僕もムチャはしてないよ！",
  ui_story_5070_50701002_12_dialog_content = "百聞は一見に如かずって言うでしょ。\n私が説明するより、自分で気づく方がずっと理解しやすいわ。",
  ui_story_5070_50701002_13_dialog_content = "どうりで、リンセイがあんなに騒いでたんだね。",
  ui_story_5070_50701002_14_dialog_content = "普通そんな危険な物を船に持ってくる人がいるなんて思わないよ。",
  ui_story_5070_50701002_15_dialog_content = "あら、ちゃんと封印してから持ってきたのよ。\n何もしなければ、危険はないわ。",
  ui_story_5070_50701002_16_dialog_content = "でも、火災が起こったあの日…封印を解いた人がいた。",
  ui_story_5070_50701002_17_dialog_content = "私はこっそり持ってきたのにも関わらずね。",
  ui_story_5070_50701002_18_dialog_content = "ユエには可燃爆発物だって断っておいたけど、\nそのユエでさえ本当のところはよく知らなかったのに――",
  ui_story_5070_50701002_19_dialog_content = "誰かがその存在を知って、近づこうとしたのよ。",
  ui_story_5070_50701002_20_dialog_content = "ということは、まさか僕が見た、あの人影が…",
  ui_story_5070_50701002_21_dialog_content = "おそらくね。",
  ui_story_5070_50701002_22_dialog_content = "だったら…急いで他の皆にも知らせなきゃ。",
  ui_story_5070_50701002_23_dialog_content = "燭陰火のテストも成功したし、\n蜃風号はすぐにこの海域から出られる。",
  ui_story_5070_50701002_24_dialog_content = "今のうちに、何か企んでるヤツを捕まえないと――",
  ui_story_5070_50701002_25_dialog_content = "試験が成功したなんて言ってないわよ。",
  ui_story_5070_50701002_26_dialog_content = "え？でも、カラクリ獣は無事に動いたよ？",
  ui_story_5070_50701002_27_dialog_content = "動力としての燭陰火の威力は申し分ないわ。\nでも、起動後のカラクリ獣はどうなったかしら？",
  ui_story_5070_50701002_28_dialog_content = "…粉々になって、海に落ちた…",
  ui_story_5070_50701002_29_dialog_content = "カラクリ獣は大きくないから、\n私が核を制御できていたのに、それでもこの有様なのよ。",
  ui_story_5070_50701002_30_dialog_content = "蜃風号の強度じゃ、ありったけの材料を使って、\n船体を強固にしたとしても…",
  ui_story_5070_50701002_31_dialog_content = "燭陰火の全開出力には耐えられないと思うわ。",
  ui_story_5070_50701002_32_dialog_content = "センキョクでも、どうにもできないの？",
  ui_story_5070_50701002_33_dialog_content = "…そうでもないわ。",
  ui_story_5070_50701002_34_dialog_content = "ただ、その前にあなたに頼みがあるの。",
  ui_story_5070_50701002_35_dialog_content = "試験が失敗したことも、燭陰火で何かを企んでる人がいることも、\n今は誰にも言わないでほしいの。",
  ui_story_5070_50701002_36_dialog_content = "それは構わないけど…でも、それなら僕たちは、\nこれから何をするの？",
  ui_story_5070_50701002_37_dialog_content = "待つのよ。",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5070_50701002_39_dialog_content = "全員図面を取りに来い。\n図面の印に沿って位置に就き、仕事を始めるんだ。",
  ui_story_5070_50701002_40_dialog_content = "何の図面だ？",
  ui_story_5070_50701002_41_dialog_content = "この図面は…",
  ui_story_5070_50701002_42_dialog_content = "俺も長いこと船の仕事をやってるが、\nこんなもん見たことねえ…",
  ui_story_5070_50701002_43_dialog_content = "甲板のデッカイ穴をふさがないってのは、まだいいとしても、\nそれを広げろってんだからよ。",
  ui_story_5070_50701002_44_dialog_content = "これじゃあ蜃風号の核が丸出しになっちまうじゃねえか。\n本当にこんなんでいいのか…？ソン、お前はどう思う？",
  ui_story_5070_50701002_45_dialog_content = "うーん…俺にも分からねえ…",
  ui_story_5070_50701002_46_dialog_content = "そんなこと、どうでもいいだろ。\nセンキョク様は俺たちよりずっと優秀なんだ。",
  ui_story_5070_50701002_47_dialog_content = "さっさと仕事を始めるぞ。\nそれが終われば、きっとこの海域を抜けられるさ。",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>3日目</color>",
  ui_story_5070_50701002_49_dialog_content = "何人かこっちに来てくれ。魚を獲るぞ。",
  ui_story_5070_50701002_50_dialog_content = "はぁ…魚づくしの飯はこれで何日目だ！？\nこの2日は味さえ付いてねえし…まったく。",
  ui_story_5070_50701002_51_dialog_content = "もう少しの辛抱だ。\n改造さえ終われば、状況も変わるってもんだ。",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>5日目</color>",
  ui_story_5070_50701002_53_dialog_content = "魚を獲ってたトコの霧が濃くなりやがった。\nこのままじゃ魚も獲れなくなっちまう。",
  ui_story_5070_50701002_54_dialog_content = "蜃風号の改造は終わったんじゃねえのか？\nセンキョク様はなんで何もしねえんだ…",
  ui_story_5070_50701002_55_dialog_content = "おい、リー。誰にも言うなよ…\nソンが言うには、俺たちのやった改造は何の意味もねえってさ。",
  ui_story_5070_50701002_56_dialog_content = "センキョク様は毎日小舟で海に出て、航路を探してるって言ってるが、\n実際は、どうすればいいか分かんねえだけだっつう話だ。",
  ui_story_5070_50701002_57_dialog_content = "何言ってんだ！ソンの野郎も適当なこと言いいやがって。\n船長に聞かれでもしてみろ…",
  ui_story_5070_50701002_58_dialog_content = "おや、PlayerNameの旦那じゃねえか！PlayerNameの旦那！",
  ui_story_5070_50701002_59_dialog_content = "ここんとこセンキョク様と一緒に海に出てるようですが、\nどうやってこの海域を抜けるか、聞いてませんかね？",
  ui_story_5070_50701002_60_dialog_content = "あ、それについては…大丈夫だとしか…\nそうだ、センキョクに物を届けなくちゃいけないから、行くね。",
  ui_story_5070_50701002_61_dialog_content = "ふぅ…",
  ui_story_5070_50701002_62_dialog_content = "PlayerName、見てちょうだい！\nあなたの巨像の説明に基づいて、構造模型を造ったの。",
  ui_story_5070_50701002_63_dialog_content = "あら？その顔は…また誰かにしつこく質問されたの？",
  ui_story_5070_50701002_64_dialog_content = "あはは…もう何日もここに留まってるからね。\nずっと神経が張り詰めたままだから、皆一刻も早く離れたいんだろうね。",
  ui_story_5070_50701002_65_dialog_content = "この模型…うーん…巨像というより、\n翼の生えた蜃風号に見えるんだけど。そうだな…",
  ui_story_5070_50701002_66_dialog_content = "PlayerNameは私に聞きたいことはないの？",
  ui_story_5070_50701002_67_dialog_content = "え？",
  ui_story_5070_50701002_68_dialog_content = "ちゃんと説明もしないまま、秘密にしてもらってるでしょ？",
  ui_story_5070_50701002_69_dialog_content = "他の皆にたくさんの改造作業をさせておいて、\n自分は一日中小舟で海に出て、何か聞かれるのを避けてる。",
  ui_story_5070_50701002_70_dialog_content = "自分でも虚勢を張ってるだけなんじゃないかって、\n思えてきたくらいよ。",
  ui_story_5070_50701002_71_dialog_content = "それなのにPlayerNameはどうして、\n私をそんなに信じて疑わないの？",
  ui_story_5070_50701002_72_dialog_content = "君を信じてるわけじゃないよ。",
  ui_story_5070_50701002_73_dialog_content = "それもそうよね…",
  ui_story_5070_50701002_74_dialog_content = "機巧術を信じてるんだ。",
  ui_story_5070_50701002_75_dialog_content = "えっ？",
  ui_story_5070_50701002_76_dialog_content = "確かに、急に襲って来たカラクリ獣に、\n悩まされたこともあったけど――",
  ui_story_5070_50701002_77_dialog_content = "君と初めて会った時、カラクリのトンボが手紙を拾ってくれた。",
  ui_story_5070_50701002_78_dialog_content = "動力炉を動かしてくれた火吹き蟹も、\n火を消してくれた水龍も…",
  ui_story_5070_50701002_79_dialog_content = "僕は何度もカラクリに助けられた。",
  ui_story_5070_50701002_80_dialog_content = "君も言ってたでしょ？機巧術は変幻自在どころじゃない、\n何でもできる技術なんだって。",
  ui_story_5070_50701002_81_dialog_content = "僕は機巧術を信じるよ。\nそれに君はカラクリに関することで、絶対にウソつかないでしょ？",
  ui_story_5070_50701002_82_dialog_content = "だから、君ならきっと僕たちを龍州まで\n無事に連れて行ってくれると信じてるんだ。",
  ui_story_5070_50701002_83_dialog_content = "ああ。",
  ui_story_5070_50701002_84_dialog_content = "この私でさえ反論のできない論点だわ。",
  ui_story_5070_50701002_85_dialog_content = "PlayerNameがそこまで信じてくれてるのに――",
  ui_story_5070_50701002_86_dialog_content = "機巧術に何が出来るか、ちゃんと見せてあげられなかったら、\n私は機巧師として失格よ！",
  ui_story_5070_50701002_87_dialog_content = "うん、楽しみにしてる。\nでも…少しも気になってないって言ったらウソになるかな。",
  ui_story_5070_50701002_88_dialog_content = "センキョク、いったい何を待ってるの？",
  ui_story_5070_50701002_89_dialog_content = "実は…",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>ボーッ――</color>",
  ui_story_5070_50701002_91_dialog_content = "蜃風号の笛の音？急にどうしたんだろう？",
  ui_story_5070_50701002_92_dialog_content = "今のは船と船が海上でやりとりをする時の信号よ。",
  ui_story_5070_50701002_93_dialog_content = "他にも船が現れたの！？",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>少し前</color>",
  ui_story_5070_50701002_95_dialog_content = "キュウ、ユエ、早う。",
  ui_story_5070_50701002_96_dialog_content = "遠くに見えるのは船ではなかろうか？",
  ui_story_5070_50701002_97_dialog_content = "殿下、お下がりくださいませ。\n船べりに近づいては危のうございます。",
  ui_story_5070_50701002_98_dialog_content = "キュウ、今はさようなことに構っておられぬ。",
  ui_story_5070_50701002_99_dialog_content = "いかなる時も、殿下の安全が一番の大事でございます。\nお気をつけくださいませ。",
  ui_story_5070_50701002_100_dialog_content = "船上の様子はよく見えませんが、\n確かに商船がこちらへ向かってきているようです。",
  ui_story_5070_50701002_101_dialog_content = "まさか、この海域に他の船が現れるとは。",
  ui_story_5070_50701002_102_dialog_content = "連絡をお取りになるのですか？\n十分な物資を積んでいるかどうかは存じませんが、もし…",
  ui_story_5070_50701002_103_dialog_content = "いずれにせよ、今から回避しても間に合わないわ。",
  ui_story_5070_50701002_104_dialog_content = "船笛を鳴らして、相手の反応を見てみましょ。",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>ボーッ――</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>ボーッ――</color>",
  ui_story_5070_50701002_107_dialog_content = "反応があったよ！",
  ui_story_5070_50701002_108_dialog_content = "あの船もここに足止めされてるのかな？\nちょうどいいね。一緒に打開策を考えられるよ。",
  ui_story_5070_50701002_109_dialog_content = "食べ物や水ももらえるかも知れない。",
  ui_story_5070_50701002_110_dialog_content = "じゃ、急いで船に戻りましょ。\n話は早い方がいいわ。",
  ui_story_5070_50701002_111_dialog_content = "相手の船が見えた。向こうも蜃風号に近づいてくるよ。",
  ui_story_5070_50701002_112_dialog_content = "あれ…？ちょっと速すぎない？",
  ui_story_5070_50701002_113_dialog_content = "減速するどころか、スピードを上げてるよ！",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_5070_50701002_115_dialog_content = "船が…相手の船が蜃風号にぶつかった！？",
  ui_story_5070_50701002_116_dialog_content = "おかしいわ…",
  ui_story_5070_50701002_117_dialog_content = "海賊船よ！",
  ui_story_5070_50701002_118_dialog_content = "PlayerName、加速するわよ！\n蜃風号が危ないわ！",
  ui_story_5070_50701101_1_dialog_content = "無礼極まる賊どもが！よくもキュウを――",
  ui_story_5070_50701101_2_dialog_content = "危ない！",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>シュッ！</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>タンドウの足下に攻撃が当たり、\n甲板の板が焼け落ちて、大きな穴が開いた</color>",
  ui_story_5070_50701101_5_dialog_content = "…",
  ui_story_5070_50701101_6_dialog_content = "殿下、恐れながら、憂さ晴らしも程々にした方がよろしいかと――",
  ui_story_5070_50701101_7_dialog_content = "海の上では慎重になるに越したことはありません。\n長い航海を無事に終えたければ、の話ですが。",
  ui_story_5070_50701101_8_dialog_content = "タンドウが攻撃されたみたいだ！\n急いで上へあがろう――",
  ui_story_5070_50701101_9_dialog_content = "待って。相手は私たちが誰だか知ってるわ。\nタンドウ様やキュウさんに本気で手を出すとは思えない。",
  ui_story_5070_50701101_10_dialog_content = "だけど私たちは相手のことを知らない。\n今上に行っても、相手の餌食になるだけよ。",
  ui_story_5070_50701101_11_dialog_content = "まずはこのまま隠れて、状況を見てから動きましょ。",
  ui_story_5070_50701101_12_dialog_content = "うーん…さっきタンドウと話してた人の声、\n何だか聞き覚えがある…",
  ui_story_5070_50701101_13_dialog_content = "腕利きのソンさんよ。",
  ui_story_5070_50701101_14_dialog_content = "ソンさん！？",
  ui_story_5070_50701101_15_dialog_content = "シッ。",
  ui_story_5070_50701101_16_dialog_content = "聞いて。",
  ui_story_5070_50701101_17_dialog_content = "あなた、本物のソンじゃないわね。",
  ui_story_5070_50701101_18_dialog_content = "ふん、腕利きのソンは仮の姿にすぎない。",
  ui_story_5070_50701101_19_dialog_content = "だが、あんたたちが知ることができるのも、\nせいぜい、そのくらいだ。",
  ui_story_5070_50701101_20_dialog_content = "お、お前…！海賊と手を組んでやがったのか！？",
  ui_story_5070_50701101_21_dialog_content = "リン家の恩を忘れたか！？\n恩知らずの裏切者め――",
  ui_story_5070_50701101_22_dialog_content = "大人しくしてろ！",
  ui_story_5070_50701101_23_dialog_content = "キュウのお嬢さんの所へ行きたくなかったら、\n静かにしてるんだな。",
  ui_story_5070_50701101_24_dialog_content = "あんたたちもだ。この船に乗ってる者の中で、\n一番強いヤツはもう先に逝っちまった。",
  ui_story_5070_50701101_25_dialog_content = "これ以上あがいても無駄だろうな。",
  ui_story_5070_50701101_26_dialog_content = "卑怯な手を使いおって！",
  ui_story_5070_50701101_27_dialog_content = "あの奇妙な白い光さえなければ、\nキュウがお主らの卑劣な手にかかるはずなかろう！",
  ui_story_5070_50701101_28_dialog_content = "卑劣？郡主殿下、言葉を謹んでいただきたいですね。",
  ui_story_5070_50701101_29_dialog_content = "あれはこの船と肩を並べる…\nいや、この蜃風号を超える素晴らしい船なんですから！",
  ui_story_5070_50701101_30_dialog_content = "ふん。口では何とでも言えるわ。",
  ui_story_5070_50701101_31_dialog_content = "船に隠れ、遠くより不意打ちを仕掛けることしか出来ぬのじゃ。\nさぞかし醜かろうのう。",
  ui_story_5070_50701101_32_dialog_content = "（その調子です、タンドウ殿下。\n相手を刺激し、怒らせてください）",
  ui_story_5070_50701101_33_dialog_content = "（キュウたちが戻る前に、できるだけ多くの情報を聞き出さなくては）",
  ui_story_5070_50701101_34_dialog_content = "不意打ちだけじゃないわ。船に上がるやいなや、\n手下にシュウ様とリンセイを捕らえさせた。",
  ui_story_5070_50701101_35_dialog_content = "寄ってたかって、身体の不自由な者と子どもを狙うなんて、\nよほどの腰抜けの集まりね。",
  ui_story_5070_50701101_36_dialog_content = "二手に分かれて行動しましょ。",
  ui_story_5070_50701101_37_dialog_content = "あの白い光を出すモノは、明らかにカラクリよ。\nしかも強大な出力をもってる。",
  ui_story_5070_50701101_38_dialog_content = "調べないといけないわ。",
  ui_story_5070_50701101_39_dialog_content = "じゃあ、僕は？",
  ui_story_5070_50701101_40_dialog_content = "この舟に残って、引き続き蜃風号の様子をうかがっててちょうだい。",
  ui_story_5070_50701101_41_dialog_content = "うまく隠れてるのよ。じゃあ、私は――",
  ui_story_5070_50701101_42_dialog_content = "そんなの「二手に分かれる」とは言わないよ。",
  ui_story_5070_50701101_43_dialog_content = "？",
  ui_story_5070_50701101_44_dialog_content = "僕だけ安全な所に残って、\n君だけが危険を冒しに行くって言うんだよ。",
  ui_story_5070_50701101_45_dialog_content = "でも…",
  ui_story_5070_50701101_46_dialog_content = "でも、時間は待ってくれない。",
  ui_story_5070_50701101_47_dialog_content = "蜃風号に戻らなきゃ。戦うのは無理でも…",
  ui_story_5070_50701101_48_dialog_content = "きっと僕にも出来ることがあるはずだ。",
  ui_story_5070_50701101_49_dialog_content = "見つかったとしても、時間稼ぎは出来るかもしれない。",
  ui_story_5070_50701101_50_dialog_content = "これこそ「二手に分かれる」だよ。",
  ui_story_5070_50701101_51_dialog_content = "じゃあ…認めないって言ったら？",
  ui_story_5070_50701101_52_dialog_content = "だったら、君が行った後にこっそり船に戻ればいい。",
  ui_story_5070_50701101_53_dialog_content = "いつも進んで危険な所へ向かうのが、\n空の末裔の習性なの？",
  ui_story_5070_50701101_54_dialog_content = "じゃあ、皆を守るために自分が盾になって、\n後のことは全部1人で抱え込むのが機巧師の習性？",
  ui_story_5070_50701101_55_dialog_content = "…お互い様ってことね。",
  ui_story_5070_50701101_56_dialog_content = "PlayerNameは私を信頼してくれたのに…",
  ui_story_5070_50701101_57_dialog_content = "私がPlayerNameを信頼しなかったら、不公平よね。",
  ui_story_5070_50701101_58_dialog_content = "じゃあ…幸運を祈ってるわ。",
  ui_story_5070_50701102_1_dialog_content = "強制感知！忘れてたことを思い出して――",
  ui_story_5070_50701102_2_dialog_content = "あ！賞金をまだ頭からもらってなかったな。\nせっつきに行かねえと…",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>トントントン――</color>",
  ui_story_5070_50701102_4_dialog_content = "（よし！龍州の海賊は、空の末裔の精神感知能力について、\n知識も経験もないんだ…）",
  ui_story_5070_50701102_5_dialog_content = "（このまま精神感知で暗示を続ければ、\n気がかりなことがある人は、ひとまずここを離れてくれる…）",
  ui_story_5070_50701102_6_dialog_content = "入口にいた奴はどこ行った？\n巡回はどうすんだ？",
  ui_story_5070_50701102_7_dialog_content = "こっちの任務に影響しなけりゃ構わねえだろ。",
  ui_story_5070_50701102_8_dialog_content = "動けねえジジイとガキ１人を見張るのに、牢まで使うなんてな。\n何を怖がってんだか。",
  ui_story_5070_50701102_9_dialog_content = "（見張りが多い！あのカラクリの牢の中は…\nシュウさんとリンセイだ！）",
  ui_story_5070_50701102_10_dialog_content = "（あれ？リンセイは何をしてるんだろう？）",
  ui_story_5070_50701102_11_dialog_content = "（くんくん…）",
  ui_story_5070_50701102_12_dialog_content = "（この匂いは…PlayerNameだね！）",
  ui_story_5070_50701102_13_dialog_content = "（こっち、こっち！あ、目が合った！）",
  ui_story_5070_50701102_14_dialog_content = "ニャ～。",
  ui_story_5070_50701102_15_dialog_content = "ああ？なんだ？ネコの鳴きマネか？",
  ui_story_5070_50701102_16_dialog_content = "退屈なんだよ。外に出してはくれないんでしょ？",
  ui_story_5070_50701102_17_dialog_content = "（リンセイは、何が言いたいんだろう？）",
  ui_story_5070_50701102_18_dialog_content = "ニャ～。",
  ui_story_5070_50701102_19_dialog_content = "（チビシッポ！それからシュウさんの…「シン」「メン」「ダク」だね？）",
  ui_story_5070_50701102_20_dialog_content = "（いったい、どこから出てきたの？）",
  ui_story_5070_50701102_21_dialog_content = "入口で何か音がしなかったか？",
  ui_story_5070_50701102_22_dialog_content = "ああ？お前の聞き間違いだろ。",
  ui_story_5070_50701102_23_dialog_content = "さっきは赤髪のジジイに見覚えがあるとか言ってたが、\n今度は入口で音がしたって？まったく、面倒くせえ奴だな。",
  ui_story_5070_50701102_24_dialog_content = "見てくる。",
  ui_story_5070_50701102_25_dialog_content = "（！！！）",
  ui_story_5070_50701102_26_dialog_content = "（隠れなきゃ…間に合わない！こうなったら一か八かだ！）",
  ui_story_5070_50701102_27_dialog_content = "お願い、時間稼ぎして！",
  ui_story_5070_50701102_28_dialog_content = "ニャ～！",
  ui_story_5070_50701102_29_dialog_content = "何！？",
  ui_story_5070_50701102_30_dialog_content = "どこから出てきやがった！どけ！チッ…咬みやがったな！",
  ui_story_5070_50701102_31_dialog_content = "（今だ！部屋の中にいる全員を…）",
  ui_story_5070_50701102_32_dialog_content = "強制感知する！",
  ui_story_5070_50701102_33_dialog_content = "うう――急に頭に激痛が走ったぞ！？",
  ui_story_5070_50701102_34_dialog_content = "ネコが…ネコが顔をひっかきやがった！！",
  ui_story_5070_50701102_35_dialog_content = "PlayerName！先にシュウさんを助けて！",
  ui_story_5070_50701102_36_dialog_content = "ニャ～。",
  ui_story_5070_50701102_37_dialog_content = "カギを持ってきてくれたの？ありがとう、チビシッポ。",
  ui_story_5070_50701102_38_dialog_content = "シュウさん、待っててください。今カギを開けますから。",
  ui_story_5070_50701102_39_dialog_content = "かたじけない。それがしは大事ない。焦らずともよい。",
  ui_story_5070_50701102_40_dialog_content = "見ているこっちが焦ってきちゃったよ！\nPlayerName、もたもたしすぎだよ。ボクがやる！",
  ui_story_5070_50701102_41_dialog_content = "えっ、リンセイ！？どうやって出てきたの？",
  ui_story_5070_50701102_42_dialog_content = "こんな大きな隙間、\nちょっと身体を横にすれば出られるでしょ？",
  ui_story_5070_50701102_43_dialog_content = "それって…光霊なら出来ることなの…？",
  ui_story_5070_50701102_44_dialog_content = "もちろん、普通の光霊にはできないよ。\nでも、ボクは特別なんだ。",
  ui_story_5070_50701102_45_dialog_content = "特別！？",
  ui_story_5070_50701102_46_dialog_content = "あれ？話してなかったっけ？",
  ui_story_5070_50701102_47_dialog_content = "ボクはネコなんだよ。",
  ui_story_5070_50701102_48_dialog_content = "！？",
  ui_story_5070_50701102_49_dialog_content = "正確には、ネコの祟霊だね。\nそっちにいるチビシッポは、ボクの兄さんなんだ。",
  ui_story_5070_50701102_50_dialog_content = "お、お兄さんなの…！？",
  ui_story_5070_50701102_51_dialog_content = "PlayerName？なんで、とまっちゃったの？",
  ui_story_5070_50701102_52_dialog_content = "アストラ大陸に祟霊はおらん。\nPlayerNameが驚くのも無理はなかろう。",
  ui_story_5070_50701102_53_dialog_content = "シュウさん…",
  ui_story_5070_50701102_54_dialog_content = "うむ、何用か？",
  ui_story_5070_50701102_55_dialog_content = "シュウさんもネコちゃんを3匹連れてますけど…\n祟霊じゃないですよね？",
  ui_story_5070_50701102_56_dialog_content = "突然ネコに化けたりしませんよね？",
  ui_story_5070_50701102_57_dialog_content = "はっはっは。それがしは普通の光霊だ。\n失望させてしまったかな。",
  ui_story_5070_50701102_58_dialog_content = "いいえ、そんなことありません！むしろ良かったです…\nシュウさんがいつも頼りになる人で。",
  ui_story_5070_50701102_59_dialog_content = "うっ…お、お前たち…",
  ui_story_5070_50701102_60_dialog_content = "PlayerName、海賊たちが正気に戻ったみたいだよ。",
  ui_story_5070_50701102_61_dialog_content = "コイツらだけじゃない。入口にたくさん人が集まってきてる。\nたぶん、甲板の方から来たんだ。",
  ui_story_5070_50701102_62_dialog_content = "取り囲め！",
  ui_story_5070_50701102_63_dialog_content = "戦えるのは、あのろくに身体も動かせねえ野郎だけだ。\nしかも、奴は火焔術以外大したことねえ。",
  ui_story_5070_50701102_64_dialog_content = "炎さえ押さえちまえば、ただの野郎だ。",
  ui_story_5070_50701102_65_dialog_content = "なんてヤツらだ！",
  ui_story_5070_50701102_66_dialog_content = "シュウさんはまず自分の身を守ってください。\nあとは僕とリンセイで何とかします。",
  ui_story_5070_50701102_67_dialog_content = "え？PlayerName、知らないの？シュウさんは…",
  ui_story_5070_50701102_68_dialog_content = "気持ちだけ、もらっておこう。",
  ui_story_5070_50701102_69_dialog_content = "リン家のご当主も戦えないにも関わらず、\n常にそれがしをかばってくれた…",
  ui_story_5070_50701102_70_dialog_content = "それがしは賊どもと長年やり合って来た。\nここで捕らえられたとて、それはただ運が尽きたにすぎぬ。",
  ui_story_5070_50701102_71_dialog_content = "おそらく天もこの賊どもとやり合い、\n過去を清算せよとそれがしに申してるのであろう。",
  ui_story_5070_50701102_72_dialog_content = "ゆえにこの敵は、それがしに任せてくれぬか？",
  ui_story_5070_50701102_73_dialog_content = "分かりました。僕も出来る限りサポートを――",
  ui_story_5070_50701102_74_dialog_content = "無用だ。貴公のその特殊な能力は、\nタンドウ殿下と璇璣卿にこそ必要なものだろう。",
  ui_story_5070_50701102_75_dialog_content = "それがしは一つの戦法しか知らぬが、\nそれで十分だ。",
  ui_story_5070_50701102_76_dialog_content = "もし手助けを願えるならば、\n賊どもに奪われた剣を渡してもらえぬか？",
  ui_story_5070_50701102_77_dialog_content = "分かりました。この剣ですね…うっ、重い！",
  ui_story_5070_50701102_78_dialog_content = "かたじけない。",
  ui_story_5070_50701102_79_dialog_content = "（剣を手にした瞬間、シュウさんの目つきが変わった…？）",
  ui_story_5070_50701102_80_dialog_content = "ハハハ。ろくに動けもしねえくせに、\n独りで俺たちに立ち向かおうってか？",
  ui_story_5070_50701102_81_dialog_content = "まったく、身の程知らずな――",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_5070_50701102_83_dialog_content = "野郎だ…",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>海賊は高笑いを浮かべたまま、その場に倒れた</color>",
  ui_story_5070_50701102_85_dialog_content = "や、野郎…な、何をしやがったんだ？",
  ui_story_5070_50701102_86_dialog_content = "慌てるな！剣が速いからなんだっていうんだ！？\nこっちはこれだけの人数がいるんだぞ！",
  ui_story_5070_50701102_87_dialog_content = "下手な称賛などいらぬ。\nいずれお前たちはそれがしの前から消えるのだからな。",
  ui_story_5070_50701102_88_dialog_content = "おい！さっき炎さえ抑え込めばいいって言ったのは誰だ！？",
  ui_story_5070_50701102_89_dialog_content = "こ、こいつ…火なんか使わねえじゃねえか！",
  ui_story_5070_50701102_90_dialog_content = "大勢の海賊たちが…シュウさん1人に圧倒されてる…",
  ui_story_5070_50701102_91_dialog_content = "当然でしょ。シュウさんを誰だと思ってるの？",
  ui_story_5070_50701102_92_dialog_content = "し…死ね――！",
  ui_story_5070_50701102_93_dialog_content = "シュウさん！後ろ！",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_5070_50701102_95_dialog_content = "うわ――！",
  ui_story_5070_50701102_96_dialog_content = "心配する必要なかったみたいだね。\nシュウさんの剣の方が僕が声を出すよりずっと速かった。",
  ui_story_5070_50701102_97_dialog_content = "ほらね。車椅子に乗ってようと、\nシュウさんがこんな烏合の衆にやられるわけないんだ。",
  ui_story_5070_50701102_98_dialog_content = "海の災難はそれがしの足を奪った。",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_5070_50701102_100_dialog_content = "それがしの炎を抑えられるのなら、やってみるがいい。",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_5070_50701102_102_dialog_content = "だが、それがしにはまだ腕も剣も残っておる。",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>スッ…</color>",
  ui_story_5070_50701102_104_dialog_content = "剣を振るい、敵を斬ることができるのだ。",
  ui_story_5070_50701102_105_dialog_content = "それが、我が唯一の戦法だ。",
  ui_story_5070_50701102_106_dialog_content = "ば…バケモンだ！",
  ui_story_5070_50701102_107_dialog_content = "かつてはよく、お主らのような賊どもにそう呼ばれていたな。",
  ui_story_5070_50701102_108_dialog_content = "ま、待て…お前は…ま、まさか…",
  ui_story_5070_50701102_109_dialog_content = "思い出した！",
  ui_story_5070_50701102_110_dialog_content = "赤い髪をした、長羽織の男――",
  ui_story_5070_50701102_111_dialog_content = "たった一人で賊の船に乗り込み、剣一つで賊を制した…",
  ui_story_5070_50701102_112_dialog_content = "済の国近海で覇を唱えた海賊を\nことごとく平定した大将軍は…お前だな！？",
  ui_story_5070_50701102_113_dialog_content = "央京の皇帝自ら称号を授けたという、平野大将軍だ！",
  ui_story_5070_50701102_114_dialog_content = "過ぎしことだ。",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>バッ――</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>最後の1人が倒れた</color>",
  ui_story_5070_50701102_117_dialog_content = "それがしは今や一介の浪人にすぎぬ…",
  ui_story_5070_50701102_118_dialog_content = "あるいは、若者にささやかな手助けをする、\nただの年寄りと言おうか。",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>同じ頃、敵の船の中では</color>",
  ui_story_5070_50701201_2_dialog_content = "（この船、蜃風号と同じ構造をしてるの！？）",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>サッ――</color>",
  ui_story_5070_50701201_4_dialog_content = "！",
  ui_story_5070_50701201_5_dialog_content = "乗った途端にこんなに素敵な贈り物をもらえるなんて、\n光栄の極みだわ。",
  ui_story_5070_50701201_6_dialog_content = "サソリだけど、毒針の暗器じゃないのね…",
  ui_story_5070_50701201_7_dialog_content = "アストラの人が得意とする、光力を集束させた槍ね。",
  ui_story_5070_50701201_8_dialog_content = "グア！",
  ui_story_5070_50701201_9_dialog_content = "尾は槍で、ハサミは刃、身体は厚い金属で覆われてる…",
  ui_story_5070_50701201_10_dialog_content = "千機斉射！",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5070_50701201_12_dialog_content = "金属のような音に、軟玉のような質感――",
  ui_story_5070_50701201_13_dialog_content = "これだけの攻撃を受けていながら、全く損傷がないところを見ると、\nかなり希少で上等な材料で造られてるようね。",
  ui_story_5070_50701201_14_dialog_content = "やれやれ…",
  ui_story_5070_50701201_15_dialog_content = "ガガガ…",
  ui_story_5070_50701201_16_dialog_content = "燃費も相当なものでしょうね。",
  ui_story_5070_50701201_17_dialog_content = "でも、しばらくやり合ってるけど、攻撃の頻度も強度もまったく弱まる様子はないわ。\nむしろ、かすかに強化されてきてる。",
  ui_story_5070_50701201_18_dialog_content = "中に仕込まれた駆動核はそうとう優秀なものみたいね。\n世界中探しても、おそらく二つとないわ。",
  ui_story_5070_50701201_19_dialog_content = "ああ、でも奇遇よね。\n蜃風号にも、ちょうど同じようなものがあるのよ。",
  ui_story_5070_50701201_20_dialog_content = "この子を解体して、核を見てみたら、もしかしてちょうど…",
  ui_story_5070_50701201_21_dialog_content = "燭陰火と瓜二つだったりして。",
  ui_story_5070_50701201_22_dialog_content = "解体できればの話だがな。",
  ui_story_5070_50701201_23_dialog_content = "あら、ようやく姿を現したわね。",
  ui_story_5070_50701201_24_dialog_content = "「腕利きのソン」の皮は脱ぎ捨てて、\n今度は正々堂々悪党としてお出ましってわけね。",
  ui_story_5070_50701201_25_dialog_content = "裏でコソコソ動くことしかできないのかと思ってたわ。",
  ui_story_5070_50701201_26_dialog_content = "ふん、何とでも言え。",
  ui_story_5070_50701201_27_dialog_content = "負け犬の遠吠えってヤツだな。\nなす術もないと白状してるようなもんだ。",
  ui_story_5070_50701201_28_dialog_content = "負け犬？それは逆じゃないの？",
  ui_story_5070_50701201_29_dialog_content = "自分は他人より劣ってる、自分は敗者だって思ってるからこそ…",
  ui_story_5070_50701201_30_dialog_content = "危険を冒してでも、あの手この手と謀をめぐらせて、\n他人の物を奪おうとするんでしょ？",
  ui_story_5070_50701201_31_dialog_content = "最初は、火吹き蟹の図面。",
  ui_story_5070_50701201_32_dialog_content = "次にカラクリの部品の密輸。\nそして、海賊を垂らし込んでリン家の商船を襲った。",
  ui_story_5070_50701201_33_dialog_content = "今もまた同じことを繰り返して、\n燭陰火を盗んだ挙句、こんなヘンテコなカラクリに使う始末ときたわ。",
  ui_story_5070_50701201_34_dialog_content = "それについて、聞きたいことがあるの。",
  ui_story_5070_50701201_35_dialog_content = "何だ？",
  ui_story_5070_50701201_36_dialog_content = "乾雲は古来より公明正大、技で立身してきた流派よ。",
  ui_story_5070_50701201_37_dialog_content = "いつどこで、こんな卑劣な真似を覚えたのかしら？",
  ui_story_5070_50701201_38_dialog_content = "ふぅ…",
  ui_story_5070_50701201_39_dialog_content = "分かっていたか。",
  ui_story_5070_50701201_40_dialog_content = "あんたの頭の中は、いつも機巧のことばかりだ。\n俺のこの顔に見覚えはないか？",
  ui_story_5070_50701201_41_dialog_content = "久しぶりね、センキョク…私の可愛い妹弟子さん。",
  ui_story_5070_50701201_42_dialog_content = "テイト。",
  ui_story_5070_50701201_43_dialog_content = "あら、先輩とは呼んでくれないのね。\nやはり高名な璇璣卿ともなると、変わるものね。",
  ui_story_5070_50701201_44_dialog_content = "とうの昔に破門になった人を\n先輩と呼ぶいわれはないわ。",
  ui_story_5070_50701201_45_dialog_content = "最後だから、多少の生意気は許してあげるわ。",
  ui_story_5070_50701201_46_dialog_content = "何しろ、幼い頃から苦労知らずの門派一の天才が、\n破門になった私の作品に歯が立たないのだもの…",
  ui_story_5070_50701201_47_dialog_content = "口汚くなるのも当然よね。",
  ui_story_5070_50701201_48_dialog_content = "構わないわ。あなたが昔馴染みを嫌おうと、\n私はそんなことしないから。",
  ui_story_5070_50701201_49_dialog_content = "同門のよしみに免じて、\n大人しく負けを認めれば、逃がしてあげるわ。",
  ui_story_5070_50701201_50_dialog_content = "あなたは知らないでしょうけど…\nまもなく縦横家の時代がやってくるのよ！",
  ui_story_5070_50701201_51_dialog_content = "この先八大諸侯国には大きな嵐が吹き荒れるわ。\nあなたのような人材は引く手あまたでしょうね。",
  ui_story_5070_50701201_52_dialog_content = "この船は姉弟子からの餞別よ。どう？",
  ui_story_5070_50701201_53_dialog_content = "やっぱり。",
  ui_story_5070_50701201_54_dialog_content = "燭陰火だけじゃなく、蜃風号も狙っていたのね。",
  ui_story_5070_50701201_55_dialog_content = "でも、まさかこのまま私を見逃すとは思えないわ。",
  ui_story_5070_50701201_56_dialog_content = "まったく…相変わらず鋭いわね。",
  ui_story_5070_50701201_57_dialog_content = "だって、この船は明らかに蜃風号を真似て造ってあるもの。\nほとんどの構造は形を真似てるだけで、本物には程遠いけど。",
  ui_story_5070_50701201_58_dialog_content = "蜃風号の核は多くの名人が力を合わせて造ったものよ。\n私1人ではさすがに真似できないわ。",
  ui_story_5070_50701201_59_dialog_content = "私の任務はもともと、蜃風号の図面を入手しさえすればよかったの。",
  ui_story_5070_50701201_60_dialog_content = "でも、まるごともらえるなら、喜んでそうするのが道理でしょ？",
  ui_story_5070_50701201_61_dialog_content = "今の蜃風号は、妹弟子の突飛な発想のせいで、\nハチャメチャに改造されてしまっているけど…",
  ui_story_5070_50701201_62_dialog_content = "後始末は先輩である私がしておいてあげるわ。",
  ui_story_5070_50701201_63_dialog_content = "（任務ねぇ…）",
  ui_story_5070_50701201_64_dialog_content = "地下牢に入れられた口の堅いリン家の子弟どもと話すより、\nこうした方がずっと気分がいいわ。",
  ui_story_5070_50701201_65_dialog_content = "少し前にリン家の商船を襲ったのも、あなたなの？",
  ui_story_5070_50701201_66_dialog_content = "頭の回転が速いわね。",
  ui_story_5070_50701201_67_dialog_content = "この容貌を変え、声を真似る術は本当に便利よ。",
  ui_story_5070_50701201_68_dialog_content = "乗客、もしくは船員に扮して海に出れば、\n内側から船の防御を崩すことなど、簡単だもの。",
  ui_story_5070_50701201_69_dialog_content = "本当は蜃風号でも、同じ悲劇を起こそうと\n双閣港で綿密に計画を立てていたのだけれど…",
  ui_story_5070_50701201_70_dialog_content = "貨物室で、ある特別な物を見つけてしまったの。",
  ui_story_5070_50701201_71_dialog_content = "まさか、妹弟子があの伝説の燭陰火を本当に見つけるとは思わなかったわ。",
  ui_story_5070_50701201_72_dialog_content = "ちょうど私も、この百家の粋を集め、カラクリ獣の最高傑作と言えるこの子を造った後、\n相応しい動力源がなくて困っていたところだったの。",
  ui_story_5070_50701201_73_dialog_content = "運命が味方したというのは、こういうことを言うのね。",
  ui_story_5070_50701201_74_dialog_content = "はぁ…",
  ui_story_5070_50701201_75_dialog_content = "…なぜため息をつくのかしら？",
  ui_story_5070_50701201_76_dialog_content = "相変わらずね。",
  ui_story_5070_50701201_77_dialog_content = "ここまで追い詰められているのに、\nまだ門派一の天才、大機巧師を気取るつもり？",
  ui_story_5070_50701201_78_dialog_content = "自分の置かれている状況が分からないのかしら？",
  ui_story_5070_50701201_79_dialog_content = "たとえあなたでも、私のカラクリ獣に…私の最高傑作に、\n傷一つ付けられないわ！",
  ui_story_5070_50701201_80_dialog_content = "「私の」カラクリ獣？",
  ui_story_5070_50701201_81_dialog_content = "盗んだ設計に盗んだ核を埋め込んで、\n強力な部品を見境なくつなぎ合わせただけのカラクリが――",
  ui_story_5070_50701201_82_dialog_content = "「私の」作品？「私」って、いったい誰のこと？",
  ui_story_5070_50701201_83_dialog_content = "あら。あなた、いつから門派の古だぬきに似てきたの？",
  ui_story_5070_50701201_84_dialog_content = "機巧術は単なる技術にすぎないわ。\n強ければ、それでいい。それ以外のことなど、どうでもいいのよ。",
  ui_story_5070_50701201_85_dialog_content = "古だぬきたちも、この完璧な蠍獣を見れば、\n負けを認めざるを得ないわ！",
  ui_story_5070_50701201_86_dialog_content = "だから、あなたは機巧術を分かってないって言われるのよ。",
  ui_story_5070_50701201_87_dialog_content = "師匠たちがこれを見たら、\nもう破門にさえできないことを嘆くに決まってるわ。",
  ui_story_5070_50701201_88_dialog_content = "…あなたとは話をするだけ無駄だったわ。",
  ui_story_5070_50701201_89_dialog_content = "蠍、砕き潰しておしまい。\nカラクリ獣の真の力を見せつけてやるのよ！",
  ui_story_5070_50701201_90_dialog_content = "蜃風号に上がってきた海賊もようやく片付いたね。\n皆、大丈夫？",
  ui_story_5070_50701201_91_dialog_content = "私たちは大丈夫よ。ただ、船職人が大勢ケガをして、\n乗客も数名姿が見えないわ。",
  ui_story_5070_50701201_92_dialog_content = "先頃キュウが落水したのじゃが、まだ戻ってこぬ…",
  ui_story_5070_50701201_93_dialog_content = "殿下！ご無事でいらっしゃいますか！？",
  ui_story_5070_50701201_94_dialog_content = "キュウ！わらわの心配などよい。けがはどうじゃ？",
  ui_story_5070_50701201_95_dialog_content = "水を少し飲んでしまっただけでございます。",
  ui_story_5070_50701201_96_dialog_content = "それよりも、かような時こそおそばで殿下をお守りすべきところ、\nおそばを離れたのは、私の怠慢でございます。どうか罰をお与えくださいませ。",
  ui_story_5070_50701201_97_dialog_content = "何を申しておるのじゃ。お主ほどの者なら、あの白い光など避けられたものを、\nわらわをかばうあまり…",
  ui_story_5070_50701201_98_dialog_content = "罰することなどできようか？\nリンセイ、急ぎキュウのけがを診てもらえぬか…",
  ui_story_5070_50701201_99_dialog_content = "殿下、ありがとうございます。",
  ui_story_5070_50701201_100_dialog_content = "ふぅ。キュウは戻ってきたのう。\nあとは璇璣卿だけなのじゃが…",
  ui_story_5070_50701201_101_dialog_content = "センキョクなら、向かいの船にいる。",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_5070_50701201_103_dialog_content = "また、あの奇妙な白い光じゃ…",
  ui_story_5070_50701201_104_dialog_content = "何が起こってるの？ボクにも見せて！",
  ui_story_5070_50701201_105_dialog_content = "センキョクは何と戦ってるの？\nなんで逃げてばかりで、反撃しないのさ！？",
  ui_story_5070_50701201_106_dialog_content = "とてもじゃないけど、見ていられないよ。\nシュウさん、ボクたちも手を貸そう。",
  ui_story_5070_50701201_107_dialog_content = "ボクたちで助けてあげて、\n二度と「ボクちゃん」なんて呼ばせないから！",
  ui_story_5070_50701201_108_dialog_content = "その必要はなかろう。",
  ui_story_5070_50701201_109_dialog_content = "ウソでしょ？けんかでもしたの？\nシュウさんが人を助けないなんて！？",
  ui_story_5070_50701201_110_dialog_content = "そうではない。璇璣卿は苦戦などしておらぬ。",
  ui_story_5070_50701201_111_dialog_content = "うん、僕もそう思う…攻撃を避けるために、\n走り回ってるわけじゃなさそうだ。",
  ui_story_5070_50701201_112_dialog_content = "おそらく相手の攻撃を誘って、わざと船を壊してるんだ。",
  ui_story_5070_50701201_113_dialog_content = "カラクリ獣の足場を破壊しようとしてるんだ！",
  ui_story_5070_50701201_114_dialog_content = "でも、なんでそんなことするの？",
  ui_story_5070_50701201_115_dialog_content = "それは僕にも分からな…いや、分かるかも。",
  ui_story_5070_50701201_116_dialog_content = "蜃風号の強度じゃ、ありったけの材料を使って、\n船体を強固にしたとしても…",
  ui_story_5070_50701201_117_dialog_content = "燭陰火の全開出力には耐えられないと思うわ。",
  ui_story_5070_50701201_118_dialog_content = "甲板のデッカイ穴をふさがないってのは、まだいいとしても、\nそれを広げろってんだからよ。",
  ui_story_5070_50701201_119_dialog_content = "これじゃあ蜃風号の核が丸出しになっちまうじゃねえか。\n本当にこんなんでいいのか…？ソン、お前はどう思う？",
  ui_story_5070_50701201_120_dialog_content = "試験が失敗したことも、燭陰火で何かを企んでる人がいることも、\n今は誰にも言わないでほしいの。",
  ui_story_5070_50701201_121_dialog_content = "それは構わないけど…でも、それなら僕たちは、\nこれから何をするの？",
  ui_story_5070_50701201_122_dialog_content = "待つのよ。",
  ui_story_5070_50701201_123_dialog_content = "（…まさか…）",
  ui_story_5070_50701201_124_dialog_content = "（僕の推測があたってたとしたら…センキョク。\n君に僕を無謀だっていう資格はないよ）",
  ui_story_5070_50701201_125_dialog_content = "（君こそ無謀だよ！）",
  ui_story_5070_50701201_126_dialog_content = "PlayerName、何を見てるの？\n甲板にあいた大きな穴の中に何かあるの？",
  ui_story_5070_50701201_127_dialog_content = "今はまだ、ないよ。",
  ui_story_5070_50701201_128_dialog_content = "でも、すぐに中は埋まる。",
  ui_story_5070_50701201_129_dialog_content = "皆、手伝って！",
  ui_story_5070_50701201_130_dialog_content = "あのカラクリ獣を蜃風号におびき寄せるんだ！",
  ui_story_5070_50701201_131_dialog_content = "雷光奇制――",
  ui_story_5070_50701201_132_dialog_content = "無駄だと言ったでしょ？",
  ui_story_5070_50701201_133_dialog_content = "この蠍獣は、私があちこちを探し回って手に入れた、\n最高水準の設計の粋を集めた部品で造られているの。",
  ui_story_5070_50701201_134_dialog_content = "いくら攻撃しても無駄よ！",
  ui_story_5070_50701201_135_dialog_content = "そうとも限らないわよ。",
  ui_story_5070_50701201_136_dialog_content = "！？",
  ui_story_5070_50701201_137_dialog_content = "PlayerName？こっちを感知する余裕があるってことは、\nそっちは順調だったのね。",
  ui_story_5070_50701201_138_dialog_content = "あはは…シュウさんのおかげだよ…\nそれはまた今度話すとして…",
  ui_story_5070_50701201_139_dialog_content = "さっきの会話を聞いたよ。\nあの日の爆発は、あのニセのソンさんが起こしたものだったんだね。",
  ui_story_5070_50701201_140_dialog_content = "物を盗んで、雷に打たれたら、普通龍州では、\n報いを受けたって考えるんじゃないの？",
  ui_story_5070_50701201_141_dialog_content = "それなのに、運命が味方した、だなんて…\n雷に打たれるのがそれなら、僕は遠慮するな。",
  ui_story_5070_50701201_142_dialog_content = "ははは、本当よね。",
  ui_story_5070_50701201_143_dialog_content = "それに、あの人のカラクリ獣はひどい見た目だね。\nぐにゃぐにゃしてて、食欲も失せちゃう。",
  ui_story_5070_50701201_144_dialog_content = "だから申したであろう？きっと醜きものに違いないと。\nわらわの申した通りであったのう。",
  ui_story_5070_50701201_145_dialog_content = "…蜃風号があんなものと比べられるなんて、心外だわ。",
  ui_story_5070_50701201_146_dialog_content = "…いい加減にしてちょうだい！",
  ui_story_5070_50701201_147_dialog_content = "蠍！蜃風号に乗り込むのよ！\nあの身の程知らずの愚か者たちを片付けておしまい！",
  ui_story_5070_50701202_1_dialog_content = "私の造った…最強のカラクリ獣が…\nなぜなの…",
  ui_story_5070_50701202_2_dialog_content = "許さないわ――！",
  ui_story_5070_50701202_3_dialog_content = "まだやる気なの？確か、戦闘は苦手じゃなかったかしら？",
  ui_story_5070_50701202_4_dialog_content = "ふふっ…ふふっ、あはははは！",
  ui_story_5070_50701202_5_dialog_content = "喜ぶのはまだ早いわ！蠍獣のエネルギー核が何か忘れたの！？",
  ui_story_5070_50701202_6_dialog_content = "燭陰火よ！カラクリに無尽蔵の動力を授ける、\n真の天の力なのよ！",
  ui_story_5070_50701202_7_dialog_content = "蠍！起きなさい！まだ終わっていないわ！",
  ui_story_5070_50701202_8_dialog_content = "みんな、気を付けて！あいつ、また動き出したよ！",
  ui_story_5070_50701202_9_dialog_content = "まだやる気なのですか。殿下、おさがりを。",
  ui_story_5070_50701202_10_dialog_content = "あなたこそ、喜ぶのは早いわ。",
  ui_story_5070_50701202_11_dialog_content = "また、その眼つき…私を上から見下すなどもってのほかよ！\n私は――",
  ui_story_5070_50701202_12_dialog_content = "PlayerName！あの人の動きを止めて！ちょっとの間でいいの！",
  ui_story_5070_50701202_13_dialog_content = "強制感知！",
  ui_story_5070_50701202_14_dialog_content = "ううっ――！",
  ui_story_5070_50701202_15_dialog_content = "ひとまず、めまいを起こしたよ。\n皆、今のうちに蠍獣を中に落とすんだ！",
  ui_story_5070_50701202_16_dialog_content = "お、落とす…？落とすってどこに？\nまさか、甲板のあの穴じゃないよね？",
  ui_story_5070_50701202_17_dialog_content = "あれはただの穴じゃないのよ。",
  ui_story_5070_50701202_18_dialog_content = "蠍獣のために用意した、特等席なの。",
  ui_story_5070_50701202_19_dialog_content = "1、2、3！",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>ド――ン！</color>",
  ui_story_5070_50701202_21_dialog_content = "やっと落ちた。ずっごく重かったね。",
  ui_story_5070_50701202_22_dialog_content = "あとは私に任せてちょうだい。",
  ui_story_5070_50701202_23_dialog_content = "ちょっと手を加えれば、蜃風号の動力炉とつなげられるわ。",
  ui_story_5070_50701202_24_dialog_content = "うう…な、何をするの…！？",
  ui_story_5070_50701202_25_dialog_content = "腕利きのソンだった時、私が描いた蜃風号の改造設計図を見たでしょ？",
  ui_story_5070_50701202_26_dialog_content = "馬鹿な…あ、あんな改造、本当にできるわけがないわ。",
  ui_story_5070_50701202_27_dialog_content = "あんな構造で、蜃風号のような大きな船体は…",
  ui_story_5070_50701202_28_dialog_content = "燭陰火級のエネルギーを核にして、\nしかも全開で稼働させなければ無理よ。",
  ui_story_5070_50701202_29_dialog_content = "でも、蜃風号の船体を構成する材料では、\nそんな衝撃には到底耐えられない…",
  ui_story_5070_50701202_30_dialog_content = "その通りよ。蜃風号の材料だけなら、\n私の構想もただの絵空事よね。",
  ui_story_5070_50701202_31_dialog_content = "でも、あなたは最強のカラクリ獣を造り出すために…",
  ui_story_5070_50701202_32_dialog_content = "あのカラクリに燭陰火全開時の衝撃にも耐えられる、\n最上の材料を使ったのよね？",
  ui_story_5070_50701202_33_dialog_content = "ま、待って…ま、まさか…おかしくなったの！？\nそんなこと、できるはず…",
  ui_story_5070_50701202_34_dialog_content = "だから、機巧術を分かってないって言われるのよ。\n既存の設計に縛られてるようじゃ機巧術とは言えない。",
  ui_story_5070_50701202_35_dialog_content = "変幻自在、万難を排する――材料さえあれば、\n機巧術には無限の可能性が生まれるのよ。",
  ui_story_5070_50701202_36_dialog_content = "いったい何の話をしてるの？",
  ui_story_5070_50701202_37_dialog_content = "ボクちゃん、しっかりつかまってるのよ。\nすぐに分かるわ。",
  ui_story_5070_50701202_38_dialog_content = "一度限りの豪華絢爛カラクリショー、\n全身全霊で楽しんでちょうだい！",
  ui_story_5070_50701202_39_dialog_content = "燭陰火のエネルギーを蠍獣でろ過して、\n穏やかな動力に変える――",
  ui_story_5070_50701202_X39_dialog_content = "そして、蜃風号を…",
  ui_story_5070_50701202_40_dialog_content = "空に飛ばすの！",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>ボーッ――</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>まだ動ける者たちはセンキョクの指示のもと、臨時の船職人となり</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>船笛が鳴るのと同時に、\n改造を終えた蜃風号のすべてのカラクリを一斉に起動した</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>船体の振動と共に、船内のカラクリが互いにぶつかりあい、伸縮し…\n光力が船体の両側に伸びて、まるで無数の翼が生えたかのようだ</color>",
  ui_story_5070_50701202_45_dialog_content = "PlayerName、今よ！",
  ui_story_5070_50701202_46_dialog_content = "強制感知！",
  ui_story_5070_50701202_47_dialog_content = "（燭陰火を感知して、力を最大限まで引き上げる！\nそれから…）",
  ui_story_5070_50701202_48_dialog_content = "（蜃風号、出発！）",
  ui_story_5070_50701202_49_dialog_content = "あり得ない…あり得ないわ…！",
  ui_story_5070_50701202_50_dialog_content = "忌々しい…ただの偶然にすぎないわ！\nまだ…まだ、終わっていないわ！",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>バシャン！</color>",
  ui_story_5070_50701202_52_dialog_content = "あの人、海に飛び込んじゃったよ！？",
  ui_story_5070_50701202_53_dialog_content = "放っておきましょ。",
  ui_story_5070_50701202_54_dialog_content = "この翼もそう長くはもたないわ。\n今のうちに一気にこの海域を抜けないと。",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>バキッ――</color>",
  ui_story_5070_50701202_56_dialog_content = "（蜃風号が飛び立って、いくらもしないうちに、\n大きな負荷に耐えられず、カラクリが悲鳴を上げる音が聞こえた）",
  ui_story_5070_50701202_57_dialog_content = "（最後の全力疾走に入る頃、\nあれだけぶ厚かった光の翼も徐々に小さくなっていった）",
  ui_story_5070_50701202_58_dialog_content = "（でも、十分だった）",
  ui_story_5070_50701202_59_dialog_content = "お日様、そよ風、穏やかな海…ボクたち、成功したんだね！",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>バシャン！！</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>蜃風号が打ちつけられるように海面に戻った</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>辺りの海は穏やかで、渦巻く潮も存在しない</color>",
  ui_story_5070_50701202_63_dialog_content = "やった、成功だ！",
  ui_story_5070_50701202_64_dialog_content = "センキョク、君は本当にすごいね！",
  ui_story_5070_50701202_65_dialog_content = "機巧術がすごいのよ。",
  ui_story_5070_50701202_66_dialog_content = "でも、今回ばかりはその褒め言葉、\nありがたく受け取っておくわ。",
  ui_story_5070_50701202_67_dialog_content = "短時間ではあったけど、蜃風号も空を飛んだね。",
  ui_story_5070_50701202_68_dialog_content = "これでセンキョクも正真正銘、蜃風号のナビゲーターだ！",
  ui_story_5070_50701202_69_dialog_content = "そうね。",
  ui_story_5070_50701202_70_dialog_content = "この感覚…一生忘れないわ。",
  ui_story_5070_50701202_71_dialog_content = "（あの危険な海域を抜けると、センキョクはすぐに星座盤やら何やらを使って、\n蜃風号をもとの正しい軌道に戻した）",
  ui_story_5070_50701202_72_dialog_content = "（その翌日、そう遠くない海面にテイトのあの船の残骸が漂っているのを見つけた）",
  ui_story_5070_50701202_73_dialog_content = "かの船も、あの者の陰謀によって沈んだリン家の船と共に海に沈んだか。\n因果応報と言おうか。",
  ui_story_5070_50701202_74_dialog_content = "だが、テイトやそれを裏で支えていた者たちが、\n容易く逝くとは思えぬ。大人しく手を引くこともあるまい。",
  ui_story_5070_50701202_75_dialog_content = "また何か企むであろうな。",
  ui_story_5070_50701202_76_dialog_content = "どうあれ、こっちは迎え撃つだけのことです。\nどんな敵も、どんな襲撃も、カラクリで迎え撃ってみせます。",
  ui_story_5070_50701202_77_dialog_content = "既存のカラクリでダメなら、新しく造ればいいんです。",
  ui_story_5070_50701202_78_dialog_content = "テイトは昔、君の姉弟子だったんだよね？",
  ui_story_5070_50701202_79_dialog_content = "破門になったとはいえ、やっぱり大きな門派の弟子なんだね。",
  ui_story_5070_50701202_80_dialog_content = "蠍獣みたいなカラクリを造るなんて、\n普通の人はできないよ。",
  ui_story_5070_50701202_81_dialog_content = "でも、どうして他人に雇われて海賊になったり、\n密輸に手を染めたりしたのかな？",
  ui_story_5070_50701202_82_dialog_content = "思い当たることがあるの。",
  ui_story_5070_50701202_83_dialog_content = "でも…調べた先に、\n果たしてどんな結果が待ってるのか分からないわ。",
  ui_story_5070_50701202_84_dialog_content = "テイトはたくさんのカラクリ技術を学んだけど、\n機巧術が何か、まったく分かっていないの。",
  ui_story_5070_50701202_85_dialog_content = "何百年もの技の蓄積と何千年もの決意の結晶たる技術は――",
  ui_story_5070_50701202_86_dialog_content = "陰謀や盗みで得られるものではないし、\n理解しようのないものよ。",
  ui_story_5070_50701202_87_dialog_content = "センキョク、お主の申したものを持ってきたぞ。",
  ui_story_5070_50701202_88_dialog_content = "じゃが、何しろ船の上じゃ。\n叔父上と交わした文はいくらももっておらぬ。",
  ui_story_5070_50701202_89_dialog_content = "それはそうと、なにゆえ、かようなものが必要なのじゃ？",
  ui_story_5070_50701202_90_dialog_content = "それは…見てみないと分かりません。",
  ui_story_5070_50701202_91_dialog_content = "そういえば、キュウさんの具合はいかがですか？",
  ui_story_5070_50701202_92_dialog_content = "気遣い感謝する。",
  ui_story_5070_50701202_93_dialog_content = "リンセイの見立てでは、数日休めばよくなるそうじゃ。",
  ui_story_5070_50701202_94_dialog_content = "（いつもと変わらない、楽しい会話が戻ってきた）",
  ui_story_5070_50701202_95_dialog_content = "（でも、センキョクは手紙を丁寧にしまっただけで…）",
  ui_story_5070_50701202_X95_dialog_content = "（「なぜ手紙が必要なのか」という問いには、答えなかった）",
  ui_story_5070_50701301_1_dialog_content = "（船上での最後の2日間はあっという間に過ぎてしまった）",
  ui_story_5070_50701301_2_dialog_content = "（たくさんの危機に直面し、たくさんの戦闘を経て、\n皆身も心も疲れ切っていた）",
  ui_story_5070_50701301_3_dialog_content = "（幸い、ようやく疲れも抜けてきた頃――\n龍州大陸が見えた）",
  ui_story_5070_50701301_4_dialog_content = "今回は本当に波乱に満ちた航海でしたが、\n何とか無事に到着できました。",
  ui_story_5070_50701301_5_dialog_content = "蜃風号、無事帰港しました。航海、完了です。",
  ui_story_5070_50701301_6_dialog_content = "蜃風号を代表し、皆様のご協力に感謝いたします。",
  ui_story_5070_50701301_7_dialog_content = "お主自身の功労も忘れてはならぬ。",
  ui_story_5070_50701301_8_dialog_content = "船がつつがなく帰港し、航路が再び通じたのじゃ。\nわらわたちの務めだけでなく、蜃風号もまた務めを果たしたのう。",
  ui_story_5070_50701301_9_dialog_content = "タンドウ殿下、先程知らせが参りまして、迎えの済の国の使者が\n港で殿下のご到着をお待ちとのことです。",
  ui_story_5070_50701301_10_dialog_content = "海の向こう側の見聞と通商の約を携えて帰ったのじゃ。\nむろん、早々に朝廷に向かう所存じゃ。",
  ui_story_5070_50701301_11_dialog_content = "しばらく宴の誘いが絶えぬであろうな。",
  ui_story_5070_50701301_12_dialog_content = "覚悟しておくのじゃぞ、PlayerName。",
  ui_story_5070_50701301_13_dialog_content = "えっ？僕？",
  ui_story_5070_50701301_14_dialog_content = "あ…そうだった…アストラの使節として\n龍州に来たってこと、忘れてたよ！",
  ui_story_5070_50701301_15_dialog_content = "ど、どうしよう…急に緊張してきちゃった…",
  ui_story_5070_50701301_16_dialog_content = "ホホホ、そう硬くなることはない。\n龍州へ物見遊山に参ったとでも思えばよい。",
  ui_story_5070_50701301_17_dialog_content = "やっと帰ってこられたね。\n一時はアストラで一生暮らすことになるのかと思ったよ…",
  ui_story_5070_50701301_18_dialog_content = "龍州を離れて、たったの半年だというのに、\nここもすっかり変わってしまった気がするな。",
  ui_story_5070_50701301_19_dialog_content = "しみじみするのは後にしようよ。\nまずは、この後どうするかを決めよう。",
  ui_story_5070_50701301_20_dialog_content = "おいしいものを食べに行く？それとも休む？",
  ui_story_5070_50701301_21_dialog_content = "リン家に戻る。",
  ui_story_5070_50701301_22_dialog_content = "タンドウ殿下らの尽力のおかげで、\nリン家の密輸は冤罪だと証明できるとしても――",
  ui_story_5070_50701301_23_dialog_content = "それはそれで、やらねばならんことが山積みだ。",
  ui_story_5070_50701301_24_dialog_content = "ご当主は…きっとそれがしを待っている！",
  ui_story_5070_50701301_25_dialog_content = "あ、ちょっと待ってよ！",
  ui_story_5070_50701301_26_dialog_content = "心配はいらないわ。",
  ui_story_5070_50701301_27_dialog_content = "着岸してすぐに状況を伝え、\n船舶府に証拠と金銭を持って行かせたわ。",
  ui_story_5070_50701301_28_dialog_content = "当主はおそらくすでに釈放されているはずよ。\nすぐに再会できるわ。",
  ui_story_5070_50701301_29_dialog_content = "見てごらんなさい。",
  ui_story_5070_50701301_30_dialog_content = "…センキョクのせいだよ。\nシュウさんの車椅子、速くてかなわないや。",
  ui_story_5070_50701301_31_dialog_content = "シュウ大兄！",
  ui_story_5070_50701301_32_dialog_content = "リンか？",
  ui_story_5070_50701301_33_dialog_content = "足が不自由になったそれがしが、\nまさかご当主に出迎えてもらえるとは思わなんだ。",
  ui_story_5070_50701301_34_dialog_content = "さようなことを申されるな…\nこちらが何と言ってよいか、分からなくなるではないか。",
  ui_story_5070_50701301_35_dialog_content = "先に礼を申すべきか、それとも詫びるべきか…",
  ui_story_5070_50701301_36_dialog_content = "それがしにかしこまった挨拶などいらぬ。",
  ui_story_5070_50701301_37_dialog_content = "それよりも…先にリンセイと船長殿を迎えに参られよ。",
  ui_story_5070_50701301_38_dialog_content = "それがしは…ご当主のつつがなき姿を見られただけで十分だ。",
  ui_story_5070_50701301_39_dialog_content = "キュウよ。鄴の国の駅站に文を届けてくれぬか？",
  ui_story_5070_50701301_40_dialog_content = "務めを果たし、無事戻ったことを知らせねばならぬ。",
  ui_story_5070_50701301_41_dialog_content = "かしこまりました。皆様もお喜びになることでしょう。",
  ui_story_5070_50701301_42_dialog_content = "PlayerName、いかがしたのじゃ？",
  ui_story_5070_50701301_43_dialog_content = "タンドウ、キュウ、シュウさん、センキョク、それから僕…\n全員降りて来たよね？",
  ui_story_5070_50701301_44_dialog_content = "でも、どうしてだろう？何か忘れてる気がする。",
  ui_story_5070_50701301_45_dialog_content = "まあ、いいか。たぶん大したことじゃないよ。行こう。",
  ui_story_5070_50701301_46_dialog_content = "センキョク様、木牛流馬はここに置きゃあいいですかね？",
  ui_story_5070_50701301_47_dialog_content = "ええ。ありがとう。",
  ui_story_5070_50701301_48_dialog_content = "礼なんざ要りませんよ。俺たちが無事戻ってこられたのも、\nセンキョク様のおかげだ。それに色々学ばせてもらいやしたからね。",
  ui_story_5070_50701301_49_dialog_content = "次に海に出る時も、ご一緒してえもんです。",
  ui_story_5070_50701301_50_dialog_content = "そうね。また会えるといいわね。",
  ui_story_5070_50701301_X50_dialog_content = "あら？これは…",
  ui_story_5070_50701301_X51_dialog_content = "長いこと離れてたから忘れてたわ。\n済の国の江南岸は一年中春みたいな所だったわね。",
  ui_story_5070_50701301_X52_dialog_content = "私…本当に探し物を見つけて、龍州に戻ってきたのね…",
  ui_story_5070_50701301_51_dialog_content = "…",
  ui_story_5070_50701301_52_dialog_content = "まあ、いいじゃない。この世がいかに広いか、\n海がいかに深いか、十分見て来たんだから。",
  ui_story_5070_50701301_53_dialog_content = "今は、もっと大事なことがあるはずよね。",
  ui_story_5070_50701301_54_dialog_content = "あら？この木牛流馬の中…",
  ui_story_5070_50701301_55_dialog_content = "おおっと！",
  ui_story_5070_50701301_56_dialog_content = "もう朝ですかねぇ？おはようございます。",
  ui_story_5070_50701301_57_dialog_content = "…木牛流馬の中に隠れて、何してるの？",
  ui_story_5070_50701301_58_dialog_content = "何って、そりゃあ…おおっと。\nすみませんが、手を貸してくれませんかね？",
  ui_story_5070_50701301_59_dialog_content = "いやはや、木牛流馬の中ってのは窮屈ですねぇ。\n身体じゅう痛くてたまりませんよ。",
  ui_story_5070_50701301_60_dialog_content = "今回の遠出では、嵐や暗鬼ばかりか、海賊にまで遭うとは。\nいやはや、ひどい目に遭ったもんです。",
  ui_story_5070_50701301_61_dialog_content = "前もって、旅の行く末を占っておいて幸いでしたよ。",
  ui_story_5070_50701301_62_dialog_content = "陰の丑と陰の午の卦象を何日も研究しましてねぇ。\nようやく分かったんですよ。おそらく、この木牛流馬のことだってねぇ。",
  ui_story_5070_50701301_63_dialog_content = "まさに絶好の隠れ場所でした。\nでなけりゃ、この災難続きの航海で命を落とすところでしたからねぇ。",
  ui_story_5070_50701301_64_dialog_content = "はあ…",
  ui_story_5070_50701301_65_dialog_content = "そうだ。隠れ場所をお借りしたんです。\nお返しをしなきゃなりませんねぇ。",
  ui_story_5070_50701301_66_dialog_content = "どうです？ただで占って差し上げますよ！？",
  ui_story_5070_50701301_67_dialog_content = "結構よ。",
  ui_story_5070_50701301_68_dialog_content = "私たち機巧師は運命や占いよりも、\n自分のつくったカラクリを信じるの。",
  ui_story_5070_50701301_69_dialog_content = "それに不吉な結果が出たからといって、\nやらなきゃいけないことは結局、やらなきゃいけないでしょ？",
  ui_story_5070_50701301_70_dialog_content = "なるほど。では、幸運を願ってますよ。",
  ui_story_5070_50701301_71_dialog_content = "僕はここで失礼しますね。",
  ui_story_5070_50701301_72_dialog_content = "（どれどれ、さっき木牛流馬の中で引いたのは…）",
  ui_story_5070_50701301_73_dialog_content = "（陽の寅に陰の辰…？これは面白いですねぇ）",
  ui_story_5070_50701301_74_dialog_content = "（船の上では、死した牛に木の馬――暗にありて現れず…）",
  ui_story_5070_50701301_X74_dialog_content = "（ようやく危うい所を抜けたと思ったら、\n今度は「凶の相露わる」と出ましたか）",
  ui_story_5070_50701301_75_dialog_content = "（危険なものには触れるなと注意して回ってた人物が、\n自ら虎穴に入ろうとしてるってとこですかねぇ？）",
  ui_story_5070_50701301_76_dialog_content = "文をお願いします。",
  ui_story_5070_50701301_77_dialog_content = "今日もお手紙ですか？\n2通どちらも鄴の国宛てですね？",
  ui_story_5070_50701301_78_dialog_content = "期日通り届けます。安心してください。",
  ui_story_5070_50701301_79_dialog_content = "<color=#e8d9bb>駅站の近くでは</color>",
  ui_story_5070_50701301_80_dialog_content = "霜刃様が郡主を無事龍州に連れ戻ったとご報告を。",
  ui_story_5070_50701301_81_dialog_content = "駅站の者も片付けるのだ。\n障害はこちらで除いておけ。"
}
return config
